-- Rights chains: synthetic profiles only carry synthetic evidence and never
-- public display; real profiles never claim synthetic evidence; knowledge time
-- never moves backwards along a chain.
CREATE FUNCTION public.predictive_rights_check() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE profile_purpose text;
BEGIN
  -- Serializes with predictive_record_feature_run() for this profile: a recording
  -- waits for an uncommitted rights change and then sees it.
  PERFORM pg_catalog.pg_advisory_xact_lock(520053, pg_catalog.hashtext(NEW.profile_id));
  SELECT purpose INTO profile_purpose FROM public.predictive_source_profiles WHERE id = NEW.profile_id;
  IF (profile_purpose = 'synthetic-test') <> (NEW.evidence_kind = 'synthetic')
      OR (profile_purpose = 'synthetic-test' AND 'public-display' = ANY(NEW.allowed_uses)) THEN
    RAISE EXCEPTION 'predictive-synthetic-rights-refused' USING ERRCODE = '23514';
  END IF;
  IF NEW.predecessor_id IS NOT NULL AND EXISTS (SELECT 1 FROM public.predictive_rights_decisions p
      WHERE p.id = NEW.predecessor_id AND p.decided_at > NEW.decided_at) THEN
    RAISE EXCEPTION 'predictive-rights-order-refused' USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END
$$;
CREATE TRIGGER predictive_rights_validate BEFORE INSERT ON public.predictive_rights_decisions FOR EACH ROW EXECUTE FUNCTION public.predictive_rights_check();

-- absence-v1, mirroring validateAbsences() in code: the prior row is the
-- absence's predecessor with identical routing; a complete, full capture of the
-- same profile and filter covers the prior row's scope and lacks the row; and
-- times run prior capture <= covering capture <= absence capture.
CREATE FUNCTION public.predictive_absence_valid(absence_id text) RETURNS boolean LANGUAGE plpgsql STABLE AS $$
DECLARE a public.predictive_observations; p public.predictive_observations; cov public.predictive_captures;
  ca public.predictive_artifacts; pa public.predictive_artifacts; pc public.predictive_captures; ac public.predictive_captures; field text;
BEGIN
  SELECT * INTO a FROM public.predictive_observations WHERE id = absence_id;
  SELECT * INTO p FROM public.predictive_observations WHERE id = a.predecessor_id;
  IF p.id IS NULL OR p.id <> a.data->>'priorObservationId' OR p.kind = 'source-row-absent' OR p.entity_key <> a.data->>'priorEntityKey' THEN RETURN false; END IF;
  FOREACH field IN ARRAY ARRAY['gameId','playerId','teamId','season','seasonType'] LOOP
    IF (p.data ? field) <> (a.data ? field) OR (p.data->field) IS DISTINCT FROM (a.data->field) THEN RETURN false; END IF;
  END LOOP;
  SELECT c.* INTO cov FROM public.predictive_captures c JOIN public.predictive_ingestion_runs r ON r.id = c.run_id
    WHERE c.id = a.data->>'coveringCaptureId' AND c.state = 'published' AND r.status = 'published'
      AND c.body_complete AND c.header_verified AND c.parser_succeeded;
  IF cov.id IS NULL THEN RETURN false; END IF;
  SELECT * INTO ca FROM public.predictive_artifacts WHERE id = cov.artifact_id;
  IF ca.profile_id <> a.profile_id OR ca.scope_kind <> a.data->>'scopeKind' OR ca.scope_season IS DISTINCT FROM (a.data->>'scopeSeason')::integer
    OR ca.scope_week IS DISTINCT FROM (a.data->>'scopeWeek')::integer OR ca.scope_game_id IS DISTINCT FROM (a.data->>'scopeGameId')::uuid
    OR ca.scope_filter IS DISTINCT FROM a.data->>'scopeFilter' THEN RETURN false; END IF;
  SELECT c.* INTO pc FROM public.predictive_artifact_observations l JOIN public.predictive_captures c ON c.artifact_id = l.artifact_id
    JOIN public.predictive_ingestion_runs r ON r.id = c.run_id
    WHERE l.observation_id = p.id AND c.state = 'published' AND r.status = 'published'
    ORDER BY c.ingested_at, c.available_at, c.captured_at, c.id COLLATE "C" LIMIT 1;
  SELECT * INTO pa FROM public.predictive_artifacts WHERE id = pc.artifact_id;
  IF NOT (ca.retrieval_kind = 'full' AND ca.profile_id = pa.profile_id AND ca.scope_filter IS NOT DISTINCT FROM pa.scope_filter
      AND ca.scope_kind <> 'manual' AND pa.scope_kind <> 'manual' AND (
        ca.scope_kind = 'all-seasons'
        OR (ca.scope_kind = 'season-file' AND ca.scope_season IS NOT DISTINCT FROM pa.scope_season AND pa.scope_kind IN ('season-file','week-file','game'))
        OR (ca.scope_kind = 'week-file' AND pa.scope_kind IN ('week-file','game') AND ca.scope_season IS NOT DISTINCT FROM pa.scope_season
          AND ca.scope_week IS NOT DISTINCT FROM pa.scope_week)
        OR (ca.scope_kind = 'game' AND pa.scope_kind = 'game' AND ca.scope_season IS NOT DISTINCT FROM pa.scope_season
          AND ca.scope_game_id IS NOT DISTINCT FROM pa.scope_game_id))) THEN RETURN false; END IF;
  IF EXISTS (SELECT 1 FROM public.predictive_artifact_observations l JOIN public.predictive_observations o ON o.id = l.observation_id
      WHERE l.artifact_id = ca.id AND o.source_key = a.source_key) THEN RETURN false; END IF;
  SELECT c.* INTO ac FROM public.predictive_artifact_observations l JOIN public.predictive_captures c ON c.artifact_id = l.artifact_id
    WHERE l.observation_id = a.id AND c.state = 'published' ORDER BY c.ingested_at, c.available_at, c.captured_at, c.id COLLATE "C" LIMIT 1;
  RETURN cov.available_at >= pc.available_at AND cov.ingested_at >= pc.ingested_at
    AND ac.available_at >= cov.available_at AND ac.ingested_at >= cov.ingested_at;
END
$$;

CREATE FUNCTION public.predictive_publication_check() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE affected text[];
BEGIN
  IF TG_TABLE_NAME = 'predictive_captures' THEN
    IF NEW.state = 'published' THEN
      IF (SELECT status FROM public.predictive_ingestion_runs WHERE id = NEW.run_id) <> 'published'
          OR (SELECT retrieval_kind FROM public.predictive_artifacts WHERE id = NEW.artifact_id) <> 'full' THEN
        RAISE EXCEPTION 'predictive-publication-invalid' USING ERRCODE = '23514';
      END IF;
      -- Historical authorization: only rights known when the bytes were captured.
      IF NOT public.predictive_rights_allow((SELECT profile_id FROM public.predictive_artifacts WHERE id = NEW.artifact_id),
          NEW.captured_at, NEW.captured_at, 'internal-research') THEN
        RAISE EXCEPTION 'predictive-rights-not-in-force' USING ERRCODE = '23514';
      END IF;
      IF NOT EXISTS (SELECT 1 FROM public.predictive_run_rights rr WHERE rr.run_id = NEW.run_id AND rr.rights_decision_id =
          public.predictive_rights_in_force((SELECT profile_id FROM public.predictive_artifacts WHERE id = NEW.artifact_id), NEW.captured_at, NEW.captured_at)) THEN
        RAISE EXCEPTION 'predictive-run-rights-missing' USING ERRCODE = '23514';
      END IF;
    END IF;
    IF (SELECT p.purpose FROM public.predictive_artifacts a JOIN public.predictive_source_profiles p ON p.id = a.profile_id
        WHERE a.id = NEW.artifact_id) = 'synthetic-test' AND NOT public.predictive_harness_session() THEN
      RAISE EXCEPTION 'predictive-synthetic-outside-harness' USING ERRCODE = '23514';
    END IF;
    SELECT array_agg(observation_id) INTO affected FROM public.predictive_artifact_observations WHERE artifact_id = NEW.artifact_id;
  ELSIF TG_TABLE_NAME = 'predictive_observations' THEN affected := ARRAY[NEW.id];
  ELSE affected := ARRAY[NEW.observation_id]; END IF;
  IF EXISTS (SELECT 1 FROM public.predictive_artifact_observations l
      JOIN public.predictive_observations o ON o.id = l.observation_id
      JOIN public.predictive_artifacts a ON a.id = l.artifact_id
      JOIN public.predictive_source_profiles p ON p.id = a.profile_id
      WHERE o.id = ANY(affected) AND (o.profile_id <> a.profile_id OR NOT o.kind = ANY(p.evidence_kinds) OR a.retrieval_kind <> 'full')) OR
    EXISTS (SELECT 1 FROM public.predictive_observations o WHERE o.id = ANY(affected) AND NOT EXISTS (
      SELECT 1 FROM public.predictive_artifact_observations l JOIN public.predictive_captures c ON c.artifact_id = l.artifact_id
      WHERE l.observation_id = o.id AND c.state = 'published')) THEN
    RAISE EXCEPTION 'predictive-publication-invalid' USING ERRCODE = '23514';
  END IF;
  -- bridge-v1: both ambiguity directions, at overlapping knowledge times and
  -- (for players) effective windows. Later corrections cannot hide old conflicts.
  IF EXISTS (WITH known AS (
      SELECT o.id, o.predecessor_id, min(greatest(c.available_at, c.ingested_at)) AS since
      FROM public.predictive_observations o JOIN public.predictive_artifact_observations l ON l.observation_id = o.id
      JOIN public.predictive_captures c ON c.artifact_id = l.artifact_id
      JOIN public.predictive_ingestion_runs r ON r.id = c.run_id
      WHERE c.state = 'published' AND r.status = 'published' GROUP BY o.id, o.predecessor_id
    ), windows AS (
      SELECT k.id, k.since, coalesce(min(n.since), 'infinity'::timestamptz) AS until
      FROM known k LEFT JOIN known n ON n.predecessor_id = k.id GROUP BY k.id, k.since
    ) SELECT 1 FROM public.predictive_observations o JOIN windows ow ON ow.id = o.id
      JOIN public.predictive_observations h ON h.kind = o.kind AND h.profile_id = o.profile_id AND h.id <> o.id
        AND h.data->>'provider' = o.data->>'provider'
      JOIN windows hw ON hw.id = h.id AND hw.since < ow.until AND ow.since < hw.until
      WHERE o.id = ANY(affected) AND o.kind IN ('player-bridge','game-bridge')
        AND ((o.kind = 'game-bridge' AND ((h.entity_key = o.entity_key AND h.game_id <> o.game_id)
            OR (h.entity_key <> o.entity_key AND h.game_id = o.game_id)))
          OR (o.kind = 'player-bridge' AND ((h.entity_key = o.entity_key AND h.player_id <> o.player_id)
            OR (h.entity_key <> o.entity_key AND h.player_id = o.player_id))
            AND (h.data->>'effectiveFrom')::timestamptz < (o.data->>'effectiveTo')::timestamptz
            AND (o.data->>'effectiveFrom')::timestamptz < (h.data->>'effectiveTo')::timestamptz))) THEN
    RAISE EXCEPTION 'predictive-bridge-ambiguous' USING ERRCODE = '23514';
  END IF;
  IF EXISTS (SELECT 1 FROM public.predictive_observations o WHERE o.id = ANY(affected) AND o.kind = 'source-row-absent'
      AND NOT public.predictive_absence_valid(o.id)) THEN
    RAISE EXCEPTION 'predictive-absence-invalid' USING ERRCODE = '23514';
  END IF;
  -- Every correction's first usable capture must follow an independently
  -- usable predecessor in the same source chain.
  IF EXISTS (SELECT 1 FROM public.predictive_observations o
    JOIN public.predictive_artifact_observations l ON l.observation_id = o.id
    JOIN public.predictive_captures c ON c.artifact_id = l.artifact_id AND c.state = 'published'
    WHERE o.id = ANY(affected) AND o.predecessor_id IS NOT NULL AND NOT EXISTS (
      SELECT 1 FROM public.predictive_artifact_observations pl JOIN public.predictive_captures pc ON pc.artifact_id = pl.artifact_id
      WHERE pl.observation_id = o.predecessor_id AND pc.state = 'published'
        AND pc.available_at <= c.available_at AND pc.ingested_at <= c.ingested_at)) THEN
    RAISE EXCEPTION 'predictive-correction-time-invalid' USING ERRCODE = '23514';
  END IF;
  IF EXISTS (WITH RECURSIVE chain AS (
    SELECT id, predecessor_id, ARRAY[id] AS path, false AS cycle FROM public.predictive_observations WHERE id = ANY(affected) AND predecessor_id IS NOT NULL
    UNION ALL SELECT c.id, o.predecessor_id, c.path || o.id, o.id = ANY(c.path)
      FROM chain c JOIN public.predictive_observations o ON o.id = c.predecessor_id WHERE NOT c.cycle)
    SELECT 1 FROM chain WHERE cycle) THEN
    RAISE EXCEPTION 'predictive-correction-cycle' USING ERRCODE = '23514';
  END IF;
  RETURN NULL;
END
$$;
CREATE CONSTRAINT TRIGGER predictive_check_captures AFTER INSERT ON public.predictive_captures DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION public.predictive_publication_check();
CREATE CONSTRAINT TRIGGER predictive_check_observations AFTER INSERT ON public.predictive_observations DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION public.predictive_publication_check();
CREATE CONSTRAINT TRIGGER predictive_check_links AFTER INSERT ON public.predictive_artifact_observations DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION public.predictive_publication_check();

-- Cross-source decisions. A decision never edits a provider's revision; it
-- selects among provider heads for one fact, or records a conflict. Inputs must
-- have been usable by decided_at. Mirrors validateDecisions() in code.
-- An explicit permission for one profile's player bridges, in one provider
-- namespace, to resolve identities for another profile's stats rows.
CREATE TABLE public.predictive_profile_identity_links (
  id text PRIMARY KEY CHECK (length(id) BETWEEN 1 AND 256 AND id !~ '[\x01-\x1f\x7f]'),
  stats_profile_id text NOT NULL REFERENCES public.predictive_source_profiles(id),
  bridge_profile_id text NOT NULL REFERENCES public.predictive_source_profiles(id),
  provider text NOT NULL CHECK (provider ~ '^[a-z0-9][a-z0-9-]{0,31}$'),
  decided_at timestamptz NOT NULL CHECK (isfinite(decided_at) AND decided_at = date_trunc('milliseconds', decided_at)),
  UNIQUE (stats_profile_id, bridge_profile_id, provider)
);
CREATE TRIGGER predictive_identity_links_immutable BEFORE UPDATE OR DELETE ON public.predictive_profile_identity_links FOR EACH ROW EXECUTE FUNCTION public.predictive_append_only();
CREATE TRIGGER predictive_identity_links_no_truncate BEFORE TRUNCATE ON public.predictive_profile_identity_links FOR EACH STATEMENT EXECUTE FUNCTION public.predictive_append_only();

-- An observation is usable at t when a published capture of a published run made
-- it available and ingested by t. Positional parameters: in SQL functions a
-- column name would shadow a parameter of the same name.
CREATE FUNCTION public.predictive_observation_usable(observation_id text, t timestamptz) RETURNS boolean LANGUAGE sql STABLE AS $$
  SELECT EXISTS (SELECT 1 FROM public.predictive_artifact_observations l JOIN public.predictive_captures c ON c.artifact_id = l.artifact_id
    JOIN public.predictive_ingestion_runs ru ON ru.id = c.run_id WHERE l.observation_id = $1 AND c.state = 'published'
      AND ru.status = 'published' AND c.available_at <= $2 AND c.ingested_at <= $2)
$$;

CREATE FUNCTION public.predictive_decision_valid(kind text, outcome jsonb) RETURNS boolean
LANGUAGE plpgsql IMMUTABLE STRICT AS $$
BEGIN
  IF jsonb_typeof(outcome) <> 'object' THEN RETURN false; END IF;
  IF kind = 'participation' THEN
    RETURN (SELECT array_agg(key ORDER BY key) FROM jsonb_object_keys(outcome) key) = ARRAY['state']
      AND (outcome->>'state' IN ('offensive-participant','zero-offensive-participation','inactive-or-dnp','unresolved','conflicting')) IS TRUE;
  END IF;
  IF kind = 'snap-source-compatibility' THEN
    RETURN (SELECT array_agg(key ORDER BY key) FROM jsonb_object_keys(outcome) key) = ARRAY['overlapGames','result']
      AND (outcome->>'result' IN ('compatible','incompatible','insufficient-overlap')) IS TRUE
      AND public.predictive_integer(outcome->'overlapGames', 0, 4096)
      AND ((outcome->>'result' = 'insufficient-overlap') = ((outcome->>'overlapGames')::integer = 0));
  END IF;
  IF kind = 'completion' THEN
    RETURN (SELECT array_agg(key ORDER BY key) FROM jsonb_object_keys(outcome) key) = ARRAY['actualEnd','completionObservedAt','state']
      AND (outcome->>'state' IN ('scheduled','in-progress','completed','suspended','postponed','conflicting')) IS TRUE
      AND outcome->'actualEnd' = 'null'::jsonb
      AND CASE WHEN outcome->>'state' = 'completed' THEN public.predictive_instant(outcome->>'completionObservedAt')
        ELSE outcome->'completionObservedAt' = 'null'::jsonb END;
  END IF;
  IF kind <> 'reconciliation' OR
    (SELECT array_agg(key ORDER BY key) FROM jsonb_object_keys(outcome) key) IS DISTINCT FROM ARRAY['result','rule','selectedObservationId']
    THEN RETURN false; END IF;
  RETURN (outcome->>'result' IN ('selected','conflict','insufficient-sources')) IS TRUE
    AND (outcome->>'rule' IN ('single-source','sources-agree','material-discrepancy','no-candidates')) IS TRUE
    AND CASE WHEN outcome->>'result' = 'selected' THEN public.predictive_text(outcome->'selectedObservationId')
      ELSE outcome->'selectedObservationId' = 'null'::jsonb END;
EXCEPTION WHEN OTHERS THEN RETURN false;
END
$$;

CREATE TABLE public.predictive_decisions (
  id text PRIMARY KEY CHECK (length(id) BETWEEN 1 AND 256 AND id !~ '[\x01-\x1f\x7f]'),
  kind text NOT NULL CHECK (kind IN ('reconciliation','completion','participation','snap-source-compatibility')),
  entity_key text NOT NULL CHECK (length(entity_key) BETWEEN 1 AND 300),
  policy_id text NOT NULL CHECK (policy_id ~ '^[a-z0-9-]+-v[0-9]+$'),
  mode text NOT NULL CHECK (mode IN ('production-research','synthetic-proof')),
  outcome jsonb NOT NULL,
  run_id text NOT NULL REFERENCES public.predictive_ingestion_runs(id),
  decided_at timestamptz NOT NULL CHECK (isfinite(decided_at) AND decided_at = date_trunc('milliseconds', decided_at)),
  predecessor_id text,
  CHECK (public.predictive_decision_valid(kind, outcome) IS TRUE),
  CHECK (kind <> 'reconciliation' OR (policy_id = 'reconciliation-v1' AND entity_key LIKE 'reconciliation:%')),
  CHECK (kind <> 'participation' OR (policy_id = 'participation-v1'
    AND entity_key ~ '^participation:[a-f0-9]{8}-[a-f0-9]{4}-4[a-f0-9]{3}-[89ab][a-f0-9]{3}-[a-f0-9]{12}:00-[0-9]{7}$')),
  CHECK (kind <> 'snap-source-compatibility' OR (policy_id = 'snap-compatibility-v1'
    AND entity_key ~ '^snap-source-compatibility:[a-z0-9][a-z0-9.-]{2,127}:[a-z0-9][a-z0-9.-]{2,127}$'
    AND split_part(entity_key, ':', 2) COLLATE "C" < split_part(entity_key, ':', 3) COLLATE "C")),
  CHECK (kind <> 'completion' OR (policy_id = 'event-completion-v1' AND entity_key ~ '^completion:[a-f0-9]{8}-[a-f0-9]{4}-4[a-f0-9]{3}-[89ab][a-f0-9]{3}-[a-f0-9]{12}$')),
  CHECK (predecessor_id IS DISTINCT FROM id),
  UNIQUE (id, kind, entity_key, policy_id),
  FOREIGN KEY (predecessor_id, kind, entity_key, policy_id)
    REFERENCES public.predictive_decisions(id, kind, entity_key, policy_id) DEFERRABLE INITIALLY DEFERRED
);
CREATE UNIQUE INDEX predictive_decisions_one_successor ON public.predictive_decisions (predecessor_id) WHERE predecessor_id IS NOT NULL;
CREATE INDEX predictive_decisions_entity_idx ON public.predictive_decisions (kind, entity_key, policy_id, decided_at);

CREATE TABLE public.predictive_decision_inputs (
  decision_id text NOT NULL REFERENCES public.predictive_decisions(id),
  observation_id text NOT NULL REFERENCES public.predictive_observations(id),
  role text NOT NULL CHECK (role IN ('candidate','selected','marker','evidence')),
  PRIMARY KEY (decision_id, observation_id)
);
CREATE INDEX predictive_decision_inputs_reverse_idx ON public.predictive_decision_inputs (observation_id, decision_id);

CREATE TRIGGER predictive_decisions_immutable BEFORE UPDATE OR DELETE ON public.predictive_decisions FOR EACH ROW EXECUTE FUNCTION public.predictive_append_only();
CREATE TRIGGER predictive_decision_inputs_immutable BEFORE UPDATE OR DELETE ON public.predictive_decision_inputs FOR EACH ROW EXECUTE FUNCTION public.predictive_append_only();
CREATE TRIGGER predictive_decisions_no_truncate BEFORE TRUNCATE ON public.predictive_decisions FOR EACH STATEMENT EXECUTE FUNCTION public.predictive_append_only();
CREATE TRIGGER predictive_decision_inputs_no_truncate BEFORE TRUNCATE ON public.predictive_decision_inputs FOR EACH STATEMENT EXECUTE FUNCTION public.predictive_append_only();

-- Whether a decision's inputs are exactly the heads of its evidence scope usable
-- at instant t: marker facts (completion), participation evidence plus stats
-- (participation), or the one fact (reconciliation). Mirrors labels.ts current().
CREATE FUNCTION public.predictive_decision_current(decision_id text, t timestamptz) RETURNS boolean LANGUAGE plpgsql STABLE AS $$
DECLARE d public.predictive_decisions; prefix text; exact_key text; heads text[]; inputs text[]; pa text; pb text;
BEGIN
  SELECT * INTO d FROM public.predictive_decisions WHERE id = decision_id;
  IF d.id IS NULL OR d.decided_at > t THEN RETURN false; END IF;
  SELECT array_agg(i.observation_id ORDER BY i.observation_id COLLATE "C") INTO inputs FROM public.predictive_decision_inputs i WHERE i.decision_id = d.id;
  IF d.kind = 'snap-source-compatibility' THEN
    -- snap-compatibility-v1 (snaps.ts snapOverlapHeadsAt): every snap head of both
    -- profiles in the games both cover with a team snap head at t.
    pa := split_part(d.entity_key, ':', 2); pb := split_part(d.entity_key, ':', 3);
    WITH visible AS (SELECT o.id, o.predecessor_id, o.kind, o.profile_id, split_part(o.entity_key, ':', 2) AS game FROM public.predictive_observations o
      WHERE split_part(o.entity_key, ':', 1) IN ('player-game-snaps','team-game-snaps') AND o.profile_id IN (pa, pb) AND EXISTS (
        SELECT 1 FROM public.predictive_artifact_observations l JOIN public.predictive_captures c ON c.artifact_id = l.artifact_id
        JOIN public.predictive_ingestion_runs ru ON ru.id = c.run_id WHERE l.observation_id = o.id AND c.state = 'published' AND ru.status = 'published'
          AND c.available_at <= t AND c.ingested_at <= t)),
    snap_heads AS (SELECT v.* FROM visible v WHERE NOT EXISTS (SELECT 1 FROM visible n WHERE n.predecessor_id = v.id)),
    overlap AS (SELECT h.game FROM snap_heads h WHERE h.kind = 'team-game-snaps' GROUP BY h.game HAVING count(DISTINCT h.profile_id) = 2)
    SELECT array_agg(h.id ORDER BY h.id COLLATE "C") INTO heads FROM snap_heads h WHERE h.game IN (SELECT game FROM overlap);
    RETURN heads IS NOT DISTINCT FROM inputs;
  END IF;
  IF d.kind = 'completion' THEN prefix := 'event-state-marker:' || split_part(d.entity_key, ':', 2) || ':';
  ELSIF d.kind = 'participation' THEN
    prefix := 'participation-evidence:' || split_part(d.entity_key, ':', 2) || ':' || split_part(d.entity_key, ':', 3) || ':';
    exact_key := 'player-game-stats:' || split_part(d.entity_key, ':', 2) || ':' || split_part(d.entity_key, ':', 3);
  ELSE exact_key := substr(d.entity_key, length('reconciliation:') + 1); END IF;
  WITH visible AS (SELECT o.id, o.predecessor_id FROM public.predictive_observations o
    WHERE ((prefix IS NOT NULL AND o.entity_key LIKE prefix || '%') OR o.entity_key = exact_key) AND EXISTS (
      SELECT 1 FROM public.predictive_artifact_observations l JOIN public.predictive_captures c ON c.artifact_id = l.artifact_id
      JOIN public.predictive_ingestion_runs ru ON ru.id = c.run_id WHERE l.observation_id = o.id AND c.state = 'published' AND ru.status = 'published'
        AND c.available_at <= t AND c.ingested_at <= t))
  SELECT array_agg(v.id ORDER BY v.id COLLATE "C") INTO heads FROM visible v WHERE NOT EXISTS (SELECT 1 FROM visible n WHERE n.predecessor_id = v.id);
  RETURN heads IS NOT DISTINCT FROM inputs;
END
$$;

CREATE FUNCTION public.predictive_decision_check() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE target text; d public.predictive_decisions; fact text; game text;
  inputs integer; sources integer; selected integer; selected_id text; same boolean; synthetic boolean; consistent boolean;
  head_ids text[]; input_ids text[]; r record; absent boolean := false;
  final_n integer := 0; terminal_n integer := 0; totals_n integer := 0; suspended_n integer := 0; postponed_n integer := 0;
  final_at timestamptz; terminal_at timestamptz; totals_at timestamptz; state text; observed timestamptz;
  conflict boolean := false; claims text[] := '{}'; stats_n integer := 0; positive_n integer := 0; overlap integer; pa text; pb text;
BEGIN
  IF TG_TABLE_NAME = 'predictive_decisions' THEN target := NEW.id; ELSE target := NEW.decision_id; END IF;
  SELECT * INTO d FROM public.predictive_decisions WHERE id = target;
  IF (SELECT status FROM public.predictive_ingestion_runs WHERE id = d.run_id) <> 'published'
      OR (d.predecessor_id IS NOT NULL AND EXISTS (SELECT 1 FROM public.predictive_decisions p WHERE p.id = d.predecessor_id AND p.decided_at > d.decided_at)) THEN
    RAISE EXCEPTION 'predictive-decision-invalid' USING ERRCODE = '23514';
  END IF;
  SELECT count(*), coalesce(bool_or(p.purpose = 'synthetic-test'), false) INTO inputs, synthetic
    FROM public.predictive_decision_inputs i JOIN public.predictive_observations o ON o.id = i.observation_id
    JOIN public.predictive_source_profiles p ON p.id = o.profile_id WHERE i.decision_id = target;
  IF (inputs > 0 AND synthetic <> (d.mode = 'synthetic-proof')) OR (d.mode = 'synthetic-proof' AND NOT public.predictive_harness_session()) THEN
    RAISE EXCEPTION 'predictive-decision-mode-invalid' USING ERRCODE = '23514';
  END IF;
  IF d.kind = 'completion' THEN
    -- event-completion-v1 (completion.ts): the inputs are exactly the marker heads
    -- usable at decided_at, and the stated outcome is what the policy computes.
    SELECT array_agg(i.observation_id ORDER BY i.observation_id COLLATE "C") INTO input_ids
      FROM public.predictive_decision_inputs i WHERE i.decision_id = target AND i.role = 'marker';
    IF NOT public.predictive_decision_current(target, d.decided_at) OR inputs <> coalesce(cardinality(input_ids), 0) THEN
      RAISE EXCEPTION 'predictive-completion-inputs-invalid' USING ERRCODE = '23514';
    END IF;
    FOR r IN SELECT o.kind, split_part(o.entity_key, ':', 3) AS marker,
        (SELECT c.captured_at FROM public.predictive_artifact_observations l JOIN public.predictive_captures c ON c.artifact_id = l.artifact_id
          WHERE l.observation_id = o.id AND c.state = 'published' ORDER BY c.ingested_at, c.available_at, c.captured_at, c.id COLLATE "C" LIMIT 1) AS captured
      FROM public.predictive_observations o WHERE o.id = ANY(coalesce(input_ids, '{}')) LOOP
      IF r.kind = 'source-row-absent' THEN absent := true; END IF;
      IF r.marker = 'provider-final-status' THEN final_n := final_n + 1; final_at := r.captured;
      ELSIF r.marker = 'terminal-play' THEN terminal_n := terminal_n + 1; terminal_at := r.captured;
      ELSIF r.marker = 'final-team-totals' THEN totals_n := totals_n + 1; totals_at := r.captured;
      ELSIF r.marker = 'suspension-notice' THEN suspended_n := suspended_n + 1;
      ELSIF r.marker = 'postponement-notice' THEN postponed_n := postponed_n + 1; END IF;
    END LOOP;
    IF absent OR greatest(final_n, terminal_n, totals_n, suspended_n, postponed_n) > 1
        OR ((suspended_n > 0 OR postponed_n > 0) AND (final_n + terminal_n + totals_n) > 0) OR (suspended_n > 0 AND postponed_n > 0) THEN state := 'conflicting';
    ELSIF suspended_n > 0 THEN state := 'suspended';
    ELSIF postponed_n > 0 THEN state := 'postponed';
    ELSIF final_n > 0 AND (terminal_n + totals_n) > 0 THEN state := 'completed'; observed := greatest(final_at, least(terminal_at, totals_at));
    ELSIF (final_n + terminal_n + totals_n) > 0 THEN state := 'in-progress';
    ELSE state := 'scheduled'; END IF;
    IF state <> d.outcome->>'state' OR (CASE WHEN observed IS NULL THEN NULL
        ELSE to_char(observed AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"') END) IS DISTINCT FROM d.outcome->>'completionObservedAt' THEN
      RAISE EXCEPTION 'predictive-decision-rule-invalid' USING ERRCODE = '23514';
    END IF;
    RETURN NULL;
  END IF;
  IF d.kind = 'participation' THEN
    -- participation-v1 (participation.ts): the inputs are exactly the evidence and
    -- stats heads usable at decided_at; the state is recomputed from them.
    SELECT array_agg(i.observation_id ORDER BY i.observation_id COLLATE "C") INTO input_ids
      FROM public.predictive_decision_inputs i WHERE i.decision_id = target AND i.role = 'evidence';
    IF NOT public.predictive_decision_current(target, d.decided_at) OR inputs <> coalesce(cardinality(input_ids), 0) THEN
      RAISE EXCEPTION 'predictive-participation-inputs-invalid' USING ERRCODE = '23514';
    END IF;
    SELECT coalesce(bool_or(n > 1 OR gone), false) INTO conflict FROM (SELECT split_part(o.entity_key, ':', 4) AS evidence, count(*) AS n,
        bool_or(o.kind = 'source-row-absent') AS gone FROM public.predictive_observations o
      WHERE o.id = ANY(coalesce(input_ids, '{}')) AND o.entity_key LIKE 'participation-evidence:%' GROUP BY 1) grouped;
    SELECT coalesce(array_agg(DISTINCT o.data->>'claim'), '{}') INTO claims FROM public.predictive_observations o
      WHERE o.id = ANY(coalesce(input_ids, '{}')) AND o.kind = 'participation-evidence';
    SELECT count(*), count(*) FILTER (WHERE o.kind = 'player-game-stats' AND (coalesce((o.data->>'attempts')::integer, 0) > 0
        OR coalesce((o.data->>'carries')::integer, 0) > 0 OR coalesce((o.data->>'targets')::integer, 0) > 0))
      INTO stats_n, positive_n FROM public.predictive_observations o WHERE o.id = ANY(coalesce(input_ids, '{}')) AND o.entity_key LIKE 'player-game-stats:%';
    IF stats_n > 0 AND positive_n = stats_n AND NOT 'offensive-participant' = ANY(claims) THEN claims := array_append(claims, 'offensive-participant'); END IF;
    state := CASE WHEN conflict OR cardinality(claims) > 1 THEN 'conflicting' WHEN cardinality(claims) = 1 THEN claims[1] ELSE 'unresolved' END;
    IF state <> d.outcome->>'state' THEN RAISE EXCEPTION 'predictive-decision-rule-invalid' USING ERRCODE = '23514'; END IF;
    RETURN NULL;
  END IF;
  IF d.kind = 'snap-source-compatibility' THEN
    -- snap-compatibility-v1 (snaps.ts): the inputs are exactly the overlap heads,
    -- and the result is recomputed from them.
    SELECT array_agg(i.observation_id ORDER BY i.observation_id COLLATE "C") INTO input_ids
      FROM public.predictive_decision_inputs i WHERE i.decision_id = target AND i.role = 'evidence';
    IF NOT public.predictive_decision_current(target, d.decided_at) OR inputs <> coalesce(cardinality(input_ids), 0) THEN
      RAISE EXCEPTION 'predictive-snap-compatibility-inputs-invalid' USING ERRCODE = '23514';
    END IF;
    pa := split_part(d.entity_key, ':', 2); pb := split_part(d.entity_key, ':', 3);
    SELECT count(DISTINCT split_part(o.entity_key, ':', 2)) INTO overlap FROM public.predictive_observations o WHERE o.id = ANY(coalesce(input_ids, '{}'));
    IF overlap = 0 THEN state := 'insufficient-overlap';
    ELSIF EXISTS (SELECT 1 FROM (SELECT o.entity_key, count(*) FILTER (WHERE o.profile_id = pa) AS na, count(*) FILTER (WHERE o.profile_id = pb) AS nb,
          bool_or(o.kind = 'source-row-absent' OR o.data->'offenseSnaps' = 'null'::jsonb) AS bad,
          count(DISTINCT o.data->'offenseSnaps') AS snaps, count(DISTINCT o.data->>'playCountingDefinition') AS definitions,
          count(o.data->>'playCountingDefinition') AS defined
        FROM public.predictive_observations o WHERE o.id = ANY(input_ids) GROUP BY o.entity_key) g
        WHERE g.na <> 1 OR g.nb <> 1 OR g.bad OR g.snaps <> 1 OR g.definitions > 1 OR g.defined NOT IN (0, 2)) THEN state := 'incompatible';
    ELSE state := 'compatible'; END IF;
    IF state <> d.outcome->>'result' OR (d.outcome->>'overlapGames')::integer <> overlap THEN
      RAISE EXCEPTION 'predictive-decision-rule-invalid' USING ERRCODE = '23514';
    END IF;
    RETURN NULL;
  END IF;
  IF d.kind <> 'reconciliation' THEN RAISE EXCEPTION 'predictive-decision-invalid' USING ERRCODE = '23514'; END IF;
  fact := substr(d.entity_key, length('reconciliation:') + 1);
  SELECT count(DISTINCT o.source_key), count(*) FILTER (WHERE i.role = 'selected'),
    min(i.observation_id) FILTER (WHERE i.role = 'selected'), count(DISTINCT o.data) <= 1
    INTO sources, selected, selected_id, same
    FROM public.predictive_decision_inputs i JOIN public.predictive_observations o ON o.id = i.observation_id WHERE i.decision_id = target;
  IF sources <> inputs OR EXISTS (SELECT 1 FROM public.predictive_decision_inputs i JOIN public.predictive_observations o ON o.id = i.observation_id
      WHERE i.decision_id = target AND (i.role NOT IN ('candidate','selected') OR o.entity_key <> fact OR NOT EXISTS (
        SELECT 1 FROM public.predictive_artifact_observations l JOIN public.predictive_captures c ON c.artifact_id = l.artifact_id
        JOIN public.predictive_ingestion_runs ru ON ru.id = c.run_id
        WHERE l.observation_id = o.id AND c.state = 'published' AND ru.status = 'published'
          AND c.available_at <= d.decided_at AND c.ingested_at <= d.decided_at))) THEN
    RAISE EXCEPTION 'predictive-decision-invalid' USING ERRCODE = '23514';
  END IF;
  IF NOT public.predictive_decision_current(target, d.decided_at) THEN
    RAISE EXCEPTION 'predictive-reconciliation-inputs-not-heads' USING ERRCODE = '23514';
  END IF;
  consistent := CASE d.outcome->>'result'
      WHEN 'selected' THEN selected = 1 AND selected_id = d.outcome->>'selectedObservationId'
        AND ((d.outcome->>'rule' = 'single-source' AND inputs = 1) OR (d.outcome->>'rule' = 'sources-agree' AND inputs > 1 AND same))
      WHEN 'conflict' THEN selected = 0 AND d.outcome->>'rule' = 'material-discrepancy' AND inputs > 1 AND NOT same
      ELSE inputs = 0 AND d.outcome->>'rule' = 'no-candidates' END;
  IF consistent IS NOT TRUE THEN
    RAISE EXCEPTION 'predictive-decision-rule-invalid' USING ERRCODE = '23514';
  END IF;
  RETURN NULL;
END
$$;
CREATE CONSTRAINT TRIGGER predictive_check_decisions AFTER INSERT ON public.predictive_decisions DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION public.predictive_decision_check();
CREATE CONSTRAINT TRIGGER predictive_check_decision_inputs AFTER INSERT ON public.predictive_decision_inputs DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION public.predictive_decision_check();

-- canonical-label-finalization-v1 (labels.ts eligibleFinalAt): the later of the
-- completion bound + 72 hours and the first Thursday 12:00 UTC strictly after it.
CREATE FUNCTION public.predictive_label_eligible_final_at(bound timestamptz) RETURNS timestamptz LANGUAGE plpgsql IMMUTABLE STRICT AS $$
DECLARE naive timestamp := bound AT TIME ZONE 'UTC'; thursday timestamp;
BEGIN
  thursday := date_trunc('day', naive) + interval '12 hours';
  thursday := thursday + ((4 - extract(dow FROM thursday)::integer + 7) % 7) * interval '1 day';
  IF thursday <= naive THEN thursday := thursday + interval '7 days'; END IF;
  RETURN greatest(bound + interval '72 hours', thursday AT TIME ZONE 'UTC');
END
$$;

CREATE TABLE public.predictive_outcome_labels (
  id text PRIMARY KEY CHECK (length(id) BETWEEN 1 AND 256 AND id !~ '[\x01-\x1f\x7f]'),
  player_id text NOT NULL CHECK (player_id ~ '^00-[0-9]{7}$'),
  game_id uuid NOT NULL REFERENCES public.predictive_games(id),
  season_type text NOT NULL CHECK (season_type IN ('REG','POST')),
  stat text NOT NULL CHECK (stat IN ('passing_yards','passing_tds','completions','attempts','passing_interceptions',
    'rushing_yards','carries','receiving_yards','receptions')),
  value integer,
  state text NOT NULL CHECK (state IN ('provisional','final','unresolved','excluded')),
  mode text NOT NULL CHECK (mode IN ('production-research','synthetic-proof')),
  policy_id text NOT NULL CHECK (policy_id = 'canonical-label-finalization-v1'),
  label_version integer NOT NULL CHECK (label_version >= 1),
  predecessor_id text REFERENCES public.predictive_outcome_labels(id) DEFERRABLE INITIALLY DEFERRED,
  run_id text NOT NULL REFERENCES public.predictive_ingestion_runs(id),
  completion_decision_id text NOT NULL REFERENCES public.predictive_decisions(id),
  participation_decision_id text NOT NULL REFERENCES public.predictive_decisions(id),
  reconciliation_decision_id text REFERENCES public.predictive_decisions(id),
  selected_observation_id text REFERENCES public.predictive_observations(id),
  eligible_final_at timestamptz CHECK (isfinite(eligible_final_at)),
  post_window_capture_id text REFERENCES public.predictive_captures(id),
  finalized_at timestamptz CHECK (isfinite(finalized_at) AND finalized_at = date_trunc('milliseconds', finalized_at)),
  created_at timestamptz NOT NULL CHECK (isfinite(created_at) AND created_at = date_trunc('milliseconds', created_at)),
  player_bridge_observation_id text REFERENCES public.predictive_observations(id),
  UNIQUE (player_id, game_id, season_type, stat, label_version),
  CHECK (state <> 'final' OR player_bridge_observation_id IS NOT NULL),
  CHECK (state IN ('provisional','final') OR player_bridge_observation_id IS NULL),
  CHECK ((label_version = 1) = (predecessor_id IS NULL)),
  CHECK (predecessor_id IS DISTINCT FROM id),
  CHECK (state NOT IN ('unresolved','excluded') OR (value IS NULL AND selected_observation_id IS NULL)),
  CHECK (value IS NULL OR stat IN ('passing_yards','rushing_yards','receiving_yards') OR value >= 0)
);
CREATE UNIQUE INDEX predictive_outcome_labels_one_successor ON public.predictive_outcome_labels (predecessor_id) WHERE predecessor_id IS NOT NULL;
CREATE INDEX predictive_outcome_labels_game_idx ON public.predictive_outcome_labels (game_id, player_id, stat);
CREATE TRIGGER predictive_labels_immutable BEFORE UPDATE OR DELETE ON public.predictive_outcome_labels FOR EACH ROW EXECUTE FUNCTION public.predictive_append_only();
CREATE TRIGGER predictive_labels_no_truncate BEFORE TRUNCATE ON public.predictive_outcome_labels FOR EACH STATEMENT EXECUTE FUNCTION public.predictive_append_only();

-- The eight binding checks, mirroring validateLabels() in labels.ts. Each
-- failure names its check: predictive-label-binding-<n>.
CREATE FUNCTION public.predictive_label_check() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE l public.predictive_outcome_labels; c public.predictive_decisions; p public.predictive_decisions; r public.predictive_decisions;
  s public.predictive_observations; b public.predictive_observations; cap public.predictive_captures; prior public.predictive_outcome_labels;
  field text; eligible timestamptz; synthetic boolean;
BEGIN
  SELECT * INTO l FROM public.predictive_outcome_labels WHERE id = NEW.id;
  IF (SELECT status FROM public.predictive_ingestion_runs WHERE id = l.run_id) <> 'published' THEN
    RAISE EXCEPTION 'predictive-label-binding-6' USING ERRCODE = '23514';
  END IF;
  field := CASE l.stat WHEN 'passing_yards' THEN 'passingYards' WHEN 'passing_tds' THEN 'passingTds' WHEN 'completions' THEN 'completions'
    WHEN 'attempts' THEN 'attempts' WHEN 'passing_interceptions' THEN 'passingInterceptions' WHEN 'rushing_yards' THEN 'rushingYards'
    WHEN 'carries' THEN 'carries' WHEN 'receiving_yards' THEN 'receivingYards' ELSE 'receptions' END;
  SELECT * INTO c FROM public.predictive_decisions WHERE id = l.completion_decision_id;
  SELECT * INTO p FROM public.predictive_decisions WHERE id = l.participation_decision_id;
  SELECT * INTO r FROM public.predictive_decisions WHERE id = l.reconciliation_decision_id;
  IF c.kind <> 'completion' OR c.entity_key <> 'completion:' || l.game_id OR NOT public.predictive_decision_current(c.id, l.created_at) THEN
    RAISE EXCEPTION 'predictive-label-binding-1' USING ERRCODE = '23514';
  END IF;
  IF p.kind <> 'participation' OR p.entity_key <> 'participation:' || l.game_id || ':' || l.player_id OR NOT public.predictive_decision_current(p.id, l.created_at) THEN
    RAISE EXCEPTION 'predictive-label-binding-2' USING ERRCODE = '23514';
  END IF;
  IF l.state IN ('provisional','final') THEN
    IF c.outcome->>'state' <> 'completed' OR p.outcome->>'state' <> 'offensive-participant' THEN
      RAISE EXCEPTION 'predictive-label-binding-2' USING ERRCODE = '23514';
    END IF;
    IF r.id IS NULL OR r.kind <> 'reconciliation' OR r.entity_key <> 'reconciliation:player-game-stats:' || l.game_id || ':' || l.player_id
        OR r.outcome->>'result' <> 'selected' OR r.outcome->>'selectedObservationId' IS DISTINCT FROM l.selected_observation_id
        OR NOT public.predictive_decision_current(r.id, l.created_at) THEN
      RAISE EXCEPTION 'predictive-label-binding-3' USING ERRCODE = '23514';
    END IF;
    SELECT * INTO s FROM public.predictive_observations WHERE id = l.selected_observation_id;
    IF s.kind <> 'player-game-stats' OR s.data->>'seasonType' <> l.season_type OR s.data->field = 'null'::jsonb
        OR (s.data->>field)::integer IS DISTINCT FROM l.value OR NOT EXISTS (
          SELECT 1 FROM public.predictive_artifact_observations la JOIN public.predictive_captures ca ON ca.artifact_id = la.artifact_id
          JOIN public.predictive_ingestion_runs ru ON ru.id = ca.run_id WHERE la.observation_id = s.id AND ca.state = 'published' AND ru.status = 'published'
            AND ca.available_at <= l.created_at AND ca.ingested_at <= l.created_at) THEN
      RAISE EXCEPTION 'predictive-label-binding-4' USING ERRCODE = '23514';
    END IF;
    -- 9 (bridge-v1, labels.ts): the pinned bridge revision maps the provider's
    -- identity to this player; it was usable, current and unambiguous when the
    -- label was created, effective at kickoff, and its profile is linked to the
    -- selected row's profile for that provider.
    IF l.player_bridge_observation_id IS NOT NULL THEN
      SELECT * INTO b FROM public.predictive_observations WHERE id = l.player_bridge_observation_id;
      IF b.kind IS DISTINCT FROM 'player-bridge' OR b.data->>'playerId' <> l.player_id
          OR b.data->>'rawPlayerId' IS DISTINCT FROM s.data->>'rawPlayerId'
          OR b.data->>'provider' IS DISTINCT FROM s.data->>'playerIdProvider'
          OR s.data->>'playerId' IS DISTINCT FROM l.player_id
          OR NOT public.predictive_observation_usable(b.id, l.created_at)
          OR EXISTS (SELECT 1 FROM public.predictive_observations n WHERE n.predecessor_id = b.id AND public.predictive_observation_usable(n.id, l.created_at))
          OR NOT EXISTS (SELECT 1 FROM public.predictive_profile_identity_links k WHERE k.stats_profile_id = s.profile_id
            AND k.bridge_profile_id = b.profile_id AND k.provider = b.data->>'provider' AND k.decided_at <= l.created_at)
          OR EXISTS (SELECT 1 FROM public.predictive_observations h WHERE h.kind = 'player-bridge' AND h.id <> b.id
            AND h.data->>'provider' = b.data->>'provider' AND public.predictive_observation_usable(h.id, l.created_at)
            AND NOT EXISTS (SELECT 1 FROM public.predictive_observations n WHERE n.predecessor_id = h.id AND public.predictive_observation_usable(n.id, l.created_at))
            AND (h.data->>'effectiveFrom')::timestamptz < (b.data->>'effectiveTo')::timestamptz
            AND (b.data->>'effectiveFrom')::timestamptz < (h.data->>'effectiveTo')::timestamptz
            AND ((h.entity_key = b.entity_key AND h.data->>'playerId' <> b.data->>'playerId')
              OR (h.entity_key <> b.entity_key AND h.data->>'playerId' = b.data->>'playerId'))) THEN
        RAISE EXCEPTION 'predictive-label-binding-9' USING ERRCODE = '23514';
      END IF;
      -- Every current schedule head for the game puts kickoff inside the window.
      IF NOT EXISTS (SELECT 1 FROM public.predictive_observations g WHERE g.entity_key = 'schedule:' || l.game_id
            AND public.predictive_observation_usable(g.id, l.created_at))
          OR EXISTS (SELECT 1 FROM public.predictive_observations g WHERE g.entity_key = 'schedule:' || l.game_id
            AND public.predictive_observation_usable(g.id, l.created_at)
            AND NOT EXISTS (SELECT 1 FROM public.predictive_observations n WHERE n.predecessor_id = g.id AND public.predictive_observation_usable(n.id, l.created_at))
            AND (g.kind <> 'schedule' OR (g.data->>'kickoff')::timestamptz < (b.data->>'effectiveFrom')::timestamptz
              OR (g.data->>'kickoff')::timestamptz >= (b.data->>'effectiveTo')::timestamptz)) THEN
        RAISE EXCEPTION 'predictive-label-binding-9' USING ERRCODE = '23514';
      END IF;
    ELSIF l.state = 'final' THEN
      RAISE EXCEPTION 'predictive-label-binding-9' USING ERRCODE = '23514';
    END IF;
  ELSE
    IF l.value IS NOT NULL OR l.selected_observation_id IS NOT NULL THEN RAISE EXCEPTION 'predictive-label-binding-4' USING ERRCODE = '23514'; END IF;
    IF l.state = 'excluded' AND (c.outcome->>'state' <> 'completed' OR p.outcome->>'state' NOT IN ('zero-offensive-participation','inactive-or-dnp')) THEN
      RAISE EXCEPTION 'predictive-label-binding-2' USING ERRCODE = '23514';
    END IF;
  END IF;
  IF l.state = 'final' THEN
    eligible := public.predictive_label_eligible_final_at((c.outcome->>'completionObservedAt')::timestamptz);
    SELECT * INTO cap FROM public.predictive_captures WHERE id = l.post_window_capture_id;
    IF l.eligible_final_at IS DISTINCT FROM eligible OR l.finalized_at IS NULL OR l.finalized_at < eligible OR l.created_at < l.finalized_at
        OR cap.id IS NULL OR cap.state <> 'published' OR NOT (cap.body_complete AND cap.header_verified AND cap.parser_succeeded)
        OR cap.captured_at < eligible OR NOT EXISTS (SELECT 1 FROM public.predictive_artifact_observations la
          WHERE la.artifact_id = cap.artifact_id AND la.observation_id = l.selected_observation_id) THEN
      RAISE EXCEPTION 'predictive-label-binding-5' USING ERRCODE = '23514';
    END IF;
    IF cap.ingested_at > l.created_at THEN RAISE EXCEPTION 'predictive-label-binding-6' USING ERRCODE = '23514'; END IF;
  ELSIF l.post_window_capture_id IS NOT NULL OR l.finalized_at IS NOT NULL OR l.eligible_final_at IS NOT NULL THEN
    RAISE EXCEPTION 'predictive-label-binding-5' USING ERRCODE = '23514';
  END IF;
  IF l.predecessor_id IS NOT NULL THEN
    SELECT * INTO prior FROM public.predictive_outcome_labels WHERE id = l.predecessor_id;
    IF prior.player_id <> l.player_id OR prior.game_id <> l.game_id OR prior.season_type <> l.season_type OR prior.stat <> l.stat
        OR prior.label_version + 1 <> l.label_version OR prior.created_at >= l.created_at THEN
      RAISE EXCEPTION 'predictive-label-binding-7' USING ERRCODE = '23514';
    END IF;
  END IF;
  synthetic := c.mode = 'synthetic-proof' OR p.mode = 'synthetic-proof' OR coalesce(r.mode = 'synthetic-proof', false) OR EXISTS (
    SELECT 1 FROM public.predictive_observations o JOIN public.predictive_source_profiles sp ON sp.id = o.profile_id
    WHERE o.id IN (l.selected_observation_id, l.player_bridge_observation_id) AND sp.purpose = 'synthetic-test');
  IF synthetic <> (l.mode = 'synthetic-proof') OR (l.mode = 'synthetic-proof' AND NOT public.predictive_harness_session()) THEN
    RAISE EXCEPTION 'predictive-label-binding-8' USING ERRCODE = '23514';
  END IF;
  RETURN NULL;
END
$$;
CREATE CONSTRAINT TRIGGER predictive_check_labels AFTER INSERT ON public.predictive_outcome_labels DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION public.predictive_label_check();

-- Saved feature runs (feature-run-retention-v1). A run is computed in a
-- read-only snapshot and recorded separately, with its full bundle as a blob and
-- an exact dependency manifest. input_digest covers cutoff-time inputs only;
-- execution_digest also covers rights, policies, code and timing.
CREATE TABLE public.predictive_feature_runs (
  id text PRIMARY KEY CHECK (length(id) BETWEEN 1 AND 256 AND id !~ '[\x01-\x1f\x7f]'),
  mode text NOT NULL CHECK (mode IN ('production-research','synthetic-proof')),
  feature_version text NOT NULL CHECK (length(feature_version) BETWEEN 1 AND 64),
  candidate text NOT NULL CHECK (length(candidate) BETWEEN 1 AND 128),
  player_id text NOT NULL CHECK (player_id ~ '^00-[0-9]{7}$'),
  game_id uuid NOT NULL REFERENCES public.predictive_games(id),
  cutoff timestamptz NOT NULL CHECK (isfinite(cutoff) AND cutoff = date_trunc('milliseconds', cutoff)),
  computed_at timestamptz NOT NULL CHECK (isfinite(computed_at) AND computed_at = date_trunc('milliseconds', computed_at) AND computed_at >= cutoff),
  recorded_at timestamptz NOT NULL CHECK (isfinite(recorded_at) AND recorded_at = date_trunc('milliseconds', recorded_at) AND recorded_at >= computed_at),
  code_version text NOT NULL CHECK (length(code_version) BETWEEN 1 AND 64),
  status text NOT NULL CHECK (status IN ('ready-inputs','unavailable-inputs')),
  reasons text[] NOT NULL,
  input_digest text NOT NULL CHECK (input_digest ~ '^[a-f0-9]{64}$'),
  execution_digest text NOT NULL CHECK (execution_digest ~ '^[a-f0-9]{64}$'),
  bundle_blob_sha256 text NOT NULL REFERENCES public.predictive_blobs(sha256),
  CHECK ((status = 'ready-inputs') = (cardinality(reasons) = 0))
);
CREATE INDEX predictive_feature_runs_recorded_idx ON public.predictive_feature_runs (recorded_at);

CREATE TABLE public.predictive_feature_run_dependencies (
  feature_run_id text NOT NULL REFERENCES public.predictive_feature_runs(id),
  observation_id text REFERENCES public.predictive_observations(id),
  decision_id text REFERENCES public.predictive_decisions(id),
  rights_decision_id text REFERENCES public.predictive_rights_decisions(id),
  policy_id text CHECK (policy_id ~ '^[a-z0-9-]+-v[0-9]+$'),
  feature_definition_id text CHECK (length(feature_definition_id) BETWEEN 1 AND 64),
  CHECK (num_nonnulls(observation_id, decision_id, rights_decision_id, policy_id, feature_definition_id) = 1)
);
CREATE UNIQUE INDEX predictive_feature_run_dependencies_unique ON public.predictive_feature_run_dependencies
  (feature_run_id, coalesce(observation_id, decision_id, rights_decision_id, policy_id, feature_definition_id));

CREATE TABLE public.predictive_feature_run_pins (
  id text PRIMARY KEY CHECK (length(id) BETWEEN 1 AND 256 AND id !~ '[\x01-\x1f\x7f]'),
  feature_run_id text NOT NULL REFERENCES public.predictive_feature_runs(id),
  reason text NOT NULL CHECK (reason IN ('training','serving','evaluation','owner')),
  pinned_at timestamptz NOT NULL CHECK (isfinite(pinned_at) AND pinned_at = date_trunc('milliseconds', pinned_at))
);
-- Unpinning is its own append-only event; a pin row is never updated.
CREATE TABLE public.predictive_feature_run_unpins (
  pin_id text PRIMARY KEY REFERENCES public.predictive_feature_run_pins(id),
  unpinned_at timestamptz NOT NULL CHECK (isfinite(unpinned_at) AND unpinned_at = date_trunc('milliseconds', unpinned_at))
);

CREATE TRIGGER predictive_feature_runs_immutable BEFORE UPDATE OR DELETE ON public.predictive_feature_runs FOR EACH ROW EXECUTE FUNCTION public.predictive_append_only();
CREATE TRIGGER predictive_feature_run_dependencies_immutable BEFORE UPDATE OR DELETE ON public.predictive_feature_run_dependencies FOR EACH ROW EXECUTE FUNCTION public.predictive_append_only();
CREATE TRIGGER predictive_feature_run_pins_immutable BEFORE UPDATE OR DELETE ON public.predictive_feature_run_pins FOR EACH ROW EXECUTE FUNCTION public.predictive_append_only();
CREATE TRIGGER predictive_feature_run_unpins_immutable BEFORE UPDATE OR DELETE ON public.predictive_feature_run_unpins FOR EACH ROW EXECUTE FUNCTION public.predictive_append_only();
CREATE TRIGGER predictive_feature_runs_no_truncate BEFORE TRUNCATE ON public.predictive_feature_runs FOR EACH STATEMENT EXECUTE FUNCTION public.predictive_append_only();
CREATE TRIGGER predictive_feature_run_dependencies_no_truncate BEFORE TRUNCATE ON public.predictive_feature_run_dependencies FOR EACH STATEMENT EXECUTE FUNCTION public.predictive_append_only();
CREATE TRIGGER predictive_feature_run_pins_no_truncate BEFORE TRUNCATE ON public.predictive_feature_run_pins FOR EACH STATEMENT EXECUTE FUNCTION public.predictive_append_only();
CREATE TRIGGER predictive_feature_run_unpins_no_truncate BEFORE TRUNCATE ON public.predictive_feature_run_unpins FOR EACH STATEMENT EXECUTE FUNCTION public.predictive_append_only();

CREATE FUNCTION public.predictive_unpin_check() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF NEW.unpinned_at < (SELECT pinned_at FROM public.predictive_feature_run_pins WHERE id = NEW.pin_id) THEN
    RAISE EXCEPTION 'predictive-unpin-before-pin' USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END
$$;
CREATE TRIGGER predictive_unpin_validate BEFORE INSERT ON public.predictive_feature_run_unpins FOR EACH ROW EXECUTE FUNCTION public.predictive_unpin_check();

-- Every dependency was usable at the cutoff; every decision's inputs are listed;
-- a ready run had model-input rights in force when recorded for every evidence
-- profile; the feature definition is named; the mode follows the evidence.
CREATE FUNCTION public.predictive_feature_run_check() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE target text; f public.predictive_feature_runs; synthetic boolean;
BEGIN
  IF TG_TABLE_NAME = 'predictive_feature_runs' THEN target := NEW.id; ELSE target := NEW.feature_run_id; END IF;
  SELECT * INTO f FROM public.predictive_feature_runs WHERE id = target;
  IF EXISTS (SELECT 1 FROM public.predictive_feature_run_dependencies d WHERE d.feature_run_id = target AND d.observation_id IS NOT NULL AND NOT EXISTS (
      SELECT 1 FROM public.predictive_artifact_observations l JOIN public.predictive_captures c ON c.artifact_id = l.artifact_id
      JOIN public.predictive_ingestion_runs ru ON ru.id = c.run_id WHERE l.observation_id = d.observation_id AND c.state = 'published'
        AND ru.status = 'published' AND c.available_at <= f.cutoff AND c.ingested_at <= f.cutoff)) THEN
    RAISE EXCEPTION 'predictive-feature-run-dependency-after-cutoff' USING ERRCODE = '23514';
  END IF;
  IF EXISTS (SELECT 1 FROM public.predictive_feature_run_dependencies d JOIN public.predictive_decisions dc ON dc.id = d.decision_id
      WHERE d.feature_run_id = target AND dc.decided_at > f.cutoff) THEN
    RAISE EXCEPTION 'predictive-feature-run-dependency-after-cutoff' USING ERRCODE = '23514';
  END IF;
  IF EXISTS (SELECT 1 FROM public.predictive_feature_run_dependencies d WHERE d.feature_run_id = target AND d.decision_id IS NOT NULL
      AND NOT public.predictive_decision_current(d.decision_id, f.cutoff)) THEN
    RAISE EXCEPTION 'predictive-feature-run-decision-stale' USING ERRCODE = '23514';
  END IF;
  IF EXISTS (SELECT 1 FROM public.predictive_feature_run_dependencies d JOIN public.predictive_decision_inputs i ON i.decision_id = d.decision_id
      WHERE d.feature_run_id = target AND NOT EXISTS (SELECT 1 FROM public.predictive_feature_run_dependencies o
        WHERE o.feature_run_id = target AND o.observation_id = i.observation_id)) THEN
    RAISE EXCEPTION 'predictive-feature-run-inputs-incomplete' USING ERRCODE = '23514';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.predictive_feature_run_dependencies d WHERE d.feature_run_id = target AND d.feature_definition_id = f.feature_version) THEN
    RAISE EXCEPTION 'predictive-feature-run-definition-missing' USING ERRCODE = '23514';
  END IF;
  IF f.status = 'ready-inputs' AND EXISTS (
      WITH profiles AS (SELECT DISTINCT o.profile_id FROM public.predictive_feature_run_dependencies d
        JOIN public.predictive_observations o ON o.id = d.observation_id WHERE d.feature_run_id = target)
      SELECT 1 FROM profiles pr WHERE NOT EXISTS (SELECT 1 FROM public.predictive_feature_run_dependencies rd WHERE rd.feature_run_id = target
        AND rd.rights_decision_id = public.predictive_rights_in_force(pr.profile_id, f.recorded_at, f.recorded_at)
        AND public.predictive_rights_allow(pr.profile_id, f.recorded_at, f.recorded_at, 'model-input'))) THEN
    RAISE EXCEPTION 'predictive-feature-run-rights-not-in-force' USING ERRCODE = '23514';
  END IF;
  synthetic := EXISTS (SELECT 1 FROM public.predictive_feature_run_dependencies d JOIN public.predictive_observations o ON o.id = d.observation_id
    JOIN public.predictive_source_profiles sp ON sp.id = o.profile_id WHERE d.feature_run_id = target AND sp.purpose = 'synthetic-test');
  IF synthetic <> (f.mode = 'synthetic-proof') OR (f.mode = 'synthetic-proof' AND NOT public.predictive_harness_session()) THEN
    RAISE EXCEPTION 'predictive-feature-run-mode-invalid' USING ERRCODE = '23514';
  END IF;
  RETURN NULL;
END
$$;
CREATE CONSTRAINT TRIGGER predictive_check_feature_runs AFTER INSERT ON public.predictive_feature_runs DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION public.predictive_feature_run_check();
-- A run and its manifest are written in one transaction and then sealed: a
-- dependency for a run created in an earlier transaction is refused, so the
-- single run-level deferred check above covers every dependency.
CREATE FUNCTION public.predictive_feature_run_dependency_guard() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM public.predictive_feature_runs f WHERE f.id = NEW.feature_run_id
      AND f.xmin::text::bigint = pg_catalog.pg_current_xact_id()::text::bigint % 4294967296) THEN
    RAISE EXCEPTION 'predictive-feature-run-sealed' USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END
$$;
CREATE TRIGGER predictive_feature_run_dependencies_sealed BEFORE INSERT ON public.predictive_feature_run_dependencies FOR EACH ROW EXECUTE FUNCTION public.predictive_feature_run_dependency_guard();

-- The only way to save a feature run. It creates the run and its complete
-- manifest in one call and stamps recorded_at from clock_timestamp(), read once
-- after taking every evidence profile's lock (shared with rights inserts), so a
-- delayed transaction cannot keep an earlier time. Rights in force at that
-- instant are recomputed here, never taken from the caller. READ COMMITTED is
-- required so each statement sees rights committed before the locks were granted.
-- execution_digest is SHA-256 over unit-separated fields, with list items
-- record-separated; IDs cannot contain control characters, so it is unambiguous.
-- Mirrored by executionDigest() in featureRuns.ts.
CREATE FUNCTION public.predictive_record_feature_run(run jsonb, dependencies jsonb) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $$
DECLARE
  profiles text[]; profile text; recorded timestamptz; rights text[]; policies text[]; definitions text[]; observations text[]; decisions text[];
  blocked boolean := false; digest_input text; execution text; run_id text; stamp text;
BEGIN
  IF NOT pg_catalog.pg_has_role(session_user, 'predictive_recorder', 'MEMBER') THEN
    RAISE EXCEPTION 'predictive-recorder-not-authorized' USING ERRCODE = '42501';
  END IF;
  IF pg_catalog.current_setting('transaction_isolation') <> 'read committed' THEN
    RAISE EXCEPTION 'predictive-recorder-isolation-refused' USING ERRCODE = '25001';
  END IF;
  IF jsonb_typeof(run) <> 'object' OR jsonb_typeof(dependencies) <> 'object'
      OR (SELECT array_agg(k ORDER BY k COLLATE "C") FROM jsonb_object_keys(run) k) IS DISTINCT FROM
        ARRAY['bundleSha256','candidate','codeVersion','computedAt','cutoff','featureVersion','gameId','inputDigest','mode','playerId','reasons','status']
      OR (SELECT array_agg(k ORDER BY k COLLATE "C") FROM jsonb_object_keys(dependencies) k) IS DISTINCT FROM
        ARRAY['decisions','featureDefinitions','observations','policies'] THEN
    RAISE EXCEPTION 'predictive-feature-run-invalid' USING ERRCODE = '23514';
  END IF;
  observations := ARRAY(SELECT DISTINCT v COLLATE "C" FROM jsonb_array_elements_text(dependencies->'observations') v ORDER BY 1);
  decisions := ARRAY(SELECT DISTINCT v COLLATE "C" FROM jsonb_array_elements_text(dependencies->'decisions') v ORDER BY 1);
  policies := ARRAY(SELECT DISTINCT v COLLATE "C" FROM jsonb_array_elements_text(dependencies->'policies') v ORDER BY 1);
  definitions := ARRAY(SELECT DISTINCT v COLLATE "C" FROM jsonb_array_elements_text(dependencies->'featureDefinitions') v ORDER BY 1);
  IF EXISTS (SELECT 1 FROM unnest(policies || definitions || ARRAY[run->>'featureVersion', run->>'codeVersion']) v WHERE v ~ '[\x01-\x1f\x7f]' OR v IS NULL) THEN
    RAISE EXCEPTION 'predictive-feature-run-invalid' USING ERRCODE = '23514';
  END IF;
  profiles := ARRAY(SELECT DISTINCT o.profile_id COLLATE "C" FROM public.predictive_observations o WHERE o.id = ANY(observations) ORDER BY 1);
  FOREACH profile IN ARRAY profiles LOOP PERFORM pg_catalog.pg_advisory_xact_lock(520053, pg_catalog.hashtext(profile)); END LOOP;
  recorded := pg_catalog.date_trunc('milliseconds', pg_catalog.clock_timestamp());
  stamp := to_char(recorded AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"');
  rights := ARRAY(SELECT DISTINCT r COLLATE "C" FROM (SELECT public.predictive_rights_in_force(p, recorded, recorded) AS r FROM unnest(profiles) p) x
    WHERE r IS NOT NULL ORDER BY 1);
  digest_input := concat_ws(E'\x1f', run->>'inputDigest', array_to_string(rights, E'\x1e'), array_to_string(policies, E'\x1e'),
    run->>'featureVersion', run->>'codeVersion', run->>'computedAt', stamp);
  execution := encode(sha256(convert_to(digest_input, 'UTF8')), 'hex');
  run_id := 'feature-run:' || execution;
  INSERT INTO public.predictive_feature_runs (id,mode,feature_version,candidate,player_id,game_id,cutoff,computed_at,recorded_at,code_version,
    status,reasons,input_digest,execution_digest,bundle_blob_sha256)
  VALUES (run_id, run->>'mode', run->>'featureVersion', run->>'candidate', run->>'playerId', (run->>'gameId')::uuid, (run->>'cutoff')::timestamptz,
    (run->>'computedAt')::timestamptz, recorded, run->>'codeVersion', run->>'status', ARRAY(SELECT jsonb_array_elements_text(run->'reasons')),
    run->>'inputDigest', execution, run->>'bundleSha256');
  INSERT INTO public.predictive_feature_run_dependencies (feature_run_id, observation_id) SELECT run_id, v FROM unnest(observations) v;
  INSERT INTO public.predictive_feature_run_dependencies (feature_run_id, decision_id) SELECT run_id, v FROM unnest(decisions) v;
  INSERT INTO public.predictive_feature_run_dependencies (feature_run_id, rights_decision_id) SELECT run_id, v FROM unnest(rights) v;
  INSERT INTO public.predictive_feature_run_dependencies (feature_run_id, policy_id) SELECT run_id, v FROM unnest(policies) v;
  INSERT INTO public.predictive_feature_run_dependencies (feature_run_id, feature_definition_id) SELECT run_id, v FROM unnest(definitions) v;
  -- The deferred run-level check still runs at commit, against this recorded_at.
  RETURN jsonb_build_object('featureRunId', run_id, 'recordedAt', stamp, 'executionDigest', execution, 'rightsDecisions', to_jsonb(rights));
END
$$;

-- feature-run-retention-v1: an unpinned run expires 90 days after recording.
-- A pin keeps it until an unpin event; provider deletions apply regardless.
CREATE FUNCTION public.predictive_feature_run_expired(run_id text, t timestamptz) RETURNS boolean LANGUAGE sql STABLE AS $$
  SELECT f.recorded_at + interval '90 days' <= t AND NOT EXISTS (SELECT 1 FROM public.predictive_feature_run_pins p
    WHERE p.feature_run_id = f.id AND p.pinned_at <= t AND NOT EXISTS (SELECT 1 FROM public.predictive_feature_run_unpins u WHERE u.pin_id = p.id AND u.unpinned_at <= t))
  FROM public.predictive_feature_runs f WHERE f.id = run_id
$$;

-- retention-policy-v1. Owner-run scoped deletion, outside the append-only write
-- path. An event row is written once, complete, by predictive_retention_execute;
-- tombstones exist only for audit_level 'full'. Neither is ever changed.
CREATE FUNCTION public.predictive_retention_scope_valid(reason text, scope jsonb) RETURNS boolean
LANGUAGE plpgsql IMMUTABLE AS $$
DECLARE keys text[];
BEGIN
  IF jsonb_typeof(scope) <> 'object' THEN RETURN false; END IF;
  keys := ARRAY(SELECT k FROM jsonb_object_keys(scope) k ORDER BY k COLLATE "C");
  IF scope->>'kind' = 'feature-run-expiry' THEN
    RETURN reason = 'expiry' AND keys = ARRAY['asOf','kind'] AND jsonb_typeof(scope->'asOf') = 'string' AND public.predictive_instant(scope->>'asOf');
  END IF;
  IF scope->>'kind' <> 'source' OR reason = 'expiry' OR keys <> ARRAY['capturedBefore','capturedFrom','kind','profileIds']
      OR jsonb_typeof(scope->'profileIds') <> 'array' OR jsonb_array_length(scope->'profileIds') NOT BETWEEN 1 AND 64
      OR EXISTS (SELECT 1 FROM jsonb_array_elements(scope->'profileIds') e WHERE jsonb_typeof(e) <> 'string')
      OR ARRAY(SELECT e FROM jsonb_array_elements_text(scope->'profileIds') WITH ORDINALITY x(e, n) ORDER BY n)
        <> ARRAY(SELECT DISTINCT e COLLATE "C" FROM jsonb_array_elements_text(scope->'profileIds') e ORDER BY 1) THEN
    RETURN false;
  END IF;
  IF jsonb_typeof(scope->'capturedFrom') <> 'null' AND NOT (jsonb_typeof(scope->'capturedFrom') = 'string' AND public.predictive_instant(scope->>'capturedFrom')) THEN RETURN false; END IF;
  IF jsonb_typeof(scope->'capturedBefore') <> 'null' AND NOT (jsonb_typeof(scope->'capturedBefore') = 'string' AND public.predictive_instant(scope->>'capturedBefore')) THEN RETURN false; END IF;
  RETURN scope->>'capturedFrom' IS NULL OR scope->>'capturedBefore' IS NULL OR (scope->>'capturedFrom')::timestamptz < (scope->>'capturedBefore')::timestamptz;
EXCEPTION WHEN OTHERS THEN RETURN false;
END
$$;

CREATE TABLE public.predictive_retention_events (
  id text PRIMARY KEY CHECK (length(id) BETWEEN 1 AND 256 AND id !~ '[\x01-\x1f\x7f]'),
  reason text NOT NULL CHECK (reason IN ('expiry','rights-revoked','provider-request','owner-request')),
  authority text NOT NULL CHECK (length(authority) BETWEEN 1 AND 256 AND authority !~ '[[:cntrl:]]'),
  decided_at timestamptz NOT NULL CHECK (isfinite(decided_at) AND decided_at = date_trunc('milliseconds', decided_at)),
  -- Deterministic: re-applying it to a restored backup removes the same rows.
  scope_descriptor jsonb NOT NULL CHECK (public.predictive_retention_scope_valid(reason, scope_descriptor) IS TRUE),
  audit_level text NOT NULL CHECK (audit_level IN ('full','digest-only')),
  removed_counts jsonb NOT NULL CHECK (jsonb_typeof(removed_counts) = 'object'),
  removed_ids_digest text NOT NULL CHECK (removed_ids_digest ~ '^[a-f0-9]{64}$'),
  executed_at timestamptz NOT NULL CHECK (isfinite(executed_at) AND executed_at >= decided_at)
);
CREATE TABLE public.predictive_retention_tombstones (
  retention_event_id text NOT NULL REFERENCES public.predictive_retention_events(id),
  target_kind text NOT NULL CHECK (target_kind IN ('observation','artifact','capture','decision','label','feature-run','pin','blob')),
  target_id text NOT NULL CHECK (length(target_id) BETWEEN 1 AND 256),
  PRIMARY KEY (retention_event_id, target_kind, target_id)
);
-- Control state, not evidence: one row per executing transaction, inserted and
-- removed by predictive_retention_execute. No role is granted any privilege.
CREATE TABLE public.predictive_retention_authorizations (
  txid xid8 PRIMARY KEY,
  retention_event_id text NOT NULL
);

-- Control state, not evidence: blob files whose rows a retention event deleted
-- and that are not yet confirmed removed from the artifact store. The owner path
-- drains it under the per-digest lock; a crash or failed unlink leaves the row
-- for a retry. A row is removed once its file is gone or its blob is referenced
-- again. No role is granted any privilege.
CREATE TABLE public.predictive_blob_removals (
  storage_ref text PRIMARY KEY CHECK (storage_ref ~ '^[a-f0-9]{64}\.(json|csv)$'),
  queued_at timestamptz NOT NULL CHECK (isfinite(queued_at))
);

CREATE FUNCTION public.predictive_retention_audit_immutable() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN RAISE EXCEPTION 'predictive-append-only' USING ERRCODE = '23514'; END
$$;
CREATE TRIGGER predictive_retention_events_immutable BEFORE UPDATE OR DELETE ON public.predictive_retention_events FOR EACH ROW EXECUTE FUNCTION public.predictive_retention_audit_immutable();
CREATE TRIGGER predictive_retention_tombstones_immutable BEFORE UPDATE OR DELETE ON public.predictive_retention_tombstones FOR EACH ROW EXECUTE FUNCTION public.predictive_retention_audit_immutable();
CREATE TRIGGER predictive_retention_events_no_truncate BEFORE TRUNCATE ON public.predictive_retention_events FOR EACH STATEMENT EXECUTE FUNCTION public.predictive_retention_audit_immutable();
CREATE TRIGGER predictive_retention_tombstones_no_truncate BEFORE TRUNCATE ON public.predictive_retention_tombstones FOR EACH STATEMENT EXECUTE FUNCTION public.predictive_retention_audit_immutable();

-- Computes the deletion closure and removes it in dependency order:
--   1. observations in scope plus every descendant in their source chains;
--   2. their links, then the artifacts in scope with all their captures;
--   3. decisions with any deleted input, plus their descendants;
--   4. labels citing any deleted decision, observation or capture, plus later versions;
--   5. feature runs depending on any of the above (or expired), with dependencies, pins, unpins;
--   6. blobs no longer referenced by any artifact or feature run.
-- Ordinary foreign keys stay, without CASCADE: an incomplete closure fails the
-- transaction. Blob files are removed by the owner CLI after commit.
CREATE FUNCTION public.predictive_retention_execute(event_id text, event_reason text, event_authority text, event_decided_at timestamptz,
  event_scope jsonb, event_audit_level text) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $$
DECLARE
  profiles text[]; captured_from timestamptz; captured_before timestamptz; as_of timestamptz;
  arts text[] := '{}'; caps text[] := '{}'; obs text[] := '{}'; decs text[] := '{}'; labs text[] := '{}';
  runs text[] := '{}'; pins text[] := '{}'; blobs text[] := '{}'; refs text[];
  removed_kinds text[]; removed_ids text[]; counts jsonb; ids_digest text; links integer; inputs integer; dependencies integer; unpins integer;
BEGIN
  IF NOT pg_catalog.pg_has_role(session_user, 'predictive_retention_owner', 'MEMBER') THEN
    RAISE EXCEPTION 'predictive-retention-not-authorized' USING ERRCODE = '42501';
  END IF;
  IF event_decided_at IS NULL OR event_decided_at > pg_catalog.now() OR NOT public.predictive_retention_scope_valid(event_reason, event_scope) THEN
    RAISE EXCEPTION 'predictive-retention-invalid' USING ERRCODE = '23514';
  END IF;
  IF event_scope->>'kind' = 'source' THEN
    profiles := ARRAY(SELECT jsonb_array_elements_text(event_scope->'profileIds'));
    IF EXISTS (SELECT 1 FROM unnest(profiles) p WHERE NOT EXISTS (SELECT 1 FROM public.predictive_source_profiles sp WHERE sp.id = p)) THEN
      RAISE EXCEPTION 'predictive-retention-invalid' USING ERRCODE = '23514';
    END IF;
    captured_from := (event_scope->>'capturedFrom')::timestamptz; captured_before := (event_scope->>'capturedBefore')::timestamptz;
    -- An artifact with any capture in range is removed whole, bytes and captures.
    arts := ARRAY(SELECT DISTINCT a.id FROM public.predictive_artifacts a JOIN public.predictive_captures c ON c.artifact_id = a.id
      WHERE a.profile_id = ANY(profiles) AND (captured_from IS NULL OR c.captured_at >= captured_from)
        AND (captured_before IS NULL OR c.captured_at < captured_before));
    caps := ARRAY(SELECT c.id FROM public.predictive_captures c WHERE c.artifact_id = ANY(arts));
    obs := ARRAY(WITH RECURSIVE chain AS (
        SELECT o.id FROM public.predictive_observations o JOIN public.predictive_artifact_observations l ON l.observation_id = o.id
        WHERE l.artifact_id = ANY(arts) AND o.profile_id = ANY(profiles)
        UNION SELECT n.id FROM public.predictive_observations n JOIN chain ON n.predecessor_id = chain.id)
      SELECT id FROM chain);
    decs := ARRAY(WITH RECURSIVE chain AS (
        SELECT DISTINCT i.decision_id AS id FROM public.predictive_decision_inputs i WHERE i.observation_id = ANY(obs)
        UNION SELECT n.id FROM public.predictive_decisions n JOIN chain ON n.predecessor_id = chain.id)
      SELECT id FROM chain);
    labs := ARRAY(WITH RECURSIVE chain AS (
        SELECT l.id FROM public.predictive_outcome_labels l WHERE l.completion_decision_id = ANY(decs) OR l.participation_decision_id = ANY(decs)
          OR l.reconciliation_decision_id = ANY(decs) OR l.selected_observation_id = ANY(obs) OR l.post_window_capture_id = ANY(caps)
          OR l.player_bridge_observation_id = ANY(obs)
        UNION SELECT n.id FROM public.predictive_outcome_labels n JOIN chain ON n.predecessor_id = chain.id)
      SELECT id FROM chain);
    runs := ARRAY(SELECT DISTINCT d.feature_run_id FROM public.predictive_feature_run_dependencies d
      WHERE d.observation_id = ANY(obs) OR d.decision_id = ANY(decs));
  ELSE
    as_of := (event_scope->>'asOf')::timestamptz;
    IF as_of > pg_catalog.now() THEN RAISE EXCEPTION 'predictive-retention-invalid' USING ERRCODE = '23514'; END IF;
    runs := ARRAY(SELECT f.id FROM public.predictive_feature_runs f WHERE public.predictive_feature_run_expired(f.id, as_of));
  END IF;
  pins := ARRAY(SELECT p.id FROM public.predictive_feature_run_pins p WHERE p.feature_run_id = ANY(runs));
  blobs := ARRAY(SELECT DISTINCT b.sha256 FROM public.predictive_blobs b
    WHERE (b.sha256 IN (SELECT a.blob_sha256 FROM public.predictive_artifacts a WHERE a.id = ANY(arts))
        OR b.sha256 IN (SELECT f.bundle_blob_sha256 FROM public.predictive_feature_runs f WHERE f.id = ANY(runs)))
      AND NOT EXISTS (SELECT 1 FROM public.predictive_artifacts a WHERE a.blob_sha256 = b.sha256 AND NOT a.id = ANY(arts))
      AND NOT EXISTS (SELECT 1 FROM public.predictive_feature_runs f WHERE f.bundle_blob_sha256 = b.sha256 AND NOT f.id = ANY(runs)));
  refs := ARRAY(SELECT b.storage_ref FROM public.predictive_blobs b WHERE b.sha256 = ANY(blobs) ORDER BY b.storage_ref COLLATE "C");

  -- Parallel arrays, never a temp table: a caller could pre-create a pg_temp
  -- relation that this definer function would then use.
  SELECT coalesce(array_agg(k ORDER BY k COLLATE "C", v COLLATE "C"), '{}'), coalesce(array_agg(v ORDER BY k COLLATE "C", v COLLATE "C"), '{}')
    INTO removed_kinds, removed_ids FROM (
      SELECT 'observation', v FROM unnest(obs) v UNION ALL SELECT 'artifact', v FROM unnest(arts) v
      UNION ALL SELECT 'capture', v FROM unnest(caps) v UNION ALL SELECT 'decision', v FROM unnest(decs) v
      UNION ALL SELECT 'label', v FROM unnest(labs) v UNION ALL SELECT 'feature-run', v FROM unnest(runs) v
      UNION ALL SELECT 'pin', v FROM unnest(pins) v UNION ALL SELECT 'blob', v FROM unnest(blobs) v) t(k, v);
  -- The canonical JSON array of {"id","kind"} pairs ordered by (kind, id),
  -- mirrored by retentionIdsDigest() in persistence.ts. JSON escaping keeps it
  -- unambiguous whatever an identifier contains.
  SELECT encode(sha256(convert_to('[' || coalesce(string_agg('{"id":' || to_json(r.v)::text || ',"kind":' || to_json(r.k)::text || '}', ','
      ORDER BY r.n), '') || ']', 'UTF8')), 'hex')
    INTO ids_digest FROM unnest(removed_kinds, removed_ids) WITH ORDINALITY r(k, v, n);
  SELECT count(*) INTO links FROM public.predictive_artifact_observations l WHERE l.observation_id = ANY(obs) OR l.artifact_id = ANY(arts);
  SELECT count(*) INTO inputs FROM public.predictive_decision_inputs i WHERE i.decision_id = ANY(decs);
  SELECT count(*) INTO dependencies FROM public.predictive_feature_run_dependencies d WHERE d.feature_run_id = ANY(runs);
  SELECT count(*) INTO unpins FROM public.predictive_feature_run_unpins u WHERE u.pin_id = ANY(pins);
  counts := jsonb_build_object('observations', cardinality(obs), 'artifacts', cardinality(arts), 'captures', cardinality(caps),
    'decisions', cardinality(decs), 'labels', cardinality(labs), 'featureRuns', cardinality(runs), 'pins', cardinality(pins),
    'blobs', cardinality(blobs), 'links', links, 'decisionInputs', inputs, 'featureRunDependencies', dependencies, 'unpins', unpins);

  INSERT INTO public.predictive_retention_events (id,reason,authority,decided_at,scope_descriptor,audit_level,removed_counts,removed_ids_digest,executed_at)
    VALUES (event_id, event_reason, event_authority, event_decided_at, event_scope, event_audit_level, counts, ids_digest, pg_catalog.now());
  INSERT INTO public.predictive_retention_authorizations (txid, retention_event_id) VALUES (pg_catalog.pg_current_xact_id(), event_id);
  DELETE FROM public.predictive_feature_run_unpins WHERE pin_id = ANY(pins);
  DELETE FROM public.predictive_feature_run_pins WHERE id = ANY(pins);
  DELETE FROM public.predictive_feature_run_dependencies WHERE feature_run_id = ANY(runs);
  DELETE FROM public.predictive_feature_runs WHERE id = ANY(runs);
  DELETE FROM public.predictive_outcome_labels WHERE id = ANY(labs);
  DELETE FROM public.predictive_decision_inputs WHERE decision_id = ANY(decs);
  DELETE FROM public.predictive_decisions WHERE id = ANY(decs);
  DELETE FROM public.predictive_artifact_observations WHERE observation_id = ANY(obs) OR artifact_id = ANY(arts);
  DELETE FROM public.predictive_observations WHERE id = ANY(obs);
  DELETE FROM public.predictive_captures WHERE id = ANY(caps);
  DELETE FROM public.predictive_artifacts WHERE id = ANY(arts);
  DELETE FROM public.predictive_blobs WHERE sha256 = ANY(blobs);
  INSERT INTO public.predictive_blob_removals (storage_ref, queued_at) SELECT r, pg_catalog.now() FROM unnest(refs) r ON CONFLICT DO NOTHING;
  IF event_audit_level = 'full' THEN
    INSERT INTO public.predictive_retention_tombstones (retention_event_id, target_kind, target_id)
      SELECT event_id, r.k, r.v FROM unnest(removed_kinds, removed_ids) r(k, v);
  END IF;
  DELETE FROM public.predictive_retention_authorizations WHERE txid = pg_catalog.pg_current_xact_id();
  -- Blob references are returned to the caller for file removal, never stored
  -- for digest-only events.
  RETURN jsonb_build_object('eventId', event_id, 'removedCounts', counts, 'removedIdsDigest', ids_digest, 'removedBlobRefs', to_jsonb(refs));
END
$$;

-- Privileges. PostgreSQL grants EXECUTE on new functions to PUBLIC by default;
-- every predictive function is revoked from PUBLIC. Role grants apply only where
-- the roles exist (the disposable harness creates them; hosted role setup is #95).
-- Execute-only filesystem cleanup boundary. No retention caller receives table
-- privileges. Rechecks and acknowledgements require the same session digest lock
-- as publishers; a fresh READ COMMITTED statement sees a completed publisher.
CREATE FUNCTION public.predictive_blob_lock_guard(digest text) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $$
BEGIN
  IF NOT (pg_catalog.pg_has_role(session_user, 'predictive_retention_owner', 'MEMBER')
      OR pg_catalog.pg_has_role(session_user, 'predictive_ingest', 'MEMBER')
      OR pg_catalog.pg_has_role(session_user, 'predictive_recorder', 'MEMBER')) THEN
    RAISE EXCEPTION 'predictive-blob-cleanup-role-refused' USING ERRCODE = '42501';
  END IF;
  IF digest IS NULL OR digest !~ '^[a-f0-9]{64}$' THEN
    RAISE EXCEPTION 'predictive-blob-reference-refused' USING ERRCODE = '23514';
  END IF;
  IF current_setting('transaction_isolation') <> 'read committed' THEN
    RAISE EXCEPTION 'predictive-blob-cleanup-isolation-refused' USING ERRCODE = '25001';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_catalog.pg_locks WHERE locktype = 'advisory' AND pid = pg_catalog.pg_backend_pid()
      AND classid = 520054::oid AND objid = (('x' || substr(digest, 1, 8))::bit(32)::bigint)::oid
      AND objsubid = 2 AND mode = 'ExclusiveLock' AND granted) THEN
    RAISE EXCEPTION 'predictive-blob-lock-required' USING ERRCODE = '55000';
  END IF;
END
$$;
CREATE FUNCTION public.predictive_blob_reference_guard(reference text) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $$
BEGIN
  IF reference IS NULL OR reference !~ '^[a-f0-9]{64}\.(json|csv)$' THEN
    RAISE EXCEPTION 'predictive-blob-reference-refused' USING ERRCODE = '23514';
  END IF;
  PERFORM public.predictive_blob_lock_guard(substr(reference, 1, 64));
END
$$;
CREATE FUNCTION public.predictive_blob_referenced(reference text) RETURNS boolean
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $$
BEGIN
  PERFORM public.predictive_blob_reference_guard(reference);
  RETURN EXISTS (SELECT 1 FROM public.predictive_blobs WHERE storage_ref = reference);
END
$$;
CREATE FUNCTION public.predictive_pending_blob_removals() RETURNS SETOF text
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $$
BEGIN
  IF NOT pg_catalog.pg_has_role(session_user, 'predictive_retention_owner', 'MEMBER') THEN
    RAISE EXCEPTION 'predictive-retention-role-refused' USING ERRCODE = '42501';
  END IF;
  RETURN QUERY SELECT storage_ref FROM public.predictive_blob_removals ORDER BY storage_ref COLLATE "C" LIMIT 1024;
END
$$;
CREATE FUNCTION public.predictive_ack_blob_removal(reference text) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $$
BEGIN
  IF NOT pg_catalog.pg_has_role(session_user, 'predictive_retention_owner', 'MEMBER') THEN
    RAISE EXCEPTION 'predictive-retention-role-refused' USING ERRCODE = '42501';
  END IF;
  PERFORM public.predictive_blob_reference_guard(reference);
  DELETE FROM public.predictive_blob_removals WHERE storage_ref = reference;
END
$$;
CREATE FUNCTION public.predictive_retention_history() RETURNS SETOF public.predictive_retention_events
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $$
BEGIN
  IF NOT pg_catalog.pg_has_role(session_user, 'predictive_retention_owner', 'MEMBER') THEN
    RAISE EXCEPTION 'predictive-retention-role-refused' USING ERRCODE = '42501';
  END IF;
  RETURN QUERY SELECT * FROM public.predictive_retention_events ORDER BY executed_at, id COLLATE "C";
END
$$;
REVOKE ALL ON FUNCTION public.predictive_blob_lock_guard(text), public.predictive_blob_reference_guard(text), public.predictive_blob_referenced(text),
  public.predictive_pending_blob_removals(), public.predictive_ack_blob_removal(text), public.predictive_retention_history() FROM PUBLIC;

REVOKE ALL ON FUNCTION public.predictive_text(jsonb), public.predictive_optional_text(jsonb), public.predictive_instant(text),
  public.predictive_integer(jsonb, numeric, numeric), public.predictive_identity(jsonb, text), public.predictive_entity_key(text, jsonb),
  public.predictive_stats_valid(jsonb), public.predictive_payload_valid(text, jsonb), public.predictive_harness_session(),
  public.predictive_rights_in_force(text, timestamptz, timestamptz), public.predictive_rights_allow(text, timestamptz, timestamptz, text),
  public.predictive_append_only(), public.predictive_rights_check(), public.predictive_publication_check(),
  public.predictive_decision_valid(text, jsonb), public.predictive_decision_check(), public.predictive_absence_valid(text),
  public.predictive_decision_current(text, timestamptz), public.predictive_label_eligible_final_at(timestamptz), public.predictive_label_check(),
  public.predictive_snaps_valid(text, jsonb), public.predictive_observation_usable(text, timestamptz), public.predictive_unpin_check(), public.predictive_feature_run_check(), public.predictive_feature_run_expired(text, timestamptz),
  public.predictive_feature_run_dependency_guard(), public.predictive_retention_scope_valid(text, jsonb),
  public.predictive_retention_audit_immutable(),
  public.predictive_retention_execute(text, text, text, timestamptz, jsonb, text),
  public.predictive_record_feature_run(jsonb, jsonb) FROM PUBLIC;
DO $grants$
BEGIN
  IF EXISTS (SELECT 1 FROM pg_catalog.pg_roles WHERE rolname = 'predictive_ingest') THEN
    GRANT EXECUTE ON FUNCTION public.predictive_blob_referenced(text) TO predictive_ingest;
    GRANT EXECUTE ON FUNCTION public.predictive_text(jsonb), public.predictive_optional_text(jsonb), public.predictive_instant(text),
      public.predictive_integer(jsonb, numeric, numeric), public.predictive_identity(jsonb, text), public.predictive_entity_key(text, jsonb),
      public.predictive_stats_valid(jsonb), public.predictive_snaps_valid(text, jsonb), public.predictive_payload_valid(text, jsonb), public.predictive_harness_session(),
      public.predictive_rights_in_force(text, timestamptz, timestamptz), public.predictive_rights_allow(text, timestamptz, timestamptz, text),
      public.predictive_append_only(), public.predictive_rights_check(), public.predictive_publication_check(),
      public.predictive_decision_valid(text, jsonb), public.predictive_decision_check(), public.predictive_absence_valid(text),
      public.predictive_decision_current(text, timestamptz), public.predictive_label_eligible_final_at(timestamptz), public.predictive_label_check(),
      public.predictive_observation_usable(text, timestamptz) TO predictive_ingest;
    GRANT SELECT, INSERT ON public.predictive_source_profiles, public.predictive_rights_decisions, public.predictive_blobs,
      public.predictive_ingestion_runs, public.predictive_run_rights, public.predictive_artifacts, public.predictive_captures,
      public.predictive_games, public.predictive_observations, public.predictive_artifact_observations,
      public.predictive_decisions, public.predictive_decision_inputs, public.predictive_outcome_labels,
      public.predictive_profile_identity_links TO predictive_ingest;
    GRANT SELECT ON public.predictive_teams TO predictive_ingest;
  END IF;
  IF EXISTS (SELECT 1 FROM pg_catalog.pg_roles WHERE rolname = 'predictive_replay') THEN
    GRANT EXECUTE ON FUNCTION public.predictive_rights_in_force(text, timestamptz, timestamptz),
      public.predictive_rights_allow(text, timestamptz, timestamptz, text) TO predictive_replay;
    GRANT SELECT ON public.predictive_source_profiles, public.predictive_rights_decisions, public.predictive_blobs,
      public.predictive_ingestion_runs, public.predictive_run_rights, public.predictive_artifacts, public.predictive_captures,
      public.predictive_teams, public.predictive_games, public.predictive_observations, public.predictive_artifact_observations,
      public.predictive_decisions, public.predictive_decision_inputs, public.predictive_outcome_labels,
      public.predictive_profile_identity_links TO predictive_replay;
  END IF;
  -- The recorder saves feature runs: it reads evidence for the deferred checks and
  -- writes only blobs and feature-run tables.
  IF EXISTS (SELECT 1 FROM pg_catalog.pg_roles WHERE rolname = 'predictive_recorder') THEN
    GRANT EXECUTE ON FUNCTION public.predictive_blob_referenced(text) TO predictive_recorder;
    GRANT EXECUTE ON FUNCTION public.predictive_rights_in_force(text, timestamptz, timestamptz),
      public.predictive_rights_allow(text, timestamptz, timestamptz, text), public.predictive_harness_session(),
      public.predictive_decision_current(text, timestamptz), public.predictive_feature_run_expired(text, timestamptz) TO predictive_recorder;
    GRANT SELECT ON public.predictive_source_profiles, public.predictive_rights_decisions, public.predictive_ingestion_runs,
      public.predictive_artifacts, public.predictive_captures, public.predictive_games, public.predictive_observations,
      public.predictive_artifact_observations, public.predictive_decisions, public.predictive_decision_inputs TO predictive_recorder;
    -- Runs and manifests are written only through the definer function.
    GRANT EXECUTE ON FUNCTION public.predictive_record_feature_run(jsonb, jsonb) TO predictive_recorder;
    GRANT SELECT ON public.predictive_feature_runs, public.predictive_feature_run_dependencies TO predictive_recorder;
    GRANT SELECT, INSERT ON public.predictive_blobs, public.predictive_feature_run_pins, public.predictive_feature_run_unpins TO predictive_recorder;
  END IF;
  IF EXISTS (SELECT 1 FROM pg_catalog.pg_roles WHERE rolname = 'predictive_replay') THEN
    GRANT SELECT ON public.predictive_feature_runs, public.predictive_feature_run_dependencies, public.predictive_feature_run_pins,
      public.predictive_feature_run_unpins, public.predictive_retention_events TO predictive_replay;
  END IF;
  -- The retention owner can only execute the definer function; it holds no
  -- table privilege, and no role holds UPDATE, DELETE or TRUNCATE.
  IF EXISTS (SELECT 1 FROM pg_catalog.pg_roles WHERE rolname = 'predictive_retention_owner') THEN
    GRANT EXECUTE ON FUNCTION public.predictive_retention_execute(text, text, text, timestamptz, jsonb, text),
      public.predictive_pending_blob_removals(), public.predictive_blob_referenced(text), public.predictive_blob_lock_guard(text),
      public.predictive_ack_blob_removal(text), public.predictive_retention_history() TO predictive_retention_owner;
  END IF;
END
$grants$;

-- Creator-corpus projection (#90). The owner's private files remain source
-- truth. Permanent owner events and gate registrations are append-only; API
-- evidence is a replace-or-delete snapshot with its own 30-day lifecycle.

CREATE FUNCTION public.corpus_append_only() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  RAISE EXCEPTION 'corpus-append-only' USING ERRCODE = '23514';
END
$$;

CREATE FUNCTION public.corpus_api_replace_only() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  RAISE EXCEPTION 'corpus-api-replace-required' USING ERRCODE = '23514';
END
$$;

CREATE TABLE public.corpus_imports (
  import_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  imported_at timestamptz NOT NULL DEFAULT date_trunc('milliseconds', clock_timestamp())
    CHECK (isfinite(imported_at) AND imported_at = date_trunc('milliseconds', imported_at)),
  importer_version varchar(64) NOT NULL CHECK (importer_version ~ '^[a-z0-9][a-z0-9.-]{0,63}$'),
  rule_version varchar(8) NOT NULL CHECK (rule_version ~ '^v[0-9]{1,3}$'),
  registration_fingerprint varchar(64) NOT NULL CHECK (registration_fingerprint ~ '^[a-f0-9]{64}$'),
  gate_fingerprint varchar(64) NOT NULL CHECK (gate_fingerprint ~ '^[a-f0-9]{64}$'),
  capture_input_fingerprint varchar(64) NOT NULL CHECK (capture_input_fingerprint ~ '^[a-f0-9]{64}$'),
  decision_input_fingerprint varchar(64) NOT NULL CHECK (decision_input_fingerprint ~ '^[a-f0-9]{64}$'),
  discovery_input_fingerprint varchar(64) NOT NULL CHECK (discovery_input_fingerprint ~ '^[a-f0-9]{64}$'),
  capture_event_count integer NOT NULL CHECK (capture_event_count >= 0),
  decision_event_count integer NOT NULL CHECK (decision_event_count >= 0),
  api_video_count integer NOT NULL CHECK (api_video_count >= 0),
  UNIQUE (importer_version, rule_version, registration_fingerprint, gate_fingerprint,
    capture_input_fingerprint, decision_input_fingerprint, discovery_input_fingerprint)
);

CREATE TABLE public.corpus_capture_events (
  creator_key varchar(32) NOT NULL CHECK (creator_key ~ '^[a-z0-9][a-z0-9-]{0,31}$'),
  log_position integer NOT NULL CHECK (log_position > 0),
  event_fingerprint varchar(64) NOT NULL CHECK (event_fingerprint ~ '^[a-f0-9]{64}$'),
  video_id varchar(11) NOT NULL CHECK (video_id ~ '^[A-Za-z0-9_-]{11}$'),
  event_kind varchar(11) NOT NULL CHECK (event_kind IN ('captured','replaced','unavailable')),
  published_date date NOT NULL,
  published_date_precision varchar(3) NOT NULL CHECK (published_date_precision = 'day'),
  published_date_provenance varchar(48) NOT NULL
    CHECK (published_date_provenance = 'owner-confirmed-video-page-pacific-date'),
  transcript_source varchar(32) NOT NULL CHECK (transcript_source = 'manual-owner-paste'),
  usage_status varchar(32) NOT NULL CHECK (usage_status = 'internal-research-only'),
  caption_kind varchar(14) CHECK (caption_kind IN ('unknown','auto-generated','uploaded')),
  transcript_sha256 varchar(64) CHECK (transcript_sha256 ~ '^[a-f0-9]{64}$'),
  transcript_characters integer CHECK (transcript_characters > 0 AND transcript_characters <= 512000),
  captured_at timestamptz NOT NULL
    CHECK (isfinite(captured_at) AND captured_at = date_trunc('milliseconds', captured_at)),
  first_import_id bigint NOT NULL REFERENCES public.corpus_imports(import_id),
  PRIMARY KEY (creator_key, log_position),
  CHECK ((event_kind = 'unavailable' AND caption_kind IS NULL AND transcript_sha256 IS NULL AND transcript_characters IS NULL)
    OR (event_kind IN ('captured','replaced') AND caption_kind IS NOT NULL
      AND transcript_sha256 IS NOT NULL AND transcript_characters IS NOT NULL))
);

CREATE INDEX corpus_capture_events_video_idx
  ON public.corpus_capture_events (creator_key, video_id, log_position DESC);

CREATE TABLE public.corpus_decision_events (
  creator_key varchar(32) NOT NULL CHECK (creator_key ~ '^[a-z0-9][a-z0-9-]{0,31}$'),
  file_position integer NOT NULL CHECK (file_position > 0),
  event_fingerprint varchar(64) NOT NULL CHECK (event_fingerprint ~ '^[a-f0-9]{64}$'),
  video_id varchar(11) NOT NULL CHECK (video_id ~ '^[A-Za-z0-9_-]{11}$'),
  decision_kind varchar(7) NOT NULL CHECK (decision_kind IN ('include','exclude','clear')),
  reason varchar(500) NOT NULL CHECK (length(btrim(reason)) > 0 AND reason !~ '[[:cntrl:]]'),
  rule_version varchar(8) NOT NULL CHECK (rule_version ~ '^v[0-9]{1,3}$'),
  decided_at timestamptz NOT NULL
    CHECK (isfinite(decided_at) AND decided_at = date_trunc('milliseconds', decided_at)),
  first_import_id bigint NOT NULL REFERENCES public.corpus_imports(import_id),
  PRIMARY KEY (creator_key, file_position)
);

CREATE INDEX corpus_decision_events_video_idx
  ON public.corpus_decision_events (creator_key, video_id, decided_at DESC, file_position DESC);

CREATE TABLE public.corpus_gate_registrations (
  commitment_digest varchar(64) PRIMARY KEY CHECK (commitment_digest ~ '^[a-f0-9]{64}$'),
  commitment_algorithm varchar(16) NOT NULL CHECK (commitment_algorithm = 'sha256'),
  commitment_version integer NOT NULL CHECK (commitment_version > 0),
  eligible_creator_count integer NOT NULL CHECK (eligible_creator_count BETWEEN 1 AND 20),
  minimum_reviewed_gradable_picks_overall integer NOT NULL CHECK (minimum_reviewed_gradable_picks_overall > 0),
  minimum_reviewed_gradable_picks_per_creator integer NOT NULL CHECK (minimum_reviewed_gradable_picks_per_creator > 0),
  maximum_feature_count integer NOT NULL CHECK (maximum_feature_count > 0),
  start_season integer NOT NULL CHECK (start_season BETWEEN 1920 AND 9999),
  start_week integer NOT NULL CHECK (start_week BETWEEN 1 AND 18),
  end_season integer NOT NULL CHECK (end_season BETWEEN 1920 AND 9999),
  end_week integer NOT NULL CHECK (end_week BETWEEN 1 AND 18),
  collection_season_type varchar(7) NOT NULL CHECK (collection_season_type = 'regular'),
  rule_version varchar(8) NOT NULL CHECK (rule_version ~ '^v[0-9]{1,3}$'),
  registered_at timestamptz NOT NULL
    CHECK (isfinite(registered_at) AND registered_at = date_trunc('milliseconds', registered_at)),
  imported_at timestamptz NOT NULL DEFAULT date_trunc('milliseconds', clock_timestamp())
    CHECK (isfinite(imported_at) AND imported_at = date_trunc('milliseconds', imported_at)
      AND imported_at >= registered_at),
  first_import_id bigint NOT NULL UNIQUE REFERENCES public.corpus_imports(import_id),
  CHECK (end_season > start_season OR (end_season = start_season AND end_week >= start_week)),
  CHECK (minimum_reviewed_gradable_picks_overall >= minimum_reviewed_gradable_picks_per_creator)
);

CREATE TABLE public.corpus_api_videos (
  creator_key varchar(32) NOT NULL CHECK (creator_key ~ '^[a-z0-9][a-z0-9-]{0,31}$'),
  video_id varchar(11) NOT NULL CHECK (video_id ~ '^[A-Za-z0-9_-]{11}$'),
  published_at timestamptz NOT NULL
    CHECK (isfinite(published_at) AND published_at = date_trunc('milliseconds', published_at)),
  duration_seconds integer CHECK (duration_seconds >= 0),
  live_broadcast_content varchar(8) NOT NULL CHECK (live_broadcast_content IN ('none','upcoming','live')),
  api_fetched_at timestamptz NOT NULL
    CHECK (isfinite(api_fetched_at) AND api_fetched_at = date_trunc('milliseconds', api_fetched_at)
      AND api_fetched_at >= published_at),
  season integer CHECK (season BETWEEN 1920 AND 9999),
  week integer CHECK (week BETWEEN 1 AND 18),
  season_week_provenance varchar(64) NOT NULL
    CHECK (season_week_provenance ~ '^[a-z0-9][a-z0-9.-]{2,63}$'),
  classification_status varchar(12) NOT NULL
    CHECK (classification_status IN ('candidate','needs-review','excluded')),
  classification_reasons varchar(64)[] NOT NULL
    CHECK (cardinality(classification_reasons) BETWEEN 1 AND 18
      AND array_position(classification_reasons, NULL) IS NULL
      AND classification_reasons <@ ARRAY[
        'prop-and-nfl-signal-in-title','invalid-published-at','outside-registered-regular-season',
        'after-registered-end-week','not-yet-vod','short-form','other-league-in-title','fantasy-in-title',
        'no-prop-signal','no-nfl-signal','duration-unknown','mixed-league-title','title-week-mismatch',
        'multiple-week-references','nfl-signal-team-name-only','nfl-signal-description-only',
        'picks-without-prop-signal','prop-signal-description-only'
      ]::varchar(64)[]),
  classification_rule_version varchar(8) NOT NULL CHECK (classification_rule_version ~ '^v[0-9]{1,3}$'),
  review_status varchar(12) NOT NULL CHECK (review_status IN ('present','needs-review','excluded')),
  snapshot_import_id bigint NOT NULL REFERENCES public.corpus_imports(import_id),
  PRIMARY KEY (creator_key, video_id),
  CHECK ((season IS NULL) = (week IS NULL))
);

CREATE INDEX corpus_api_videos_expiry_idx ON public.corpus_api_videos (api_fetched_at);
CREATE INDEX corpus_api_videos_slot_idx
  ON public.corpus_api_videos (creator_key, season, week, review_status);

CREATE TRIGGER corpus_imports_immutable BEFORE UPDATE OR DELETE ON public.corpus_imports
  FOR EACH ROW EXECUTE FUNCTION public.corpus_append_only();
CREATE TRIGGER corpus_capture_events_immutable BEFORE UPDATE OR DELETE ON public.corpus_capture_events
  FOR EACH ROW EXECUTE FUNCTION public.corpus_append_only();
CREATE TRIGGER corpus_decision_events_immutable BEFORE UPDATE OR DELETE ON public.corpus_decision_events
  FOR EACH ROW EXECUTE FUNCTION public.corpus_append_only();
CREATE TRIGGER corpus_gate_registrations_immutable BEFORE UPDATE OR DELETE ON public.corpus_gate_registrations
  FOR EACH ROW EXECUTE FUNCTION public.corpus_append_only();
CREATE TRIGGER corpus_imports_no_truncate BEFORE TRUNCATE ON public.corpus_imports
  FOR EACH STATEMENT EXECUTE FUNCTION public.corpus_append_only();
CREATE TRIGGER corpus_capture_events_no_truncate BEFORE TRUNCATE ON public.corpus_capture_events
  FOR EACH STATEMENT EXECUTE FUNCTION public.corpus_append_only();
CREATE TRIGGER corpus_decision_events_no_truncate BEFORE TRUNCATE ON public.corpus_decision_events
  FOR EACH STATEMENT EXECUTE FUNCTION public.corpus_append_only();
CREATE TRIGGER corpus_gate_registrations_no_truncate BEFORE TRUNCATE ON public.corpus_gate_registrations
  FOR EACH STATEMENT EXECUTE FUNCTION public.corpus_append_only();
CREATE TRIGGER corpus_api_videos_no_update BEFORE UPDATE ON public.corpus_api_videos
  FOR EACH ROW EXECUTE FUNCTION public.corpus_api_replace_only();
CREATE TRIGGER corpus_api_videos_no_truncate BEFORE TRUNCATE ON public.corpus_api_videos
  FOR EACH STATEMENT EXECUTE FUNCTION public.corpus_api_replace_only();

COMMENT ON TABLE public.corpus_imports IS 'Append-only audit of validated local creator-corpus snapshot publications; contains fingerprints and counts, never source content.';
COMMENT ON TABLE public.corpus_capture_events IS 'Append-only projection of owner capture events; transcript text, notes and reasons remain only in the private source log.';
COMMENT ON TABLE public.corpus_decision_events IS 'Append-only projection of owner include, exclude and clear decisions in source order.';
COMMENT ON TABLE public.corpus_gate_registrations IS 'Immutable public readiness-gate registrations; private creator keys and salts are never stored.';
COMMENT ON TABLE public.corpus_api_videos IS 'Current refresh-or-delete YouTube API evidence and derived classification; complete creator snapshots are replaced atomically.';
COMMENT ON FUNCTION public.corpus_append_only() IS 'Refuses UPDATE, DELETE and TRUNCATE on permanent creator-corpus audit tables.';
COMMENT ON FUNCTION public.corpus_api_replace_only() IS 'Refuses in-place mutation and TRUNCATE of API evidence; importers replace rows with DELETE plus INSERT.';

-- PostgreSQL grants EXECUTE on new functions to PUBLIC by default. Table and
-- sequence privileges are explicit too, even though their defaults are closed.
REVOKE ALL ON FUNCTION public.corpus_append_only(), public.corpus_api_replace_only() FROM PUBLIC;
REVOKE ALL ON public.corpus_imports, public.corpus_capture_events, public.corpus_decision_events,
  public.corpus_gate_registrations, public.corpus_api_videos FROM PUBLIC;
REVOKE ALL ON SEQUENCE public.corpus_imports_import_id_seq FROM PUBLIC;

-- The role is created only by the disposable/local database setup before this
-- migration. Hosted setup (#95) deliberately does not create it, so empty
-- shared tables grant no hosted mutation path.
DO $grants$
BEGIN
  IF EXISTS (SELECT 1 FROM pg_catalog.pg_roles WHERE rolname = 'corpus_importer') THEN
    GRANT SELECT, INSERT ON public.corpus_imports, public.corpus_capture_events,
      public.corpus_decision_events, public.corpus_gate_registrations TO corpus_importer;
    GRANT SELECT, INSERT, DELETE ON public.corpus_api_videos TO corpus_importer;
    GRANT USAGE, SELECT ON SEQUENCE public.corpus_imports_import_id_seq TO corpus_importer;
  END IF;
END
$grants$;

-- PR B: raw CSV claims, deliberately outside canonical observations/labels.
-- 0003 is released and unchanged. Each complete capture is an immutable
-- snapshot; row ordinal counts parsed records (not physical CSV lines).
CREATE FUNCTION public.predictive_source_projection_valid(data jsonb) RETURNS boolean
LANGUAGE plpgsql STABLE STRICT AS $$
DECLARE fields text[]; stats text[]; parts text[]; field text;
BEGIN
  SELECT array_agg(key ORDER BY key COLLATE "C") INTO fields FROM jsonb_object_keys(data) key;
  FOREACH field IN ARRAY ARRAY['feed','version','rawGameId','rawTeam','rawOpponent','seasonType'] LOOP
    IF jsonb_typeof(data->field) IS DISTINCT FROM 'string' THEN RETURN false; END IF;
  END LOOP;
  IF fields <> ARRAY['feed','missing','playerIdProvider','rawGameId','rawOpponent','rawPlayerId','rawTeam','season','seasonType','values','version','week']
      OR data->>'version' <> 'nflverse-raw-stats-v1' OR data->>'feed' NOT IN ('player','team')
      OR NOT public.predictive_integer(data->'season', 2026, 2026)
      OR NOT public.predictive_integer(data->'week', 1, 22) OR data->>'seasonType' NOT IN ('REG','POST')
      OR data->>'rawGameId' !~ '^[0-9]{4}_[0-9]{2}_[A-Z]{2,3}_[A-Z]{2,3}$' THEN RETURN false; END IF;
  parts := string_to_array(data->>'rawGameId', '_');
  IF parts[1]::integer <> (data->>'season')::integer OR parts[2]::integer <> (data->>'week')::integer
      OR parts[3] = parts[4] OR data->>'rawTeam' = data->>'rawOpponent'
      OR data->>'rawTeam' <> ALL(parts[3:4]) OR data->>'rawOpponent' <> ALL(parts[3:4])
      OR NOT EXISTS (SELECT 1 FROM public.predictive_teams WHERE id = 'nfl:team:' || parts[3])
      OR NOT EXISTS (SELECT 1 FROM public.predictive_teams WHERE id = 'nfl:team:' || parts[4]) THEN RETURN false; END IF;
  IF data->>'feed' = 'player' THEN
    IF data->>'rawPlayerId' !~ '^00-[0-9]{7}$' OR data->>'playerIdProvider' <> 'gsis'
        OR jsonb_typeof(data->'rawPlayerId') <> 'string' OR jsonb_typeof(data->'playerIdProvider') <> 'string' THEN RETURN false; END IF;
  ELSIF data->'rawPlayerId' <> 'null'::jsonb OR data->'playerIdProvider' <> 'null'::jsonb THEN RETURN false; END IF;
  SELECT array_agg(key ORDER BY key COLLATE "C") INTO stats FROM jsonb_object_keys(data->'values') key;
  RETURN stats = ARRAY['attempts','carries','completions','passingInterceptions','passingTds','passingYards','receivingYards','receptions','rushingYards','targets']
    AND public.predictive_stats_valid((data->'values') || jsonb_build_object('missing', data->'missing'));
EXCEPTION WHEN OTHERS THEN RETURN false;
END
$$;

CREATE TABLE public.predictive_source_stats_rows (
  id text PRIMARY KEY CHECK (id ~ '^source-row:[a-f0-9]{64}$'),
  capture_id text NOT NULL REFERENCES public.predictive_captures(id),
  row_ordinal integer NOT NULL CHECK (row_ordinal BETWEEN 1 AND 8192),
  raw_key_sha256 text NOT NULL CHECK (raw_key_sha256 ~ '^[a-f0-9]{64}$'),
  selected_sha256 text NOT NULL CHECK (selected_sha256 ~ '^[a-f0-9]{64}$'),
  projection jsonb CHECK (projection IS NULL OR public.predictive_source_projection_valid(projection) IS TRUE),
  failure_code text CHECK (failure_code IN ('source-stats-context-refused','source-stats-player-refused',
    'source-number-refused','source-stats-denominator-refused','source-stats-scope-refused')),
  CHECK ((projection IS NULL) = (failure_code IS NOT NULL)),
  UNIQUE (capture_id, row_ordinal)
);
CREATE INDEX predictive_source_stats_key_idx ON public.predictive_source_stats_rows (capture_id, raw_key_sha256);
CREATE INDEX predictive_source_capture_scope_idx ON public.predictive_artifacts (profile_id, scope_season) WHERE scope_kind = 'season-file';
CREATE TRIGGER predictive_source_rows_immutable BEFORE UPDATE OR DELETE ON public.predictive_source_stats_rows
  FOR EACH ROW EXECUTE FUNCTION public.predictive_append_only();
CREATE TRIGGER predictive_source_rows_no_truncate BEFORE TRUNCATE ON public.predictive_source_stats_rows
  FOR EACH STATEMENT EXECUTE FUNCTION public.predictive_append_only();

-- A direct SQL writer cannot backdate a raw CSV import either. Original archive
-- times live in captured_at; ingestion is when this database received it.
CREATE FUNCTION public.predictive_source_ingestion_clock() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE profile_id text;
BEGIN
  SELECT p.id INTO profile_id FROM public.predictive_artifacts a JOIN public.predictive_blobs b ON b.sha256=a.blob_sha256
      JOIN public.predictive_source_profiles p ON p.id=a.profile_id WHERE a.id=NEW.artifact_id
      AND b.media_type='text/csv' AND p.parser_version='nflverse-csv-qualification-v1';
  IF profile_id IS NOT NULL THEN
    PERFORM pg_advisory_xact_lock(520053, hashtext(profile_id));
    NEW.ingested_at := date_trunc('milliseconds', clock_timestamp());
  END IF;
  RETURN NEW;
END
$$;
CREATE TRIGGER predictive_source_ingestion_clock BEFORE INSERT ON public.predictive_captures
  FOR EACH ROW EXECUTE FUNCTION public.predictive_source_ingestion_clock();

-- SQL checks the envelope/shape and complete snapshot coverage. Byte/selected-row
-- hashes and exact numeric normalization are independently rechecked on replay.
CREATE FUNCTION public.predictive_source_claim_check() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE cap public.predictive_captures; art public.predictive_artifacts; profile public.predictive_source_profiles;
  media text; n integer; maximum integer; minimum integer; expected_key text;
BEGIN
  IF TG_TABLE_NAME = 'predictive_captures' THEN SELECT * INTO cap FROM public.predictive_captures WHERE id = NEW.id;
  ELSE SELECT * INTO cap FROM public.predictive_captures WHERE id = NEW.capture_id; END IF;
  SELECT * INTO art FROM public.predictive_artifacts WHERE id = cap.artifact_id;
  SELECT * INTO profile FROM public.predictive_source_profiles WHERE id = art.profile_id;
  SELECT media_type INTO media FROM public.predictive_blobs WHERE sha256 = art.blob_sha256;
  -- Existing diagnostic CSVs and the released JSON proof retain their contracts.
  IF TG_TABLE_NAME = 'predictive_captures' AND (media <> 'text/csv' OR profile.parser_version <> 'nflverse-csv-qualification-v1') THEN RETURN NULL; END IF;
  IF media <> 'text/csv' OR profile.parser_version <> 'nflverse-csv-qualification-v1'
      OR profile.allowlist_version <> 'predictive-raw-allowlist-v1' OR profile.feed NOT IN ('player','team')
      OR profile.purpose NOT IN ('source','synthetic-test') OR profile.provider <> 'nflverse'
      OR profile.release_tag IS DISTINCT FROM 'stats_' || profile.feed
      OR profile.asset_pattern IS DISTINCT FROM 'stats_' || profile.feed || '_week_2026.csv'
      OR profile.header_profile_sha256 IS NULL
      OR NOT (CASE profile.feed WHEN 'player' THEN 'player-game-stats' ELSE 'team-game-stats' END = ANY(profile.evidence_kinds))
      OR cap.state <> 'published' OR art.retrieval_kind <> 'full' OR art.scope_kind <> 'season-file'
      OR art.scope_season <> 2026 OR art.scope_filter IS NOT NULL OR cap.published_at IS NOT NULL
      OR cap.available_at <> cap.captured_at OR cap.ingested_at > clock_timestamp()
      OR NOT public.predictive_rights_allow(profile.id, clock_timestamp(), clock_timestamp(), 'internal-research') THEN
    RAISE EXCEPTION 'predictive-source-claim-envelope-invalid' USING ERRCODE = '23514';
  END IF;
  IF TG_TABLE_NAME = 'predictive_captures' THEN
    SELECT count(*), min(row_ordinal), max(row_ordinal) INTO n, minimum, maximum
      FROM public.predictive_source_stats_rows WHERE capture_id = cap.id;
    IF n <> cap.parsed_rows OR n < 1 OR minimum <> 1 OR maximum <> n THEN
      RAISE EXCEPTION 'predictive-source-claim-coverage-invalid' USING ERRCODE = '23514';
    END IF;
  END IF;
  IF TG_TABLE_NAME = 'predictive_source_stats_rows' THEN
    IF NEW.row_ordinal > cap.parsed_rows THEN RAISE EXCEPTION 'predictive-source-claim-coverage-invalid' USING ERRCODE = '23514'; END IF;
    IF NEW.id <> 'source-row:' || encode(sha256(convert_to('[' || to_json(NEW.capture_id)::text || ',' || NEW.row_ordinal::text || ']', 'UTF8')), 'hex') THEN
      RAISE EXCEPTION 'predictive-source-claim-id-invalid' USING ERRCODE = '23514';
    END IF;
    IF NEW.projection IS NOT NULL THEN
      expected_key := '[' || to_json(NEW.projection->>'rawGameId')::text || ',' || to_json(NEW.projection->>'rawTeam')::text
        || CASE profile.feed WHEN 'player' THEN ',' || to_json(NEW.projection->>'rawPlayerId')::text ELSE '' END || ']';
      IF NEW.projection->>'feed' <> profile.feed OR NEW.raw_key_sha256 <> encode(sha256(convert_to(expected_key, 'UTF8')), 'hex') THEN
        RAISE EXCEPTION 'predictive-source-claim-key-invalid' USING ERRCODE = '23514';
      END IF;
    END IF;
  END IF;
  RETURN NULL;
END
$$;
CREATE CONSTRAINT TRIGGER predictive_source_capture_check AFTER INSERT ON public.predictive_captures
  DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION public.predictive_source_claim_check();
CREATE CONSTRAINT TRIGGER predictive_source_row_check AFTER INSERT ON public.predictive_source_stats_rows
  DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION public.predictive_source_claim_check();

-- Staging is not a shortcut into canonical evidence. A later reviewed adapter
-- must add explicit raw-row and bridge bindings before these artifacts can be
-- linked to canonical observations.
CREATE FUNCTION public.predictive_source_canonical_guard() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF EXISTS (SELECT 1 FROM public.predictive_artifacts a JOIN public.predictive_blobs b ON b.sha256 = a.blob_sha256
      JOIN public.predictive_source_profiles p ON p.id = a.profile_id WHERE a.id = NEW.artifact_id
      AND b.media_type = 'text/csv' AND p.parser_version = 'nflverse-csv-qualification-v1') THEN
    RAISE EXCEPTION 'predictive-source-canonical-binding-required' USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END
$$;
CREATE TRIGGER predictive_source_canonical_guard BEFORE INSERT ON public.predictive_artifact_observations
  FOR EACH ROW EXECUTE FUNCTION public.predictive_source_canonical_guard();

ALTER TABLE public.predictive_retention_tombstones DROP CONSTRAINT predictive_retention_tombstones_target_kind_check;
ALTER TABLE public.predictive_retention_tombstones ADD CONSTRAINT predictive_retention_tombstones_target_kind_check
  CHECK (target_kind IN ('observation','artifact','capture','decision','label','feature-run','pin','blob','source-stats-row'));

REVOKE ALL ON public.predictive_source_stats_rows FROM PUBLIC;
REVOKE EXECUTE ON FUNCTION public.predictive_source_projection_valid(jsonb), public.predictive_source_claim_check(),
  public.predictive_source_canonical_guard(), public.predictive_source_ingestion_clock() FROM PUBLIC;
DO $grants$
BEGIN
  IF EXISTS (SELECT 1 FROM pg_catalog.pg_roles WHERE rolname = 'predictive_ingest') THEN
    GRANT SELECT, INSERT ON public.predictive_source_stats_rows TO predictive_ingest;
    GRANT EXECUTE ON FUNCTION public.predictive_source_projection_valid(jsonb), public.predictive_source_claim_check(),
      public.predictive_source_canonical_guard(), public.predictive_source_ingestion_clock() TO predictive_ingest;
  END IF;
  IF EXISTS (SELECT 1 FROM pg_catalog.pg_roles WHERE rolname = 'predictive_replay') THEN
    GRANT SELECT ON public.predictive_source_stats_rows TO predictive_replay;
  END IF;
END
$grants$;

-- Extend the released retention closure for raw source rows. Existing graph,
-- role boundary, locking, audit and queued-file recovery remain identical.
CREATE OR REPLACE FUNCTION public.predictive_retention_execute(event_id text, event_reason text, event_authority text, event_decided_at timestamptz,
  event_scope jsonb, event_audit_level text) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $$
DECLARE
  profiles text[]; captured_from timestamptz; captured_before timestamptz; as_of timestamptz;
  arts text[] := '{}'; caps text[] := '{}'; obs text[] := '{}'; decs text[] := '{}'; labs text[] := '{}';
  runs text[] := '{}'; pins text[] := '{}'; blobs text[] := '{}'; refs text[]; source_rows text[] := '{}';
  removed_kinds text[]; removed_ids text[]; counts jsonb; ids_digest text; links integer; inputs integer; dependencies integer; unpins integer;
BEGIN
  IF NOT pg_catalog.pg_has_role(session_user, 'predictive_retention_owner', 'MEMBER') THEN
    RAISE EXCEPTION 'predictive-retention-not-authorized' USING ERRCODE = '42501';
  END IF;
  IF event_decided_at IS NULL OR event_decided_at > pg_catalog.now() OR NOT public.predictive_retention_scope_valid(event_reason, event_scope) THEN
    RAISE EXCEPTION 'predictive-retention-invalid' USING ERRCODE = '23514';
  END IF;
  IF event_scope->>'kind' = 'source' THEN
    profiles := ARRAY(SELECT jsonb_array_elements_text(event_scope->'profileIds'));
    IF EXISTS (SELECT 1 FROM unnest(profiles) p WHERE NOT EXISTS (SELECT 1 FROM public.predictive_source_profiles sp WHERE sp.id = p)) THEN
      RAISE EXCEPTION 'predictive-retention-invalid' USING ERRCODE = '23514';
    END IF;
    captured_from := (event_scope->>'capturedFrom')::timestamptz; captured_before := (event_scope->>'capturedBefore')::timestamptz;
    -- An artifact with any capture in range is removed whole, bytes and captures.
    arts := ARRAY(SELECT DISTINCT a.id FROM public.predictive_artifacts a JOIN public.predictive_captures c ON c.artifact_id = a.id
      WHERE a.profile_id = ANY(profiles) AND (captured_from IS NULL OR c.captured_at >= captured_from)
        AND (captured_before IS NULL OR c.captured_at < captured_before));
    caps := ARRAY(SELECT c.id FROM public.predictive_captures c WHERE c.artifact_id = ANY(arts));
    obs := ARRAY(WITH RECURSIVE chain AS (
        SELECT o.id FROM public.predictive_observations o JOIN public.predictive_artifact_observations l ON l.observation_id = o.id
        WHERE l.artifact_id = ANY(arts) AND o.profile_id = ANY(profiles)
        UNION SELECT n.id FROM public.predictive_observations n JOIN chain ON n.predecessor_id = chain.id)
      SELECT id FROM chain);
    decs := ARRAY(WITH RECURSIVE chain AS (
        SELECT DISTINCT i.decision_id AS id FROM public.predictive_decision_inputs i WHERE i.observation_id = ANY(obs)
        UNION SELECT n.id FROM public.predictive_decisions n JOIN chain ON n.predecessor_id = chain.id)
      SELECT id FROM chain);
    labs := ARRAY(WITH RECURSIVE chain AS (
        SELECT l.id FROM public.predictive_outcome_labels l WHERE l.completion_decision_id = ANY(decs) OR l.participation_decision_id = ANY(decs)
          OR l.reconciliation_decision_id = ANY(decs) OR l.selected_observation_id = ANY(obs) OR l.post_window_capture_id = ANY(caps)
          OR l.player_bridge_observation_id = ANY(obs)
        UNION SELECT n.id FROM public.predictive_outcome_labels n JOIN chain ON n.predecessor_id = chain.id)
      SELECT id FROM chain);
    runs := ARRAY(SELECT DISTINCT d.feature_run_id FROM public.predictive_feature_run_dependencies d
      WHERE d.observation_id = ANY(obs) OR d.decision_id = ANY(decs));
  ELSE
    as_of := (event_scope->>'asOf')::timestamptz;
    IF as_of > pg_catalog.now() THEN RAISE EXCEPTION 'predictive-retention-invalid' USING ERRCODE = '23514'; END IF;
    runs := ARRAY(SELECT f.id FROM public.predictive_feature_runs f WHERE public.predictive_feature_run_expired(f.id, as_of));
  END IF;
  source_rows := ARRAY(SELECT s.id FROM public.predictive_source_stats_rows s WHERE s.capture_id = ANY(caps));
  pins := ARRAY(SELECT p.id FROM public.predictive_feature_run_pins p WHERE p.feature_run_id = ANY(runs));
  blobs := ARRAY(SELECT DISTINCT b.sha256 FROM public.predictive_blobs b
    WHERE (b.sha256 IN (SELECT a.blob_sha256 FROM public.predictive_artifacts a WHERE a.id = ANY(arts))
        OR b.sha256 IN (SELECT f.bundle_blob_sha256 FROM public.predictive_feature_runs f WHERE f.id = ANY(runs)))
      AND NOT EXISTS (SELECT 1 FROM public.predictive_artifacts a WHERE a.blob_sha256 = b.sha256 AND NOT a.id = ANY(arts))
      AND NOT EXISTS (SELECT 1 FROM public.predictive_feature_runs f WHERE f.bundle_blob_sha256 = b.sha256 AND NOT f.id = ANY(runs)));
  refs := ARRAY(SELECT b.storage_ref FROM public.predictive_blobs b WHERE b.sha256 = ANY(blobs) ORDER BY b.storage_ref COLLATE "C");

  -- Parallel arrays, never a temp table: a caller could pre-create a pg_temp
  -- relation that this definer function would then use.
  SELECT coalesce(array_agg(k ORDER BY k COLLATE "C", v COLLATE "C"), '{}'), coalesce(array_agg(v ORDER BY k COLLATE "C", v COLLATE "C"), '{}')
    INTO removed_kinds, removed_ids FROM (
      SELECT 'observation', v FROM unnest(obs) v UNION ALL SELECT 'artifact', v FROM unnest(arts) v
      UNION ALL SELECT 'capture', v FROM unnest(caps) v UNION ALL SELECT 'decision', v FROM unnest(decs) v
      UNION ALL SELECT 'label', v FROM unnest(labs) v UNION ALL SELECT 'feature-run', v FROM unnest(runs) v
      UNION ALL SELECT 'pin', v FROM unnest(pins) v UNION ALL SELECT 'blob', v FROM unnest(blobs) v
      UNION ALL SELECT 'source-stats-row', v FROM unnest(source_rows) v) t(k, v);
  -- The canonical JSON array of {"id","kind"} pairs ordered by (kind, id),
  -- mirrored by retentionIdsDigest() in persistence.ts. JSON escaping keeps it
  -- unambiguous whatever an identifier contains.
  SELECT encode(sha256(convert_to('[' || coalesce(string_agg('{"id":' || to_json(r.v)::text || ',"kind":' || to_json(r.k)::text || '}', ','
      ORDER BY r.n), '') || ']', 'UTF8')), 'hex')
    INTO ids_digest FROM unnest(removed_kinds, removed_ids) WITH ORDINALITY r(k, v, n);
  SELECT count(*) INTO links FROM public.predictive_artifact_observations l WHERE l.observation_id = ANY(obs) OR l.artifact_id = ANY(arts);
  SELECT count(*) INTO inputs FROM public.predictive_decision_inputs i WHERE i.decision_id = ANY(decs);
  SELECT count(*) INTO dependencies FROM public.predictive_feature_run_dependencies d WHERE d.feature_run_id = ANY(runs);
  SELECT count(*) INTO unpins FROM public.predictive_feature_run_unpins u WHERE u.pin_id = ANY(pins);
  counts := jsonb_build_object('observations', cardinality(obs), 'artifacts', cardinality(arts), 'captures', cardinality(caps),
    'decisions', cardinality(decs), 'labels', cardinality(labs), 'featureRuns', cardinality(runs), 'pins', cardinality(pins),
    'blobs', cardinality(blobs), 'links', links, 'decisionInputs', inputs, 'featureRunDependencies', dependencies, 'unpins', unpins);

  -- Preserve old zero-row event counts/digests for backup re-apply parity.
  IF cardinality(source_rows) > 0 THEN counts := counts || jsonb_build_object('sourceStatsRows', cardinality(source_rows)); END IF;
  INSERT INTO public.predictive_retention_events (id,reason,authority,decided_at,scope_descriptor,audit_level,removed_counts,removed_ids_digest,executed_at)
    VALUES (event_id, event_reason, event_authority, event_decided_at, event_scope, event_audit_level, counts, ids_digest, pg_catalog.now());
  INSERT INTO public.predictive_retention_authorizations (txid, retention_event_id) VALUES (pg_catalog.pg_current_xact_id(), event_id);
  DELETE FROM public.predictive_feature_run_unpins WHERE pin_id = ANY(pins);
  DELETE FROM public.predictive_feature_run_pins WHERE id = ANY(pins);
  DELETE FROM public.predictive_feature_run_dependencies WHERE feature_run_id = ANY(runs);
  DELETE FROM public.predictive_feature_runs WHERE id = ANY(runs);
  DELETE FROM public.predictive_outcome_labels WHERE id = ANY(labs);
  DELETE FROM public.predictive_decision_inputs WHERE decision_id = ANY(decs);
  DELETE FROM public.predictive_decisions WHERE id = ANY(decs);
  DELETE FROM public.predictive_artifact_observations WHERE observation_id = ANY(obs) OR artifact_id = ANY(arts);
  DELETE FROM public.predictive_observations WHERE id = ANY(obs);
  DELETE FROM public.predictive_source_stats_rows WHERE id = ANY(source_rows);
  DELETE FROM public.predictive_captures WHERE id = ANY(caps);
  DELETE FROM public.predictive_artifacts WHERE id = ANY(arts);
  DELETE FROM public.predictive_blobs WHERE sha256 = ANY(blobs);
  INSERT INTO public.predictive_blob_removals (storage_ref, queued_at) SELECT r, pg_catalog.now() FROM unnest(refs) r ON CONFLICT DO NOTHING;
  IF event_audit_level = 'full' THEN
    INSERT INTO public.predictive_retention_tombstones (retention_event_id, target_kind, target_id)
      SELECT event_id, r.k, r.v FROM unnest(removed_kinds, removed_ids) r(k, v);
  END IF;
  DELETE FROM public.predictive_retention_authorizations WHERE txid = pg_catalog.pg_current_xact_id();
  -- Blob references are returned to the caller for file removal, never stored
  -- for digest-only events.
  RETURN jsonb_build_object('eventId', event_id, 'removedCounts', counts, 'removedIdsDigest', ids_digest, 'removedBlobRefs', to_jsonb(refs));
END
$$;

-- Bound, canonical source revisions for internal research. They do not enter
-- predictive_observations or the feature/label head set until that complete
-- activation boundary is implemented. Released migrations remain unchanged.
CREATE FUNCTION public.predictive_source_canonical_json(value jsonb) RETURNS text
LANGUAGE sql IMMUTABLE STRICT AS $$
  SELECT CASE jsonb_typeof($1)
    WHEN 'object' THEN '{' || coalesce((SELECT string_agg(to_jsonb(key)::text || ':' || public.predictive_source_canonical_json(v), ',' ORDER BY key COLLATE "C") FROM jsonb_each($1) e(key,v)), '') || '}'
    WHEN 'array' THEN '[' || coalesce((SELECT string_agg(public.predictive_source_canonical_json(v), ',' ORDER BY n) FROM jsonb_array_elements($1) WITH ORDINALITY e(v,n)), '') || ']'
    ELSE $1::text END
$$;
CREATE FUNCTION public.predictive_source_digest(value jsonb) RETURNS text
LANGUAGE sql IMMUTABLE STRICT AS $$ SELECT encode(sha256(convert_to(public.predictive_source_canonical_json($1), 'UTF8')), 'hex') $$;
CREATE FUNCTION public.predictive_source_time(value timestamptz) RETURNS text
LANGUAGE sql IMMUTABLE STRICT AS $$ SELECT to_char($1 AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"') $$;
CREATE FUNCTION public.predictive_source_set_equal(a jsonb, b jsonb) RETURNS boolean
LANGUAGE sql IMMUTABLE STRICT AS $$ SELECT jsonb_typeof($1)='array' AND jsonb_typeof($2)='array'
  AND jsonb_array_length($1)=jsonb_array_length($2) AND $1 @> $2 AND $2 @> $1 $$;
CREATE FUNCTION public.predictive_source_exact(value jsonb, keys text[]) RETURNS boolean
LANGUAGE sql IMMUTABLE AS $$ SELECT CASE WHEN jsonb_typeof($1)='object' THEN coalesce(
  (SELECT array_agg(k ORDER BY k COLLATE "C") FROM jsonb_object_keys($1) k)=
    (SELECT array_agg(k ORDER BY k COLLATE "C") FROM unnest($2) k),false) ELSE false END $$;
CREATE FUNCTION public.predictive_source_request_key(req jsonb) RETURNS text
LANGUAGE plpgsql STABLE AS $$
DECLARE parts text[];
BEGIN
  IF public.predictive_source_exact(req,ARRAY['profileId','rawGameId','rawTeam','rawPlayerId','cutoff']) IS NOT TRUE
      OR public.predictive_text(req->'profileId') IS NOT TRUE OR (req->>'profileId') ~ '[|]'
      OR public.predictive_instant(req->>'cutoff') IS NOT TRUE
      OR jsonb_typeof(req->'rawGameId') IS DISTINCT FROM 'string' OR (req->>'rawGameId') !~ '^2026_[0-9]{2}_[A-Z]{2,3}_[A-Z]{2,3}$'
      OR jsonb_typeof(req->'rawTeam') IS DISTINCT FROM 'string'
      OR (req->'rawPlayerId' IS DISTINCT FROM 'null'::jsonb AND public.predictive_identity(req->'rawPlayerId','player') IS NOT TRUE) THEN
    RAISE EXCEPTION 'predictive-source-request-invalid' USING ERRCODE='23514'; END IF;
  parts:=string_to_array(req->>'rawGameId','_');
  IF parts[2]::integer NOT BETWEEN 1 AND 22 OR parts[3]=parts[4] OR (req->>'rawTeam') <> ALL(parts[3:4])
      OR NOT EXISTS (SELECT 1 FROM public.predictive_teams WHERE id='nfl:team:' || parts[3])
      OR NOT EXISTS (SELECT 1 FROM public.predictive_teams WHERE id='nfl:team:' || parts[4]) THEN
    RAISE EXCEPTION 'predictive-source-request-invalid' USING ERRCODE='23514'; END IF;
  RETURN public.predictive_source_digest(jsonb_build_array(req->>'rawGameId',req->>'rawTeam') ||
    CASE WHEN req->'rawPlayerId'='null'::jsonb THEN '[]'::jsonb ELSE jsonb_build_array(req->>'rawPlayerId') END);
END
$$;
CREATE FUNCTION public.predictive_source_is_head(id text, at_time timestamptz, rights_time timestamptz) RETURNS boolean
LANGUAGE sql STABLE AS $$ SELECT public.predictive_observation_usable($1,$2)
  AND EXISTS (SELECT 1 FROM public.predictive_observations o WHERE o.id=$1
    AND public.predictive_rights_allow(o.profile_id,$3,$3,'internal-research'))
  AND NOT EXISTS (SELECT 1 FROM public.predictive_observations n WHERE n.predecessor_id=$1 AND public.predictive_observation_usable(n.id,$2)) $$;
CREATE FUNCTION public.predictive_source_dependencies(ids text[], role_name text, at_time timestamptz) RETURNS jsonb
LANGUAGE sql STABLE AS $$ SELECT coalesce(jsonb_agg(jsonb_build_object('role',$2,'observationId',o.id,'profileId',o.profile_id,
  'sourceKey',o.source_key,'captureId',c.id,'artifactId',a.id,'artifactSha256',a.blob_sha256,
  'availableAt',public.predictive_source_time(c.available_at),'ingestedAt',public.predictive_source_time(c.ingested_at))), '[]'::jsonb)
  FROM public.predictive_observations o JOIN LATERAL (
    SELECT c.* FROM public.predictive_artifact_observations l JOIN public.predictive_captures c ON c.artifact_id=l.artifact_id
    JOIN public.predictive_ingestion_runs r ON r.id=c.run_id WHERE l.observation_id=o.id AND c.state='published' AND r.status='published'
      AND c.available_at <= $3 AND c.ingested_at <= $3
    ORDER BY c.ingested_at,c.available_at,c.captured_at,c.id COLLATE "C" LIMIT 1) c ON true
  JOIN public.predictive_artifacts a ON a.id=c.artifact_id WHERE o.id=ANY($1) $$;

CREATE TABLE public.predictive_source_stats_revisions (
  id text PRIMARY KEY CHECK (id ~ '^normalized-stats:[a-f0-9]{64}$'),
  kind text NOT NULL CHECK (kind IN ('player-game-stats','team-game-stats')),
  profile_id text NOT NULL REFERENCES public.predictive_source_profiles(id),
  source_record_id text NOT NULL CHECK (source_record_id ~ '^[a-f0-9]{64}$'),
  data jsonb NOT NULL CHECK (public.predictive_payload_valid(kind,data) IS TRUE),
  entity_key text NOT NULL CHECK (entity_key=public.predictive_entity_key(kind,data)),
  source_key text NOT NULL CHECK (source_key=entity_key || '|' || profile_id || '|' || source_record_id),
  predecessor_id text,
  correction_reason text CHECK (correction_reason='source-normalization-change'),
  UNIQUE (id,source_key), UNIQUE (id,profile_id,source_record_id),
  FOREIGN KEY (predecessor_id,source_key) REFERENCES public.predictive_source_stats_revisions(id,source_key) DEFERRABLE INITIALLY DEFERRED,
  CHECK ((predecessor_id IS NULL)=(correction_reason IS NULL)), CHECK (predecessor_id IS DISTINCT FROM id)
);
CREATE UNIQUE INDEX predictive_source_revisions_successor ON public.predictive_source_stats_revisions(predecessor_id) WHERE predecessor_id IS NOT NULL;
CREATE INDEX predictive_source_revisions_entity ON public.predictive_source_stats_revisions(entity_key,profile_id,source_record_id);
CREATE TABLE public.predictive_source_bindings (
  id text PRIMARY KEY CHECK (length(id) BETWEEN 1 AND 256 AND length(btrim(id))>0 AND id !~ '[[:cntrl:]|]'),
  profile_id text NOT NULL REFERENCES public.predictive_source_profiles(id),
  raw_key_sha256 text NOT NULL CHECK (raw_key_sha256 ~ '^[a-f0-9]{64}$'),
  predecessor_id text,
  recorded_at timestamptz NOT NULL CHECK (isfinite(recorded_at) AND recorded_at=date_trunc('milliseconds',recorded_at)),
  cutoff timestamptz NOT NULL CHECK (isfinite(cutoff) AND cutoff <= recorded_at),
  plan jsonb NOT NULL,
  revision_id text,
  UNIQUE (id,profile_id,raw_key_sha256),
  FOREIGN KEY (predecessor_id,profile_id,raw_key_sha256) REFERENCES public.predictive_source_bindings(id,profile_id,raw_key_sha256) DEFERRABLE INITIALLY DEFERRED,
  FOREIGN KEY (revision_id,profile_id,raw_key_sha256) REFERENCES public.predictive_source_stats_revisions(id,profile_id,source_record_id),
  CHECK (predecessor_id IS DISTINCT FROM id),
  CHECK ((revision_id IS NULL)=(plan->'candidate'='null'::jsonb))
);
CREATE UNIQUE INDEX predictive_source_bindings_root ON public.predictive_source_bindings(profile_id,raw_key_sha256) WHERE predecessor_id IS NULL;
CREATE UNIQUE INDEX predictive_source_bindings_successor ON public.predictive_source_bindings(predecessor_id) WHERE predecessor_id IS NOT NULL;
CREATE INDEX predictive_source_bindings_scope ON public.predictive_source_bindings(profile_id,raw_key_sha256,recorded_at);
CREATE TABLE public.predictive_source_binding_captures (
  binding_id text NOT NULL REFERENCES public.predictive_source_bindings(id),
  capture_id text NOT NULL REFERENCES public.predictive_captures(id), PRIMARY KEY (binding_id,capture_id)
);
CREATE TABLE public.predictive_source_binding_rows (
  binding_id text NOT NULL REFERENCES public.predictive_source_bindings(id),
  row_id text NOT NULL REFERENCES public.predictive_source_stats_rows(id), PRIMARY KEY (binding_id,row_id)
);
CREATE TABLE public.predictive_source_binding_dependencies (
  binding_id text NOT NULL REFERENCES public.predictive_source_bindings(id),
  observation_id text NOT NULL REFERENCES public.predictive_observations(id),
  role text NOT NULL CHECK (role IN ('game-bridge','team-alias','opponent-alias','player-bridge','schedule')),
  capture_id text NOT NULL REFERENCES public.predictive_captures(id),
  artifact_id text NOT NULL REFERENCES public.predictive_artifacts(id), PRIMARY KEY (binding_id,role,observation_id)
);
CREATE INDEX predictive_source_binding_dependencies_reverse ON public.predictive_source_binding_dependencies(observation_id,binding_id);
CREATE TABLE public.predictive_source_binding_links (
  binding_id text NOT NULL REFERENCES public.predictive_source_bindings(id),
  link_id text NOT NULL REFERENCES public.predictive_profile_identity_links(id), PRIMARY KEY (binding_id,link_id)
);
CREATE TABLE public.predictive_source_binding_decisions (
  binding_id text NOT NULL REFERENCES public.predictive_source_bindings(id),
  decision_id text NOT NULL REFERENCES public.predictive_decisions(id), PRIMARY KEY (binding_id,decision_id)
);
CREATE TABLE public.predictive_source_binding_rights (
  binding_id text NOT NULL REFERENCES public.predictive_source_bindings(id),
  rights_decision_id text NOT NULL REFERENCES public.predictive_rights_decisions(id), PRIMARY KEY (binding_id,rights_decision_id)
);

-- Independently recompute permitted raw rows, normalization identity and the
-- complete relevant head sets. A correctly rehashed forged plan still refuses.
CREATE FUNCTION public.predictive_source_plan_check(proposed jsonb, rights_time timestamptz, require_current boolean) RETURNS void
LANGUAGE plpgsql STABLE AS $$
DECLARE b jsonb := proposed->'binding'; req jsonb := b->'sourceRequest'; p public.predictive_source_profiles;
  t timestamptz; raw_key text; caps jsonb; cap jsonb; source_rows jsonb; row_refs jsonb; stats jsonb;
  expected_reason text; expected_candidate jsonb; deps jsonb := '[]'; links jsonb := '[]'; decisions jsonb := '[]'; rights_ids jsonb;
  ids text[]; current_ids text[]; role_name text; fact text; game text; team text; opponent text; player text; chosen text;
  schedule jsonb; parts text[]; decision_ids text[]; values_count integer; bad boolean; candidate_data jsonb; d public.predictive_decisions;
BEGIN
  IF public.predictive_source_exact(proposed,ARRAY['status','reason','candidate','dataDigest','binding','planDigest',
        'observationsPublished','featuresPublished','labelsFinalized','populationCoverage']) IS NOT TRUE
      OR public.predictive_source_exact(b,ARRAY['version','cutoff','sourceRequest','sourceInputDigest','sourceProfileId','rawSourceKey',
        'sourceCaptures','sourceRows','parserVersion','projectionVersion','dependencies','identityLinks','decisions','rightsDecisionIds']) IS NOT TRUE THEN
    RAISE EXCEPTION 'predictive-source-plan-invalid' USING ERRCODE='23514'; END IF;
  raw_key:=public.predictive_source_request_key(req);
  IF jsonb_typeof(b->'sourceCaptures') IS DISTINCT FROM 'array' OR jsonb_typeof(b->'sourceRows') IS DISTINCT FROM 'array'
      OR jsonb_typeof(b->'dependencies') IS DISTINCT FROM 'array' OR jsonb_typeof(b->'identityLinks') IS DISTINCT FROM 'array'
      OR jsonb_typeof(b->'decisions') IS DISTINCT FROM 'array' OR jsonb_typeof(b->'rightsDecisionIds') IS DISTINCT FROM 'array'
      OR b->>'cutoff' IS DISTINCT FROM req->>'cutoff' THEN
    RAISE EXCEPTION 'predictive-source-plan-invalid' USING ERRCODE='23514'; END IF;
  t:=(b->>'cutoff')::timestamptz;
  IF rights_time IS NULL OR NOT isfinite(rights_time) OR require_current IS NULL OR b->>'version' IS DISTINCT FROM 'nflverse-stats-normalization-plan-v1' OR b->>'parserVersion' IS DISTINCT FROM 'nflverse-csv-qualification-v1'
      OR b->>'projectionVersion' IS DISTINCT FROM 'nflverse-raw-stats-v1' OR public.predictive_instant(b->>'cutoff') IS NOT TRUE
      OR t > rights_time OR req->>'cutoff' IS DISTINCT FROM b->>'cutoff' OR req->>'profileId' IS DISTINCT FROM b->>'sourceProfileId'
      OR proposed->'observationsPublished' IS DISTINCT FROM 'false'::jsonb OR proposed->'featuresPublished' IS DISTINCT FROM 'false'::jsonb
      OR proposed->'labelsFinalized' IS DISTINCT FROM 'false'::jsonb OR proposed->>'populationCoverage' IS DISTINCT FROM 'unqualified'
      OR proposed->>'planDigest' IS DISTINCT FROM public.predictive_source_digest(jsonb_build_object('reason',proposed->'reason','candidate',proposed->'candidate','binding',b)) THEN
    RAISE EXCEPTION 'predictive-source-plan-invalid' USING ERRCODE='23514';
  END IF;
  SELECT * INTO p FROM public.predictive_source_profiles WHERE id=b->>'sourceProfileId';
  IF p.id IS NULL OR p.provider <> 'nflverse' OR p.parser_version <> 'nflverse-csv-qualification-v1' OR p.feed NOT IN ('player','team')
      OR public.predictive_rights_allow(p.id,rights_time,rights_time,'internal-research') IS NOT TRUE
      OR p.allowlist_version IS DISTINCT FROM 'predictive-raw-allowlist-v1'
      OR (p.feed='player') IS DISTINCT FROM (req->'rawPlayerId'<>'null'::jsonb) THEN
    RAISE EXCEPTION 'predictive-source-plan-rights-profile-invalid' USING ERRCODE='23514';
  END IF;
  WITH eligible AS (SELECT c.*,dense_rank() OVER (ORDER BY c.captured_at DESC) AS rank
    FROM public.predictive_captures c JOIN public.predictive_artifacts a ON a.id=c.artifact_id
    JOIN public.predictive_blobs bl ON bl.sha256=a.blob_sha256 JOIN public.predictive_ingestion_runs r ON r.id=c.run_id
    WHERE a.profile_id=p.id AND a.scope_kind='season-file' AND a.scope_season=2026 AND a.scope_filter IS NULL AND bl.media_type='text/csv'
      AND c.state='published' AND r.status='published' AND c.available_at <= t AND c.ingested_at <= t)
  SELECT jsonb_agg(jsonb_build_object('id',c.id,'runId',c.run_id,'artifactId',c.artifact_id,'capturedAt',public.predictive_source_time(c.captured_at),
    'availableAt',public.predictive_source_time(c.available_at),'ingestedAt',public.predictive_source_time(c.ingested_at),
    'parsedRows',c.parsed_rows,'sha256',a.blob_sha256,'storageRef',bl.storage_ref,'byteSize',bl.byte_size) ORDER BY c.ingested_at,c.id COLLATE "C")
    INTO caps FROM eligible c JOIN public.predictive_artifacts a ON a.id=c.artifact_id JOIN public.predictive_blobs bl ON bl.sha256=a.blob_sha256 WHERE c.rank=1;
  -- Uncaptured/ambiguous raw evidence and unresolved bridges are not recordable
  -- in this increment. Their read-only plans remain explicitly unavailable.
  IF caps IS NULL OR jsonb_array_length(caps)>256 OR (SELECT count(DISTINCT x->>'sha256') FROM jsonb_array_elements(caps) x) <> 1 THEN
    RAISE EXCEPTION 'predictive-source-plan-not-recordable' USING ERRCODE='23514';
  END IF;
  cap := caps->0;
  IF require_current AND EXISTS (SELECT 1 FROM public.predictive_captures c JOIN public.predictive_artifacts a ON a.id=c.artifact_id
      JOIN public.predictive_ingestion_runs r ON r.id=c.run_id JOIN public.predictive_blobs bl ON bl.sha256=a.blob_sha256
      WHERE a.profile_id=p.id AND a.scope_kind='season-file' AND a.scope_season=2026 AND a.scope_filter IS NULL
        AND c.state='published' AND r.status='published' AND bl.media_type='text/csv' AND c.available_at <= rights_time AND c.ingested_at <= rights_time
        AND (c.captured_at > (cap->>'capturedAt')::timestamptz OR (c.captured_at=(cap->>'capturedAt')::timestamptz AND a.blob_sha256 IS DISTINCT FROM (cap->>'sha256')))) THEN
    RAISE EXCEPTION 'predictive-source-plan-stale' USING ERRCODE='23514';
  END IF;
  SELECT coalesce(jsonb_agg(jsonb_build_object('id',s.id,'rowOrdinal',s.row_ordinal,'rawKeySha256',s.raw_key_sha256,
      'selectedSha256',s.selected_sha256,'projection',s.projection,'failureCode',s.failure_code) ORDER BY s.row_ordinal),'[]'::jsonb),
    coalesce(jsonb_agg(jsonb_build_object('id',s.id,'rowOrdinal',s.row_ordinal,'selectedSha256',s.selected_sha256) ORDER BY s.row_ordinal),'[]'::jsonb)
    INTO source_rows,row_refs FROM public.predictive_source_stats_rows s WHERE s.capture_id=cap->>'id' AND s.raw_key_sha256=raw_key;
  caps := jsonb_build_array(cap);
  IF b->'sourceCaptures' IS DISTINCT FROM caps OR b->'sourceRows' IS DISTINCT FROM row_refs
      OR b->'rawSourceKey' IS DISTINCT FROM (CASE WHEN jsonb_array_length(source_rows)=0 THEN 'null'::jsonb ELSE to_jsonb(raw_key) END)
      OR b->>'sourceInputDigest' IS DISTINCT FROM public.predictive_source_digest(jsonb_build_object('version','nflverse-csv-source-claims-v1',
        'request',req,'captures',caps,'rows',source_rows)) THEN
    RAISE EXCEPTION 'predictive-source-plan-rows-invalid' USING ERRCODE='23514';
  END IF;
  IF jsonb_array_length(source_rows)=0 THEN expected_reason := 'source-row-missing';
  ELSIF (SELECT count(DISTINCT x->>'selectedSha256') FROM jsonb_array_elements(source_rows) x)>1 THEN expected_reason := 'source-row-ambiguous';
  ELSIF source_rows->0->>'failureCode' IS NOT NULL THEN expected_reason := 'source-row-refused'; END IF;
  IF expected_reason IS NOT NULL THEN
    IF proposed->>'reason' IS DISTINCT FROM expected_reason OR proposed->'candidate' IS DISTINCT FROM 'null'::jsonb OR proposed->'dataDigest' IS DISTINCT FROM 'null'::jsonb
        OR proposed->>'status' IS DISTINCT FROM 'unavailable-source-normalization' OR b->'dependencies' IS DISTINCT FROM '[]'::jsonb OR b->'decisions' IS DISTINCT FROM '[]'::jsonb
        OR b->'identityLinks' IS DISTINCT FROM '[]'::jsonb OR b->'rightsDecisionIds' IS DISTINCT FROM '[]'::jsonb THEN
      RAISE EXCEPTION 'predictive-source-plan-unavailable-invalid' USING ERRCODE='23514';
    END IF;
    RETURN;
  END IF;
  stats := source_rows->0->'projection';
  FOREACH role_name IN ARRAY ARRAY['game-bridge','team-alias','opponent-alias'] LOOP
    fact := CASE role_name WHEN 'game-bridge' THEN 'game-bridge:nflverse:' || (stats->>'rawGameId')
      WHEN 'team-alias' THEN 'team-alias:nflverse:' || (stats->>'rawTeam') ELSE 'team-alias:nflverse:' || (stats->>'rawOpponent') END;
    SELECT coalesce(array_agg(o.id ORDER BY o.id COLLATE "C"),'{}') INTO ids FROM public.predictive_observations o
      WHERE o.entity_key=fact AND public.predictive_source_is_head(o.id,t,rights_time);
    IF require_current THEN
      SELECT coalesce(array_agg(o.id ORDER BY o.id COLLATE "C"),'{}') INTO current_ids FROM public.predictive_observations o
        WHERE o.entity_key=fact AND public.predictive_source_is_head(o.id,rights_time,rights_time);
      IF ids<>current_ids THEN RAISE EXCEPTION 'predictive-source-plan-stale' USING ERRCODE='23514'; END IF;
    END IF;
    SELECT count(DISTINCT CASE role_name WHEN 'game-bridge' THEN o.data->>'gameId' ELSE o.data->>'teamId' END),
      coalesce(bool_or(o.kind='source-row-absent'),false), min(CASE role_name WHEN 'game-bridge' THEN o.data->>'gameId' ELSE o.data->>'teamId' END)
      FILTER (WHERE role_name='game-bridge' OR ((o.data->>'effectiveFromSeason')::integer <= (stats->>'season')::integer
        AND (o.data->>'effectiveToSeason')::integer >= (stats->>'season')::integer)) INTO values_count,bad,chosen
      FROM public.predictive_observations o WHERE o.id=ANY(ids) AND (role_name='game-bridge' OR o.kind='source-row-absent'
        OR ((o.data->>'effectiveFromSeason')::integer <= (stats->>'season')::integer AND (o.data->>'effectiveToSeason')::integer >= (stats->>'season')::integer));
    IF values_count<>1 OR bad OR chosen IS NULL THEN RAISE EXCEPTION 'predictive-source-plan-bridge-invalid' USING ERRCODE='23514'; END IF;
    IF role_name='game-bridge' THEN game:=chosen; ELSIF role_name='team-alias' THEN team:=chosen; ELSE opponent:=chosen; END IF;
    deps := deps || public.predictive_source_dependencies(ids,role_name,t);
  END LOOP;
  IF EXISTS (SELECT 1 FROM public.predictive_observations o WHERE o.kind='game-bridge' AND o.game_id=game::uuid
      AND o.data->>'provider'='nflverse' AND (o.data->>'rawGameId') IS DISTINCT FROM (stats->>'rawGameId')
      AND (public.predictive_source_is_head(o.id,t,rights_time) OR (require_current AND public.predictive_source_is_head(o.id,rights_time,rights_time)))) THEN
    RAISE EXCEPTION 'predictive-source-plan-bridge-invalid' USING ERRCODE='23514';
  END IF;
  SELECT coalesce(array_agg(o.id ORDER BY o.id COLLATE "C"),'{}') INTO ids FROM public.predictive_observations o
    WHERE o.entity_key='schedule:' || game AND public.predictive_source_is_head(o.id,t,rights_time);
  IF require_current THEN
    SELECT coalesce(array_agg(o.id ORDER BY o.id COLLATE "C"),'{}') INTO current_ids FROM public.predictive_observations o
      WHERE o.entity_key='schedule:' || game AND public.predictive_source_is_head(o.id,rights_time,rights_time);
    IF ids<>current_ids THEN RAISE EXCEPTION 'predictive-source-plan-stale' USING ERRCODE='23514'; END IF;
  END IF;
  IF cardinality(ids)=1 THEN chosen:=ids[1];
  ELSIF cardinality(ids)>1 THEN
    SELECT array_agg(x.id) INTO decision_ids FROM public.predictive_decisions x WHERE x.entity_key='reconciliation:schedule:' || game AND x.kind='reconciliation'
      AND x.decided_at <= t AND NOT EXISTS (SELECT 1 FROM public.predictive_decisions n WHERE n.predecessor_id=x.id AND n.decided_at<=t)
      AND (SELECT r.status FROM public.predictive_ingestion_runs r WHERE r.id=x.run_id)='published';
    IF cardinality(decision_ids) IS DISTINCT FROM 1 THEN RAISE EXCEPTION 'predictive-source-plan-schedule-invalid' USING ERRCODE='23514'; END IF;
    SELECT * INTO d FROM public.predictive_decisions WHERE id=decision_ids[1];
    IF d.outcome->>'result' IS DISTINCT FROM 'selected' OR public.predictive_decision_current(d.id,t) IS NOT TRUE
        OR (require_current AND (SELECT array_agg(x.id ORDER BY x.id COLLATE "C") FROM public.predictive_decisions x
        JOIN public.predictive_ingestion_runs r ON r.id=x.run_id WHERE x.entity_key=d.entity_key AND x.kind='reconciliation' AND r.status='published'
          AND x.decided_at<=rights_time AND NOT EXISTS (SELECT 1 FROM public.predictive_decisions n WHERE n.predecessor_id=x.id AND n.decided_at<=rights_time)) IS DISTINCT FROM decision_ids) THEN
      RAISE EXCEPTION 'predictive-source-plan-schedule-invalid' USING ERRCODE='23514'; END IF;
    chosen:=d.outcome->>'selectedObservationId';
    decisions:=jsonb_build_array(jsonb_build_object('id',d.id,'kind',d.kind,'entityKey',d.entity_key,'policyId',d.policy_id,'mode',d.mode,
      'decidedAt',public.predictive_source_time(d.decided_at),'predecessorId',d.predecessor_id,'outcome',d.outcome,'inputs',
      (SELECT jsonb_agg(jsonb_build_object('observationId',i.observation_id,'role',i.role) ORDER BY i.observation_id COLLATE "C") FROM public.predictive_decision_inputs i WHERE i.decision_id=d.id)));
  ELSE RAISE EXCEPTION 'predictive-source-plan-schedule-invalid' USING ERRCODE='23514'; END IF;
  SELECT data INTO schedule FROM public.predictive_observations WHERE id=chosen AND kind='schedule' AND id=ANY(ids);
  IF schedule IS NULL OR EXISTS (SELECT 1 FROM public.predictive_observations s JOIN public.predictive_observations a ON a.kind='schedule'
      AND a.raw_game_id=s.raw_game_id AND a.game_id<>s.game_id WHERE s.id=ANY(ids)
        AND (public.predictive_source_is_head(a.id,t,rights_time) OR (require_current AND public.predictive_source_is_head(a.id,rights_time,rights_time)))) THEN
    RAISE EXCEPTION 'predictive-source-plan-schedule-invalid' USING ERRCODE='23514'; END IF;
  deps:=deps || public.predictive_source_dependencies(ids,'schedule',t);
  parts:=string_to_array(stats->>'rawGameId','_');
  IF schedule->'season' IS DISTINCT FROM stats->'season' OR schedule->'week' IS DISTINCT FROM stats->'week' OR schedule->'seasonType' IS DISTINCT FROM stats->'seasonType' OR team=opponent
      OR (schedule->>'homeTeamId') IS DISTINCT FROM (CASE WHEN (stats->>'rawTeam')=parts[4] THEN team ELSE opponent END)
      OR (schedule->>'awayTeamId') IS DISTINCT FROM (CASE WHEN (stats->>'rawTeam')=parts[3] THEN team ELSE opponent END) THEN
    RAISE EXCEPTION 'predictive-source-plan-context-invalid' USING ERRCODE='23514'; END IF;
  candidate_data:=jsonb_build_object('gameId',game,'rawGameId',stats->'rawGameId','teamId',team,'rawTeam',stats->'rawTeam',
    'season',stats->'season','seasonType',stats->'seasonType','missing',stats->'missing') || (stats->'values');
  IF p.feed='player' THEN
    SELECT coalesce(array_agg(o.id ORDER BY o.id COLLATE "C"),'{}') INTO ids FROM public.predictive_observations o
      WHERE o.entity_key='player-bridge:gsis:' || (stats->>'rawPlayerId') AND public.predictive_source_is_head(o.id,t,rights_time);
    IF require_current THEN
      SELECT coalesce(array_agg(o.id ORDER BY o.id COLLATE "C"),'{}') INTO current_ids FROM public.predictive_observations o
        WHERE o.entity_key='player-bridge:gsis:' || (stats->>'rawPlayerId') AND public.predictive_source_is_head(o.id,rights_time,rights_time);
      IF ids<>current_ids THEN RAISE EXCEPTION 'predictive-source-plan-stale' USING ERRCODE='23514'; END IF;
    END IF;
    IF EXISTS (SELECT 1 FROM public.predictive_observations o WHERE o.id=ANY(ids) AND o.kind='source-row-absent') THEN
      RAISE EXCEPTION 'predictive-source-plan-player-invalid' USING ERRCODE='23514'; END IF;
    SELECT count(DISTINCT o.player_id),min(o.player_id) INTO values_count,player FROM public.predictive_observations o WHERE o.id=ANY(ids)
      AND (o.data->>'effectiveFrom')::timestamptz <= (schedule->>'kickoff')::timestamptz AND (schedule->>'kickoff')::timestamptz < (o.data->>'effectiveTo')::timestamptz;
    IF values_count<>1 OR EXISTS (SELECT 1 FROM public.predictive_observations o WHERE o.kind='player-bridge' AND o.player_id=player
        AND o.data->>'provider'='gsis' AND (o.data->>'rawPlayerId') IS DISTINCT FROM (stats->>'rawPlayerId')
        AND (o.data->>'effectiveFrom')::timestamptz <= (schedule->>'kickoff')::timestamptz AND (schedule->>'kickoff')::timestamptz < (o.data->>'effectiveTo')::timestamptz
        AND (public.predictive_source_is_head(o.id,t,rights_time) OR (require_current AND public.predictive_source_is_head(o.id,rights_time,rights_time)))) THEN
      RAISE EXCEPTION 'predictive-source-plan-player-invalid' USING ERRCODE='23514'; END IF;
    SELECT coalesce(jsonb_agg(jsonb_build_object('id',k.id,'statsProfileId',k.stats_profile_id,'bridgeProfileId',k.bridge_profile_id,
      'provider',k.provider,'decidedAt',public.predictive_source_time(k.decided_at))),'[]'::jsonb) INTO links FROM public.predictive_profile_identity_links k
      WHERE k.stats_profile_id=p.id AND k.provider='gsis' AND k.decided_at<=t AND EXISTS (SELECT 1 FROM public.predictive_observations o WHERE o.id=ANY(ids)
        AND o.profile_id=k.bridge_profile_id AND o.player_id=player AND (o.data->>'effectiveFrom')::timestamptz <= (schedule->>'kickoff')::timestamptz
        AND (schedule->>'kickoff')::timestamptz < (o.data->>'effectiveTo')::timestamptz);
    IF require_current AND EXISTS (SELECT 1 FROM public.predictive_profile_identity_links k
        WHERE k.stats_profile_id=p.id AND k.provider='gsis' AND k.decided_at>t AND k.decided_at<=rights_time
          AND EXISTS (SELECT 1 FROM public.predictive_observations o WHERE o.id=ANY(ids) AND o.profile_id=k.bridge_profile_id
            AND o.player_id=player AND (o.data->>'effectiveFrom')::timestamptz <= (schedule->>'kickoff')::timestamptz
            AND (schedule->>'kickoff')::timestamptz < (o.data->>'effectiveTo')::timestamptz)) THEN
      RAISE EXCEPTION 'predictive-source-plan-stale' USING ERRCODE='23514'; END IF;
    IF links='[]'::jsonb THEN RAISE EXCEPTION 'predictive-source-plan-player-invalid' USING ERRCODE='23514'; END IF;
    deps:=deps || public.predictive_source_dependencies(ids,'player-bridge',t);
    candidate_data:=candidate_data || jsonb_build_object('playerId',player,'rawPlayerId',stats->'rawPlayerId','playerIdProvider','gsis');
  END IF;
  SELECT jsonb_agg(to_jsonb(public.predictive_rights_in_force(id,rights_time,rights_time))) INTO rights_ids FROM (
    SELECT p.id UNION SELECT x->>'profileId' FROM jsonb_array_elements(deps) x) profiles(id);
  expected_candidate:=jsonb_build_object('kind',CASE p.feed WHEN 'player' THEN 'player-game-stats' ELSE 'team-game-stats' END,'data',candidate_data);
  IF proposed->>'status' IS DISTINCT FROM 'planned-source-normalization' OR proposed->'reason' IS DISTINCT FROM 'null'::jsonb
      OR proposed->'candidate' IS DISTINCT FROM expected_candidate OR proposed->>'dataDigest' IS DISTINCT FROM public.predictive_source_digest(expected_candidate)
      OR public.predictive_source_set_equal(b->'dependencies',deps) IS NOT TRUE OR public.predictive_source_set_equal(b->'identityLinks',links) IS NOT TRUE
      OR public.predictive_source_set_equal(b->'decisions',decisions) IS NOT TRUE OR public.predictive_source_set_equal(b->'rightsDecisionIds',rights_ids) IS NOT TRUE THEN
    RAISE EXCEPTION 'predictive-source-plan-normalization-invalid' USING ERRCODE='23514'; END IF;
END
$$;

CREATE FUNCTION public.predictive_record_source_binding(binding_id text, expected_head text, proposed jsonb) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE p text:=proposed->'binding'->>'sourceProfileId'; raw_key text; t timestamptz; old public.predictive_source_bindings;
  head public.predictive_source_bindings; prior public.predictive_source_stats_revisions; revision text; kind text; data jsonb; fact text;
BEGIN
  IF NOT pg_catalog.pg_has_role(session_user,'predictive_recorder','MEMBER') THEN
    RAISE EXCEPTION 'predictive-source-recorder-not-authorized' USING ERRCODE='42501'; END IF;
  IF pg_catalog.current_setting('transaction_isolation') <> 'read committed' THEN
    RAISE EXCEPTION 'predictive-source-recorder-isolation-refused' USING ERRCODE='25001'; END IF;
  PERFORM pg_catalog.pg_advisory_xact_lock(520052,1);
  -- Freeze the publication evidence while independently checking the proposed
  -- witness. Cooperating writers already use the global lock; SHARE also covers
  -- direct SQL appenders. No filesystem write or digest lock is needed here.
  LOCK TABLE public.predictive_source_profiles,public.predictive_rights_decisions,public.predictive_ingestion_runs,
    public.predictive_artifacts,public.predictive_blobs,public.predictive_captures,public.predictive_source_stats_rows,
    public.predictive_observations,public.predictive_artifact_observations,public.predictive_profile_identity_links,
    public.predictive_decisions,public.predictive_decision_inputs IN SHARE MODE;
  t:=date_trunc('milliseconds',pg_catalog.clock_timestamp());
  IF EXISTS (SELECT 1 FROM public.predictive_source_profiles sp WHERE sp.purpose='synthetic-test' AND
      (sp.id=p OR sp.id IN (SELECT x->>'profileId' FROM jsonb_array_elements(proposed->'binding'->'dependencies') x)))
      AND NOT public.predictive_harness_session() THEN RAISE EXCEPTION 'predictive-synthetic-outside-harness' USING ERRCODE='23514'; END IF;
  raw_key:=public.predictive_source_request_key(proposed->'binding'->'sourceRequest');
  SELECT * INTO old FROM public.predictive_source_bindings WHERE id=binding_id;
  IF old.id IS NOT NULL THEN
    IF old.plan IS DISTINCT FROM proposed OR old.predecessor_id IS DISTINCT FROM expected_head THEN RAISE EXCEPTION 'predictive-source-binding-id-conflict' USING ERRCODE='23514'; END IF;
    IF EXISTS (SELECT 1 FROM (SELECT old.profile_id AS id UNION SELECT x->>'profileId' FROM jsonb_array_elements(old.plan->'binding'->'dependencies') x) profiles
        WHERE public.predictive_rights_allow(profiles.id,t,t,'internal-research') IS NOT TRUE) THEN
      RAISE EXCEPTION 'predictive-source-plan-rights-profile-invalid' USING ERRCODE='23514'; END IF;
    RETURN jsonb_build_object('id',old.id,'recordedAt',public.predictive_source_time(old.recorded_at),'reused',true);
  END IF;
  PERFORM public.predictive_source_plan_check(proposed,t,true);
  SELECT * INTO head FROM public.predictive_source_bindings b WHERE b.profile_id=p AND b.raw_key_sha256=raw_key
    AND NOT EXISTS (SELECT 1 FROM public.predictive_source_bindings n WHERE n.predecessor_id=b.id);
  IF head.id IS DISTINCT FROM expected_head OR (head.id IS NOT NULL AND (head.recorded_at>t OR head.cutoff>(proposed->'binding'->>'cutoff')::timestamptz)) THEN
    RAISE EXCEPTION 'predictive-source-binding-head-conflict' USING ERRCODE='23514'; END IF;
  IF proposed->'candidate'<>'null'::jsonb THEN
    kind:=proposed->'candidate'->>'kind'; data:=proposed->'candidate'->'data'; fact:=public.predictive_entity_key(kind,data);
    SELECT r.* INTO prior FROM public.predictive_source_stats_revisions r WHERE r.profile_id=p AND r.source_record_id=raw_key AND r.entity_key=fact
      AND NOT EXISTS (SELECT 1 FROM public.predictive_source_stats_revisions n WHERE n.predecessor_id=r.id);
    IF prior.id IS NOT NULL AND prior.data=data AND prior.kind=kind THEN revision:=prior.id;
    ELSE
      revision:='normalized-stats:' || encode(sha256(convert_to(binding_id,'UTF8')),'hex');
      INSERT INTO public.predictive_source_stats_revisions(id,kind,profile_id,source_record_id,data,entity_key,source_key,predecessor_id,correction_reason)
        VALUES(revision,kind,p,raw_key,data,fact,fact || '|' || p || '|' || raw_key,prior.id,CASE WHEN prior.id IS NOT NULL THEN 'source-normalization-change' END);
    END IF;
  END IF;
  INSERT INTO public.predictive_source_bindings(id,profile_id,raw_key_sha256,predecessor_id,recorded_at,cutoff,plan,revision_id)
    VALUES(binding_id,p,raw_key,head.id,t,(proposed->'binding'->>'cutoff')::timestamptz,proposed,revision);
  INSERT INTO public.predictive_source_binding_captures SELECT binding_id,x->>'id' FROM jsonb_array_elements(proposed->'binding'->'sourceCaptures') x;
  INSERT INTO public.predictive_source_binding_rows SELECT binding_id,x->>'id' FROM jsonb_array_elements(proposed->'binding'->'sourceRows') x;
  INSERT INTO public.predictive_source_binding_dependencies SELECT binding_id,x->>'observationId',x->>'role',x->>'captureId',x->>'artifactId'
    FROM jsonb_array_elements(proposed->'binding'->'dependencies') x;
  INSERT INTO public.predictive_source_binding_links SELECT binding_id,x->>'id' FROM jsonb_array_elements(proposed->'binding'->'identityLinks') x;
  INSERT INTO public.predictive_source_binding_decisions SELECT binding_id,x->>'id' FROM jsonb_array_elements(proposed->'binding'->'decisions') x;
  INSERT INTO public.predictive_source_binding_rights SELECT binding_id,jsonb_array_elements_text(proposed->'binding'->'rightsDecisionIds');
  RETURN jsonb_build_object('id',binding_id,'recordedAt',public.predictive_source_time(t),'reused',false);
END
$$;

DO $immutable$
DECLARE rel text;
BEGIN
  FOREACH rel IN ARRAY ARRAY['predictive_source_stats_revisions','predictive_source_bindings','predictive_source_binding_captures',
    'predictive_source_binding_rows','predictive_source_binding_dependencies','predictive_source_binding_links','predictive_source_binding_decisions','predictive_source_binding_rights'] LOOP
    EXECUTE format('CREATE TRIGGER %I BEFORE UPDATE OR DELETE ON public.%I FOR EACH ROW EXECUTE FUNCTION public.predictive_append_only()',rel || '_immutable',rel);
    EXECUTE format('CREATE TRIGGER %I BEFORE TRUNCATE ON public.%I FOR EACH STATEMENT EXECUTE FUNCTION public.predictive_append_only()',rel || '_no_truncate',rel);
    EXECUTE format('REVOKE ALL ON public.%I FROM PUBLIC',rel);
    IF EXISTS (SELECT 1 FROM pg_catalog.pg_roles WHERE rolname='predictive_replay') THEN EXECUTE format('GRANT SELECT ON public.%I TO predictive_replay',rel); END IF;
  END LOOP;
END
$immutable$;
REVOKE ALL ON FUNCTION public.predictive_source_canonical_json(jsonb),public.predictive_source_digest(jsonb),public.predictive_source_time(timestamptz),
  public.predictive_source_set_equal(jsonb,jsonb),public.predictive_source_exact(jsonb,text[]),public.predictive_source_request_key(jsonb),public.predictive_source_is_head(text,timestamptz,timestamptz),public.predictive_source_dependencies(text[],text,timestamptz),
  public.predictive_source_plan_check(jsonb,timestamptz,boolean),public.predictive_record_source_binding(text,text,jsonb) FROM PUBLIC;
DO $grants$
BEGIN
  IF EXISTS (SELECT 1 FROM pg_catalog.pg_roles WHERE rolname='predictive_recorder') THEN
    GRANT EXECUTE ON FUNCTION public.predictive_record_source_binding(text,text,jsonb) TO predictive_recorder;
  END IF;
END
$grants$;

-- Retention deletes a complete affected raw chain, including its older bindings.
-- A missing tail must never reactivate an earlier canonical contribution.
ALTER TABLE public.predictive_retention_tombstones DROP CONSTRAINT predictive_retention_tombstones_target_kind_check;
ALTER TABLE public.predictive_retention_tombstones ADD CONSTRAINT predictive_retention_tombstones_target_kind_check
  CHECK (target_kind IN ('observation','artifact','capture','decision','label','feature-run','pin','blob','source-stats-row','source-binding','source-stats-revision'));
CREATE OR REPLACE FUNCTION public.predictive_retention_execute(event_id text, event_reason text, event_authority text, event_decided_at timestamptz,
  event_scope jsonb, event_audit_level text) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $$
DECLARE
  profiles text[]; captured_from timestamptz; captured_before timestamptz; as_of timestamptz;
  arts text[] := '{}'; caps text[] := '{}'; obs text[] := '{}'; decs text[] := '{}'; labs text[] := '{}';
  runs text[] := '{}'; pins text[] := '{}'; blobs text[] := '{}'; refs text[]; source_rows text[] := '{}'; bindings text[] := '{}'; revisions text[] := '{}'; binding_links integer;
  removed_kinds text[]; removed_ids text[]; counts jsonb; ids_digest text; links integer; inputs integer; dependencies integer; unpins integer;
BEGIN
  IF NOT pg_catalog.pg_has_role(session_user, 'predictive_retention_owner', 'MEMBER') THEN
    RAISE EXCEPTION 'predictive-retention-not-authorized' USING ERRCODE = '42501';
  END IF;
  IF event_decided_at IS NULL OR event_decided_at > pg_catalog.now() OR NOT public.predictive_retention_scope_valid(event_reason, event_scope) THEN
    RAISE EXCEPTION 'predictive-retention-invalid' USING ERRCODE = '23514';
  END IF;
  PERFORM pg_catalog.pg_advisory_xact_lock(520052,1);
  LOCK TABLE public.predictive_source_bindings,public.predictive_source_stats_revisions IN SHARE ROW EXCLUSIVE MODE;
  IF event_scope->>'kind' = 'source' THEN
    profiles := ARRAY(SELECT jsonb_array_elements_text(event_scope->'profileIds'));
    IF EXISTS (SELECT 1 FROM unnest(profiles) p WHERE NOT EXISTS (SELECT 1 FROM public.predictive_source_profiles sp WHERE sp.id = p)) THEN
      RAISE EXCEPTION 'predictive-retention-invalid' USING ERRCODE = '23514';
    END IF;
    captured_from := (event_scope->>'capturedFrom')::timestamptz; captured_before := (event_scope->>'capturedBefore')::timestamptz;
    -- An artifact with any capture in range is removed whole, bytes and captures.
    arts := ARRAY(SELECT DISTINCT a.id FROM public.predictive_artifacts a JOIN public.predictive_captures c ON c.artifact_id = a.id
      WHERE a.profile_id = ANY(profiles) AND (captured_from IS NULL OR c.captured_at >= captured_from)
        AND (captured_before IS NULL OR c.captured_at < captured_before));
    caps := ARRAY(SELECT c.id FROM public.predictive_captures c WHERE c.artifact_id = ANY(arts));
    obs := ARRAY(WITH RECURSIVE chain AS (
        SELECT o.id FROM public.predictive_observations o JOIN public.predictive_artifact_observations l ON l.observation_id = o.id
        WHERE l.artifact_id = ANY(arts) AND o.profile_id = ANY(profiles)
        UNION SELECT n.id FROM public.predictive_observations n JOIN chain ON n.predecessor_id = chain.id)
      SELECT id FROM chain);
    decs := ARRAY(WITH RECURSIVE chain AS (
        SELECT DISTINCT i.decision_id AS id FROM public.predictive_decision_inputs i WHERE i.observation_id = ANY(obs)
        UNION SELECT n.id FROM public.predictive_decisions n JOIN chain ON n.predecessor_id = chain.id)
      SELECT id FROM chain);
    labs := ARRAY(WITH RECURSIVE chain AS (
        SELECT l.id FROM public.predictive_outcome_labels l WHERE l.completion_decision_id = ANY(decs) OR l.participation_decision_id = ANY(decs)
          OR l.reconciliation_decision_id = ANY(decs) OR l.selected_observation_id = ANY(obs) OR l.post_window_capture_id = ANY(caps)
          OR l.player_bridge_observation_id = ANY(obs)
        UNION SELECT n.id FROM public.predictive_outcome_labels n JOIN chain ON n.predecessor_id = chain.id)
      SELECT id FROM chain);
    runs := ARRAY(SELECT DISTINCT d.feature_run_id FROM public.predictive_feature_run_dependencies d
      WHERE d.observation_id = ANY(obs) OR d.decision_id = ANY(decs));
  ELSE
    as_of := (event_scope->>'asOf')::timestamptz;
    IF as_of > pg_catalog.now() THEN RAISE EXCEPTION 'predictive-retention-invalid' USING ERRCODE = '23514'; END IF;
    runs := ARRAY(SELECT f.id FROM public.predictive_feature_runs f WHERE public.predictive_feature_run_expired(f.id, as_of));
  END IF;
  source_rows := ARRAY(SELECT s.id FROM public.predictive_source_stats_rows s WHERE s.capture_id = ANY(caps));
  bindings := ARRAY(WITH affected AS (
      SELECT b.profile_id,b.raw_key_sha256 FROM public.predictive_source_bindings b WHERE
        EXISTS (SELECT 1 FROM public.predictive_source_binding_captures x WHERE x.binding_id=b.id AND x.capture_id=ANY(caps))
        OR EXISTS (SELECT 1 FROM public.predictive_source_binding_rows x WHERE x.binding_id=b.id AND x.row_id=ANY(source_rows))
        OR EXISTS (SELECT 1 FROM public.predictive_source_binding_dependencies x WHERE x.binding_id=b.id
          AND (x.observation_id=ANY(obs) OR x.capture_id=ANY(caps) OR x.artifact_id=ANY(arts)))
        OR EXISTS (SELECT 1 FROM public.predictive_source_binding_decisions x WHERE x.binding_id=b.id AND x.decision_id=ANY(decs)))
    SELECT DISTINCT b.id FROM public.predictive_source_bindings b JOIN affected a USING(profile_id,raw_key_sha256));
  revisions := ARRAY(SELECT r.id FROM public.predictive_source_stats_revisions r WHERE EXISTS (
    SELECT 1 FROM public.predictive_source_bindings b WHERE b.id=ANY(bindings) AND b.profile_id=r.profile_id AND b.raw_key_sha256=r.source_record_id));
  pins := ARRAY(SELECT p.id FROM public.predictive_feature_run_pins p WHERE p.feature_run_id = ANY(runs));
  blobs := ARRAY(SELECT DISTINCT b.sha256 FROM public.predictive_blobs b
    WHERE (b.sha256 IN (SELECT a.blob_sha256 FROM public.predictive_artifacts a WHERE a.id = ANY(arts))
        OR b.sha256 IN (SELECT f.bundle_blob_sha256 FROM public.predictive_feature_runs f WHERE f.id = ANY(runs)))
      AND NOT EXISTS (SELECT 1 FROM public.predictive_artifacts a WHERE a.blob_sha256 = b.sha256 AND NOT a.id = ANY(arts))
      AND NOT EXISTS (SELECT 1 FROM public.predictive_feature_runs f WHERE f.bundle_blob_sha256 = b.sha256 AND NOT f.id = ANY(runs)));
  refs := ARRAY(SELECT b.storage_ref FROM public.predictive_blobs b WHERE b.sha256 = ANY(blobs) ORDER BY b.storage_ref COLLATE "C");

  -- Parallel arrays, never a temp table: a caller could pre-create a pg_temp
  -- relation that this definer function would then use.
  SELECT coalesce(array_agg(k ORDER BY k COLLATE "C", v COLLATE "C"), '{}'), coalesce(array_agg(v ORDER BY k COLLATE "C", v COLLATE "C"), '{}')
    INTO removed_kinds, removed_ids FROM (
      SELECT 'observation', v FROM unnest(obs) v UNION ALL SELECT 'artifact', v FROM unnest(arts) v
      UNION ALL SELECT 'capture', v FROM unnest(caps) v UNION ALL SELECT 'decision', v FROM unnest(decs) v
      UNION ALL SELECT 'label', v FROM unnest(labs) v UNION ALL SELECT 'feature-run', v FROM unnest(runs) v
      UNION ALL SELECT 'pin', v FROM unnest(pins) v UNION ALL SELECT 'blob', v FROM unnest(blobs) v
      UNION ALL SELECT 'source-stats-row', v FROM unnest(source_rows) v
      UNION ALL SELECT 'source-binding', v FROM unnest(bindings) v UNION ALL SELECT 'source-stats-revision', v FROM unnest(revisions) v) t(k, v);
  -- The canonical JSON array of {"id","kind"} pairs ordered by (kind, id),
  -- mirrored by retentionIdsDigest() in persistence.ts. JSON escaping keeps it
  -- unambiguous whatever an identifier contains.
  SELECT encode(sha256(convert_to('[' || coalesce(string_agg('{"id":' || to_json(r.v)::text || ',"kind":' || to_json(r.k)::text || '}', ','
      ORDER BY r.n), '') || ']', 'UTF8')), 'hex')
    INTO ids_digest FROM unnest(removed_kinds, removed_ids) WITH ORDINALITY r(k, v, n);
  SELECT count(*) INTO links FROM public.predictive_artifact_observations l WHERE l.observation_id = ANY(obs) OR l.artifact_id = ANY(arts);
  SELECT count(*) INTO inputs FROM public.predictive_decision_inputs i WHERE i.decision_id = ANY(decs);
  SELECT count(*) INTO dependencies FROM public.predictive_feature_run_dependencies d WHERE d.feature_run_id = ANY(runs);
  SELECT count(*) INTO unpins FROM public.predictive_feature_run_unpins u WHERE u.pin_id = ANY(pins);
  counts := jsonb_build_object('observations', cardinality(obs), 'artifacts', cardinality(arts), 'captures', cardinality(caps),
    'decisions', cardinality(decs), 'labels', cardinality(labs), 'featureRuns', cardinality(runs), 'pins', cardinality(pins),
    'blobs', cardinality(blobs), 'links', links, 'decisionInputs', inputs, 'featureRunDependencies', dependencies, 'unpins', unpins);

  -- Preserve old zero-row event counts/digests for backup re-apply parity.
  IF cardinality(source_rows) > 0 THEN counts := counts || jsonb_build_object('sourceStatsRows', cardinality(source_rows)); END IF;
  IF cardinality(bindings)>0 THEN
    SELECT sum(n)::integer INTO binding_links FROM (
      SELECT count(*) AS n FROM public.predictive_source_binding_captures WHERE binding_id=ANY(bindings)
      UNION ALL SELECT count(*) FROM public.predictive_source_binding_rows WHERE binding_id=ANY(bindings)
      UNION ALL SELECT count(*) FROM public.predictive_source_binding_dependencies WHERE binding_id=ANY(bindings)
      UNION ALL SELECT count(*) FROM public.predictive_source_binding_links WHERE binding_id=ANY(bindings)
      UNION ALL SELECT count(*) FROM public.predictive_source_binding_decisions WHERE binding_id=ANY(bindings)
      UNION ALL SELECT count(*) FROM public.predictive_source_binding_rights WHERE binding_id=ANY(bindings)) x;
    counts:=counts || jsonb_build_object('sourceBindings',cardinality(bindings),'sourceStatsRevisions',cardinality(revisions),'sourceBindingLinks',binding_links);
  END IF;
  INSERT INTO public.predictive_retention_events (id,reason,authority,decided_at,scope_descriptor,audit_level,removed_counts,removed_ids_digest,executed_at)
    VALUES (event_id, event_reason, event_authority, event_decided_at, event_scope, event_audit_level, counts, ids_digest, pg_catalog.now());
  INSERT INTO public.predictive_retention_authorizations (txid, retention_event_id) VALUES (pg_catalog.pg_current_xact_id(), event_id);
  DELETE FROM public.predictive_source_binding_captures WHERE binding_id=ANY(bindings);
  DELETE FROM public.predictive_source_binding_rows WHERE binding_id=ANY(bindings);
  DELETE FROM public.predictive_source_binding_dependencies WHERE binding_id=ANY(bindings);
  DELETE FROM public.predictive_source_binding_links WHERE binding_id=ANY(bindings);
  DELETE FROM public.predictive_source_binding_decisions WHERE binding_id=ANY(bindings);
  DELETE FROM public.predictive_source_binding_rights WHERE binding_id=ANY(bindings);
  DELETE FROM public.predictive_source_bindings WHERE id=ANY(bindings);
  DELETE FROM public.predictive_source_stats_revisions WHERE id=ANY(revisions);
  DELETE FROM public.predictive_feature_run_unpins WHERE pin_id = ANY(pins);
  DELETE FROM public.predictive_feature_run_pins WHERE id = ANY(pins);
  DELETE FROM public.predictive_feature_run_dependencies WHERE feature_run_id = ANY(runs);
  DELETE FROM public.predictive_feature_runs WHERE id = ANY(runs);
  DELETE FROM public.predictive_outcome_labels WHERE id = ANY(labs);
  DELETE FROM public.predictive_decision_inputs WHERE decision_id = ANY(decs);
  DELETE FROM public.predictive_decisions WHERE id = ANY(decs);
  DELETE FROM public.predictive_artifact_observations WHERE observation_id = ANY(obs) OR artifact_id = ANY(arts);
  DELETE FROM public.predictive_observations WHERE id = ANY(obs);
  DELETE FROM public.predictive_source_stats_rows WHERE id = ANY(source_rows);
  DELETE FROM public.predictive_captures WHERE id = ANY(caps);
  DELETE FROM public.predictive_artifacts WHERE id = ANY(arts);
  DELETE FROM public.predictive_blobs WHERE sha256 = ANY(blobs);
  INSERT INTO public.predictive_blob_removals (storage_ref, queued_at) SELECT r, pg_catalog.now() FROM unnest(refs) r ON CONFLICT DO NOTHING;
  IF event_audit_level = 'full' THEN
    INSERT INTO public.predictive_retention_tombstones (retention_event_id, target_kind, target_id)
      SELECT event_id, r.k, r.v FROM unnest(removed_kinds, removed_ids) r(k, v);
  END IF;
  DELETE FROM public.predictive_retention_authorizations WHERE txid = pg_catalog.pg_current_xact_id();
  -- Blob references are returned to the caller for file removal, never stored
  -- for digest-only events.
  RETURN jsonb_build_object('eventId', event_id, 'removedCounts', counts, 'removedIdsDigest', ids_digest, 'removedBlobRefs', to_jsonb(refs));
END
$$;

-- A real CSV profile cannot bypass staging by wrapping generated revisions in
-- JSON. The separately guarded synthetic JSON harness retains its proof path.
CREATE OR REPLACE FUNCTION public.predictive_source_canonical_guard() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF EXISTS (SELECT 1 FROM public.predictive_artifacts a JOIN public.predictive_blobs b ON b.sha256=a.blob_sha256
      JOIN public.predictive_source_profiles p ON p.id=a.profile_id WHERE a.id=NEW.artifact_id
      AND p.parser_version='nflverse-csv-qualification-v1' AND (b.media_type='text/csv' OR p.purpose<>'synthetic-test')) THEN
    RAISE EXCEPTION 'predictive-source-canonical-binding-required' USING ERRCODE='23514'; END IF;
  RETURN NEW;
END
$$;

-- Preserve the v1 checker for historical audit. New bindings use v2, which
-- pins rights even on unavailable plans and reconstructs every failure witness.
ALTER FUNCTION public.predictive_source_plan_check(jsonb,timestamptz,boolean) RENAME TO predictive_source_plan_check_v1;

CREATE FUNCTION public.predictive_source_plan_v2(req jsonb, rights_time timestamptz) RETURNS jsonb
LANGUAGE plpgsql STABLE AS $$
DECLARE p public.predictive_source_profiles; t timestamptz; raw_key text;
  caps jsonb; cap jsonb; source_rows jsonb:='[]'; row_refs jsonb:='[]'; stats jsonb;
  reason text; candidate jsonb; deps jsonb:='[]'; links jsonb:='[]'; decisions jsonb:='[]'; rights_ids jsonb;
  ids text[]; rivals text[]; role_name text; fact text; game text; team text; opponent text; player text; chosen text;
  schedule jsonb; parts text[]; decision_ids text[]; values_count integer; bad boolean; data jsonb; b jsonb;
  d public.predictive_decisions;
BEGIN
  raw_key:=public.predictive_source_request_key(req); t:=(req->>'cutoff')::timestamptz;
  SELECT * INTO p FROM public.predictive_source_profiles WHERE id=req->>'profileId';
  IF rights_time IS NULL OR NOT isfinite(rights_time) OR t>rights_time OR p.id IS NULL OR p.provider<>'nflverse'
      OR p.parser_version<>'nflverse-csv-qualification-v1' OR p.allowlist_version<>'predictive-raw-allowlist-v1'
      OR p.feed NOT IN ('player','team') OR (p.feed='player') IS DISTINCT FROM (req->'rawPlayerId'<>'null'::jsonb)
      OR public.predictive_rights_allow(p.id,rights_time,rights_time,'internal-research') IS NOT TRUE THEN
    RAISE EXCEPTION 'predictive-source-plan-rights-profile-invalid' USING ERRCODE='23514'; END IF;

  WITH eligible AS (SELECT c.*,dense_rank() OVER (ORDER BY c.captured_at DESC) AS rank
    FROM public.predictive_captures c JOIN public.predictive_artifacts a ON a.id=c.artifact_id
    JOIN public.predictive_blobs bl ON bl.sha256=a.blob_sha256 JOIN public.predictive_ingestion_runs r ON r.id=c.run_id
    WHERE a.profile_id=p.id AND a.scope_kind='season-file' AND a.scope_season=2026 AND a.scope_filter IS NULL AND bl.media_type='text/csv'
      AND c.state='published' AND r.status='published' AND c.available_at<=t AND c.ingested_at<=t)
  SELECT coalesce(jsonb_agg(jsonb_build_object('id',c.id,'runId',c.run_id,'artifactId',c.artifact_id,
    'capturedAt',public.predictive_source_time(c.captured_at),'availableAt',public.predictive_source_time(c.available_at),
    'ingestedAt',public.predictive_source_time(c.ingested_at),'parsedRows',c.parsed_rows,'sha256',a.blob_sha256,
    'storageRef',bl.storage_ref,'byteSize',bl.byte_size) ORDER BY c.ingested_at,c.id COLLATE "C"),'[]')
    INTO caps FROM eligible c JOIN public.predictive_artifacts a ON a.id=c.artifact_id
    JOIN public.predictive_blobs bl ON bl.sha256=a.blob_sha256 WHERE c.rank=1;
  IF jsonb_array_length(caps)>256 THEN RAISE EXCEPTION 'predictive-source-plan-bounds-refused' USING ERRCODE='23514'; END IF;

  <<normalization>> BEGIN
    IF caps='[]'::jsonb THEN
      reason:=CASE WHEN EXISTS (SELECT 1 FROM public.predictive_retention_events
        WHERE scope_descriptor->>'kind'='source' AND scope_descriptor->'profileIds' ? p.id
          AND (scope_descriptor->>'capturedFrom' IS NULL OR (scope_descriptor->>'capturedFrom')::timestamptz<=t))
        THEN 'retained-evidence-removed' ELSE 'source-capture-missing' END;
      EXIT normalization;
    END IF;
    IF (SELECT count(DISTINCT x->>'sha256') FROM jsonb_array_elements(caps) x)>1 THEN
      reason:='source-capture-ambiguous'; EXIT normalization; END IF;
    cap:=caps->0; caps:=jsonb_build_array(cap);
    SELECT coalesce(jsonb_agg(jsonb_build_object('id',s.id,'rowOrdinal',s.row_ordinal,'rawKeySha256',s.raw_key_sha256,
        'selectedSha256',s.selected_sha256,'projection',s.projection,'failureCode',s.failure_code) ORDER BY s.row_ordinal),'[]'),
      coalesce(jsonb_agg(jsonb_build_object('id',s.id,'rowOrdinal',s.row_ordinal,'selectedSha256',s.selected_sha256) ORDER BY s.row_ordinal),'[]')
      INTO source_rows,row_refs FROM public.predictive_source_stats_rows s WHERE s.capture_id=cap->>'id' AND s.raw_key_sha256=raw_key;
    IF source_rows='[]'::jsonb THEN reason:='source-row-missing'; EXIT normalization;
    ELSIF (SELECT count(DISTINCT x->>'selectedSha256') FROM jsonb_array_elements(source_rows) x)>1 THEN
      reason:='source-row-ambiguous'; EXIT normalization;
    ELSIF source_rows->0->>'failureCode' IS NOT NULL THEN reason:='source-row-refused'; EXIT normalization; END IF;
    stats:=source_rows->0->'projection';

    FOREACH role_name IN ARRAY ARRAY['game-bridge','team-alias','opponent-alias'] LOOP
      fact:=CASE role_name WHEN 'game-bridge' THEN 'game-bridge:nflverse:' || (stats->>'rawGameId')
        WHEN 'team-alias' THEN 'team-alias:nflverse:' || (stats->>'rawTeam') ELSE 'team-alias:nflverse:' || (stats->>'rawOpponent') END;
      SELECT coalesce(array_agg(o.id ORDER BY o.id COLLATE "C"),'{}') INTO ids FROM public.predictive_observations o
        WHERE o.entity_key=fact AND public.predictive_source_is_head(o.id,t,rights_time);
      deps:=deps || public.predictive_source_dependencies(ids,role_name,t);
      SELECT count(DISTINCT CASE role_name WHEN 'game-bridge' THEN o.data->>'gameId' ELSE o.data->>'teamId' END),
        min(CASE role_name WHEN 'game-bridge' THEN o.data->>'gameId' ELSE o.data->>'teamId' END)
        INTO values_count,chosen FROM public.predictive_observations o WHERE o.id=ANY(ids) AND o.kind=CASE role_name WHEN 'game-bridge' THEN 'game-bridge' ELSE 'team-alias' END
          AND (role_name='game-bridge' OR ((o.data->>'effectiveFromSeason')::integer <= (stats->>'season')::integer
            AND (o.data->>'effectiveToSeason')::integer >= (stats->>'season')::integer));
      IF EXISTS (SELECT 1 FROM public.predictive_observations o WHERE o.id=ANY(ids) AND o.kind='source-row-absent') OR values_count>1 THEN
        reason:=role_name || '-conflict'; EXIT normalization;
      ELSIF values_count=0 THEN reason:=role_name || '-missing'; EXIT normalization; END IF;
      IF role_name='game-bridge' THEN
        game:=chosen;
        SELECT coalesce(array_agg(o.id ORDER BY o.id COLLATE "C"),'{}') INTO rivals FROM public.predictive_observations o
          WHERE o.kind='game-bridge' AND o.data->>'provider'=p.provider AND o.game_id=game::uuid
            AND o.data->>'rawGameId'<>stats->>'rawGameId' AND public.predictive_source_is_head(o.id,t,rights_time);
        IF cardinality(rivals)>0 THEN deps:=deps || public.predictive_source_dependencies(rivals,role_name,t);
          reason:='game-bridge-conflict'; EXIT normalization; END IF;
      ELSIF role_name='team-alias' THEN team:=chosen; ELSE opponent:=chosen; END IF;
    END LOOP;

    SELECT coalesce(array_agg(o.id ORDER BY o.id COLLATE "C"),'{}') INTO ids FROM public.predictive_observations o
      WHERE o.entity_key='schedule:' || game AND public.predictive_source_is_head(o.id,t,rights_time);
    IF EXISTS (SELECT 1 FROM public.predictive_observations o WHERE o.id=ANY(ids) AND o.kind='source-row-absent') THEN
      deps:=deps || public.predictive_source_dependencies(ids,'schedule',t); reason:='normalization-schedule-absent'; EXIT normalization; END IF;
    SELECT coalesce(array_agg(o.id ORDER BY o.id COLLATE "C"),'{}') INTO ids FROM public.predictive_observations o WHERE o.id=ANY(ids) AND o.kind='schedule';
    SELECT EXISTS (SELECT 1 FROM public.predictive_observations s JOIN public.predictive_observations a
      ON a.kind='schedule' AND a.raw_game_id=s.raw_game_id AND a.game_id<>s.game_id
      WHERE s.id=ANY(ids) AND public.predictive_source_is_head(a.id,t,rights_time)) INTO bad;
    IF bad THEN
      SELECT array_agg(o.id ORDER BY o.id COLLATE "C") INTO rivals FROM public.predictive_observations o WHERE o.kind='schedule'
        AND o.raw_game_id IN (SELECT s.raw_game_id FROM public.predictive_observations s WHERE s.id=ANY(ids))
        AND public.predictive_source_is_head(o.id,t,rights_time);
      deps:=deps || public.predictive_source_dependencies(rivals,'schedule',t); reason:='normalization-schedule-ambiguous'; EXIT normalization;
    END IF;
    deps:=deps || public.predictive_source_dependencies(ids,'schedule',t);
    IF cardinality(ids)=0 THEN reason:='normalization-schedule-missing'; EXIT normalization;
    ELSIF cardinality(ids)=1 THEN chosen:=ids[1];
    ELSE
      SELECT array_agg(x.id ORDER BY x.id COLLATE "C") INTO decision_ids FROM public.predictive_decisions x
        JOIN public.predictive_ingestion_runs r ON r.id=x.run_id WHERE x.entity_key='reconciliation:schedule:' || game AND x.kind='reconciliation'
        AND r.status='published' AND x.decided_at<=t
        AND NOT EXISTS (SELECT 1 FROM public.predictive_decisions n WHERE n.predecessor_id=x.id AND n.decided_at<=t);
      IF cardinality(decision_ids) IS DISTINCT FROM 1 THEN reason:='normalization-schedule-ambiguous'; EXIT normalization; END IF;
      SELECT * INTO d FROM public.predictive_decisions WHERE id=decision_ids[1];
      IF d.outcome->>'result' IS DISTINCT FROM 'selected' OR (d.outcome->>'selectedObservationId')<>ALL(ids)
          OR (SELECT array_agg(i.observation_id ORDER BY i.observation_id COLLATE "C") FROM public.predictive_decision_inputs i WHERE i.decision_id=d.id) IS DISTINCT FROM ids THEN
        reason:='normalization-schedule-ambiguous'; EXIT normalization; END IF;
      chosen:=d.outcome->>'selectedObservationId';
      decisions:=jsonb_build_array(jsonb_build_object('id',d.id,'kind',d.kind,'entityKey',d.entity_key,'policyId',d.policy_id,'mode',d.mode,
        'decidedAt',public.predictive_source_time(d.decided_at),'predecessorId',d.predecessor_id,'outcome',d.outcome,'inputs',
        (SELECT jsonb_agg(jsonb_build_object('observationId',i.observation_id,'role',i.role) ORDER BY i.observation_id COLLATE "C") FROM public.predictive_decision_inputs i WHERE i.decision_id=d.id)));
    END IF;
    SELECT o.data INTO schedule FROM public.predictive_observations o WHERE o.id=chosen;
    parts:=string_to_array(stats->>'rawGameId','_');
    IF schedule->'season' IS DISTINCT FROM stats->'season' OR schedule->'week' IS DISTINCT FROM stats->'week'
        OR schedule->'seasonType' IS DISTINCT FROM stats->'seasonType' OR team=opponent
        OR (schedule->>'homeTeamId') IS DISTINCT FROM (CASE WHEN (stats->>'rawTeam')=parts[4] THEN team ELSE opponent END)
        OR (schedule->>'awayTeamId') IS DISTINCT FROM (CASE WHEN (stats->>'rawTeam')=parts[3] THEN team ELSE opponent END) THEN
      reason:='source-schedule-context-conflict'; EXIT normalization; END IF;
    data:=jsonb_build_object('gameId',game,'rawGameId',stats->'rawGameId','teamId',team,'rawTeam',stats->'rawTeam',
      'season',stats->'season','seasonType',stats->'seasonType','missing',stats->'missing') || (stats->'values');
    IF p.feed='player' THEN
      SELECT coalesce(array_agg(o.id ORDER BY o.id COLLATE "C"),'{}') INTO ids FROM public.predictive_observations o
        WHERE o.entity_key='player-bridge:gsis:' || (stats->>'rawPlayerId') AND public.predictive_source_is_head(o.id,t,rights_time);
      deps:=deps || public.predictive_source_dependencies(ids,'player-bridge',t);
      SELECT count(DISTINCT o.player_id),min(o.player_id) INTO values_count,player FROM public.predictive_observations o
        WHERE o.id=ANY(ids) AND o.kind='player-bridge' AND (o.data->>'effectiveFrom')::timestamptz <= (schedule->>'kickoff')::timestamptz
        AND (schedule->>'kickoff')::timestamptz < (o.data->>'effectiveTo')::timestamptz;
      IF EXISTS (SELECT 1 FROM public.predictive_observations o WHERE o.id=ANY(ids) AND o.kind='source-row-absent') OR values_count>1 THEN
        reason:='player-bridge-conflict'; EXIT normalization;
      ELSIF values_count=0 THEN reason:='player-bridge-missing'; EXIT normalization; END IF;
      SELECT coalesce(array_agg(o.id ORDER BY o.id COLLATE "C"),'{}') INTO rivals FROM public.predictive_observations o
        WHERE o.kind='player-bridge' AND o.player_id=player AND o.data->>'provider'='gsis'
        AND (o.data->>'rawPlayerId') IS DISTINCT FROM (stats->>'rawPlayerId')
        AND (o.data->>'effectiveFrom')::timestamptz <= (schedule->>'kickoff')::timestamptz
        AND (schedule->>'kickoff')::timestamptz < (o.data->>'effectiveTo')::timestamptz AND public.predictive_source_is_head(o.id,t,rights_time);
      IF cardinality(rivals)>0 THEN deps:=deps || public.predictive_source_dependencies(rivals,'player-bridge',t);
        reason:='player-bridge-conflict'; EXIT normalization; END IF;
      SELECT coalesce(jsonb_agg(jsonb_build_object('id',k.id,'statsProfileId',k.stats_profile_id,'bridgeProfileId',k.bridge_profile_id,
        'provider',k.provider,'decidedAt',public.predictive_source_time(k.decided_at)) ORDER BY k.id COLLATE "C"),'[]') INTO links
        FROM public.predictive_profile_identity_links k WHERE k.stats_profile_id=p.id AND k.provider='gsis' AND k.decided_at<=t
        AND EXISTS (SELECT 1 FROM public.predictive_observations o WHERE o.id=ANY(ids) AND o.kind='player-bridge'
          AND o.profile_id=k.bridge_profile_id AND o.player_id=player AND (o.data->>'effectiveFrom')::timestamptz <= (schedule->>'kickoff')::timestamptz
          AND (schedule->>'kickoff')::timestamptz < (o.data->>'effectiveTo')::timestamptz);
      IF links='[]'::jsonb THEN reason:='player-bridge-link-missing'; EXIT normalization; END IF;
      data:=data || jsonb_build_object('playerId',player,'rawPlayerId',stats->'rawPlayerId','playerIdProvider','gsis');
    END IF;
    candidate:=jsonb_build_object('kind',CASE p.feed WHEN 'player' THEN 'player-game-stats' ELSE 'team-game-stats' END,'data',data);
  END normalization;

  SELECT coalesce(jsonb_agg(x ORDER BY x->>'role' COLLATE "C",x->>'observationId' COLLATE "C"),'[]') INTO deps FROM jsonb_array_elements(deps) x;
  SELECT jsonb_agg(to_jsonb(public.predictive_rights_in_force(id,rights_time,rights_time))
    ORDER BY public.predictive_rights_in_force(id,rights_time,rights_time) COLLATE "C") INTO rights_ids FROM (
    SELECT p.id UNION SELECT x->>'profileId' FROM jsonb_array_elements(deps) x) profiles(id);
  IF EXISTS (SELECT 1 FROM jsonb_array_elements(deps) x WHERE public.predictive_rights_allow(x->>'profileId',rights_time,rights_time,'internal-research') IS NOT TRUE) THEN
    RAISE EXCEPTION 'predictive-source-plan-rights-profile-invalid' USING ERRCODE='23514'; END IF;
  b:=jsonb_build_object('version','nflverse-stats-normalization-plan-v2','cutoff',req->'cutoff','sourceRequest',req,
    'sourceInputDigest',public.predictive_source_digest(jsonb_build_object('version','nflverse-csv-source-claims-v1','request',req,'captures',caps,'rows',source_rows)),
    'sourceProfileId',p.id,'rawSourceKey',CASE WHEN source_rows='[]'::jsonb THEN NULL ELSE raw_key END,
    'sourceCaptures',caps,'sourceRows',row_refs,'parserVersion','nflverse-csv-qualification-v1','projectionVersion','nflverse-raw-stats-v1',
    'dependencies',deps,'identityLinks',links,'decisions',decisions,'rightsDecisionIds',rights_ids);
  RETURN jsonb_build_object('status',CASE WHEN reason IS NULL THEN 'planned-source-normalization' ELSE 'unavailable-source-normalization' END,
    'reason',reason,'candidate',candidate,'dataDigest',public.predictive_source_digest(candidate),'binding',b,
    'planDigest',public.predictive_source_digest(jsonb_build_object('reason',reason,'candidate',candidate,'binding',b)),
    'observationsPublished',false,'featuresPublished',false,'labelsFinalized',false,'populationCoverage','unqualified');
END
$$;

CREATE FUNCTION public.predictive_source_plan_basis(plan jsonb) RETURNS jsonb
LANGUAGE sql IMMUTABLE STRICT AS $$ SELECT jsonb_build_object('reason',$1->'reason','candidate',$1->'candidate',
  'binding',($1->'binding')-ARRAY['version','cutoff','sourceInputDigest','rightsDecisionIds','sourceRequest'],
  'request',($1->'binding'->'sourceRequest')-'cutoff') $$;

CREATE FUNCTION public.predictive_source_plan_check(proposed jsonb, rights_time timestamptz, require_current boolean) RETURNS void
LANGUAGE plpgsql STABLE AS $$
DECLARE req jsonb:=proposed->'binding'->'sourceRequest'; expected jsonb; current_plan jsonb;
BEGIN
  IF require_current IS NULL THEN RAISE EXCEPTION 'predictive-source-plan-invalid' USING ERRCODE='23514'; END IF;
  IF proposed->'binding'->>'version'='nflverse-stats-normalization-plan-v1' AND NOT require_current THEN
    PERFORM public.predictive_source_plan_check_v1(proposed,rights_time,false); RETURN; END IF;
  IF proposed->'binding'->>'version' IS DISTINCT FROM 'nflverse-stats-normalization-plan-v2' THEN
    RAISE EXCEPTION 'predictive-source-plan-version-invalid' USING ERRCODE='23514'; END IF;
  expected:=public.predictive_source_plan_v2(req,rights_time);
  IF proposed IS DISTINCT FROM expected THEN RAISE EXCEPTION 'predictive-source-plan-witness-invalid' USING ERRCODE='23514'; END IF;
  IF require_current THEN
    current_plan:=public.predictive_source_plan_v2(jsonb_set(req,'{cutoff}',to_jsonb(public.predictive_source_time(rights_time))),rights_time);
    IF public.predictive_source_plan_basis(proposed) IS DISTINCT FROM public.predictive_source_plan_basis(current_plan) THEN
      RAISE EXCEPTION 'predictive-source-plan-stale' USING ERRCODE='23514'; END IF;
  END IF;
END
$$;
REVOKE ALL ON FUNCTION public.predictive_source_plan_v2(jsonb,timestamptz),public.predictive_source_plan_basis(jsonb),
  public.predictive_source_plan_check(jsonb,timestamptz,boolean) FROM PUBLIC;

-- Capture-less states cannot prove they fall outside a provider deletion window.
-- Conservatively remove their complete raw lineage whenever that source is scoped.
CREATE OR REPLACE FUNCTION public.predictive_retention_execute(event_id text, event_reason text, event_authority text, event_decided_at timestamptz,
  event_scope jsonb, event_audit_level text) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $$
DECLARE
  profiles text[]; captured_from timestamptz; captured_before timestamptz; as_of timestamptz;
  arts text[] := '{}'; caps text[] := '{}'; obs text[] := '{}'; decs text[] := '{}'; labs text[] := '{}';
  runs text[] := '{}'; pins text[] := '{}'; blobs text[] := '{}'; refs text[]; source_rows text[] := '{}'; bindings text[] := '{}'; revisions text[] := '{}'; binding_links integer;
  removed_kinds text[]; removed_ids text[]; counts jsonb; ids_digest text; links integer; inputs integer; dependencies integer; unpins integer;
BEGIN
  IF NOT pg_catalog.pg_has_role(session_user, 'predictive_retention_owner', 'MEMBER') THEN
    RAISE EXCEPTION 'predictive-retention-not-authorized' USING ERRCODE = '42501';
  END IF;
  IF event_decided_at IS NULL OR event_decided_at > pg_catalog.now() OR NOT public.predictive_retention_scope_valid(event_reason, event_scope) THEN
    RAISE EXCEPTION 'predictive-retention-invalid' USING ERRCODE = '23514';
  END IF;
  PERFORM pg_catalog.pg_advisory_xact_lock(520052,1);
  LOCK TABLE public.predictive_source_bindings,public.predictive_source_stats_revisions IN SHARE ROW EXCLUSIVE MODE;
  IF event_scope->>'kind' = 'source' THEN
    profiles := ARRAY(SELECT jsonb_array_elements_text(event_scope->'profileIds'));
    IF EXISTS (SELECT 1 FROM unnest(profiles) p WHERE NOT EXISTS (SELECT 1 FROM public.predictive_source_profiles sp WHERE sp.id = p)) THEN
      RAISE EXCEPTION 'predictive-retention-invalid' USING ERRCODE = '23514';
    END IF;
    captured_from := (event_scope->>'capturedFrom')::timestamptz; captured_before := (event_scope->>'capturedBefore')::timestamptz;
    -- An artifact with any capture in range is removed whole, bytes and captures.
    arts := ARRAY(SELECT DISTINCT a.id FROM public.predictive_artifacts a JOIN public.predictive_captures c ON c.artifact_id = a.id
      WHERE a.profile_id = ANY(profiles) AND (captured_from IS NULL OR c.captured_at >= captured_from)
        AND (captured_before IS NULL OR c.captured_at < captured_before));
    caps := ARRAY(SELECT c.id FROM public.predictive_captures c WHERE c.artifact_id = ANY(arts));
    obs := ARRAY(WITH RECURSIVE chain AS (
        SELECT o.id FROM public.predictive_observations o JOIN public.predictive_artifact_observations l ON l.observation_id = o.id
        WHERE l.artifact_id = ANY(arts) AND o.profile_id = ANY(profiles)
        UNION SELECT n.id FROM public.predictive_observations n JOIN chain ON n.predecessor_id = chain.id)
      SELECT id FROM chain);
    decs := ARRAY(WITH RECURSIVE chain AS (
        SELECT DISTINCT i.decision_id AS id FROM public.predictive_decision_inputs i WHERE i.observation_id = ANY(obs)
        UNION SELECT n.id FROM public.predictive_decisions n JOIN chain ON n.predecessor_id = chain.id)
      SELECT id FROM chain);
    labs := ARRAY(WITH RECURSIVE chain AS (
        SELECT l.id FROM public.predictive_outcome_labels l WHERE l.completion_decision_id = ANY(decs) OR l.participation_decision_id = ANY(decs)
          OR l.reconciliation_decision_id = ANY(decs) OR l.selected_observation_id = ANY(obs) OR l.post_window_capture_id = ANY(caps)
          OR l.player_bridge_observation_id = ANY(obs)
        UNION SELECT n.id FROM public.predictive_outcome_labels n JOIN chain ON n.predecessor_id = chain.id)
      SELECT id FROM chain);
    runs := ARRAY(SELECT DISTINCT d.feature_run_id FROM public.predictive_feature_run_dependencies d
      WHERE d.observation_id = ANY(obs) OR d.decision_id = ANY(decs));
  ELSE
    as_of := (event_scope->>'asOf')::timestamptz;
    IF as_of > pg_catalog.now() THEN RAISE EXCEPTION 'predictive-retention-invalid' USING ERRCODE = '23514'; END IF;
    runs := ARRAY(SELECT f.id FROM public.predictive_feature_runs f WHERE public.predictive_feature_run_expired(f.id, as_of));
  END IF;
  source_rows := ARRAY(SELECT s.id FROM public.predictive_source_stats_rows s WHERE s.capture_id = ANY(caps));
  bindings := ARRAY(WITH affected AS (
      SELECT b.profile_id,b.raw_key_sha256 FROM public.predictive_source_bindings b WHERE
        (b.profile_id=ANY(profiles) AND NOT EXISTS (SELECT 1 FROM public.predictive_source_binding_captures x WHERE x.binding_id=b.id))
        OR EXISTS (SELECT 1 FROM public.predictive_source_binding_captures x WHERE x.binding_id=b.id AND x.capture_id=ANY(caps))
        OR EXISTS (SELECT 1 FROM public.predictive_source_binding_rows x WHERE x.binding_id=b.id AND x.row_id=ANY(source_rows))
        OR EXISTS (SELECT 1 FROM public.predictive_source_binding_dependencies x WHERE x.binding_id=b.id
          AND (x.observation_id=ANY(obs) OR x.capture_id=ANY(caps) OR x.artifact_id=ANY(arts)))
        OR EXISTS (SELECT 1 FROM public.predictive_source_binding_decisions x WHERE x.binding_id=b.id AND x.decision_id=ANY(decs)))
    SELECT DISTINCT b.id FROM public.predictive_source_bindings b JOIN affected a USING(profile_id,raw_key_sha256));
  revisions := ARRAY(SELECT r.id FROM public.predictive_source_stats_revisions r WHERE EXISTS (
    SELECT 1 FROM public.predictive_source_bindings b WHERE b.id=ANY(bindings) AND b.profile_id=r.profile_id AND b.raw_key_sha256=r.source_record_id));
  pins := ARRAY(SELECT p.id FROM public.predictive_feature_run_pins p WHERE p.feature_run_id = ANY(runs));
  blobs := ARRAY(SELECT DISTINCT b.sha256 FROM public.predictive_blobs b
    WHERE (b.sha256 IN (SELECT a.blob_sha256 FROM public.predictive_artifacts a WHERE a.id = ANY(arts))
        OR b.sha256 IN (SELECT f.bundle_blob_sha256 FROM public.predictive_feature_runs f WHERE f.id = ANY(runs)))
      AND NOT EXISTS (SELECT 1 FROM public.predictive_artifacts a WHERE a.blob_sha256 = b.sha256 AND NOT a.id = ANY(arts))
      AND NOT EXISTS (SELECT 1 FROM public.predictive_feature_runs f WHERE f.bundle_blob_sha256 = b.sha256 AND NOT f.id = ANY(runs)));
  refs := ARRAY(SELECT b.storage_ref FROM public.predictive_blobs b WHERE b.sha256 = ANY(blobs) ORDER BY b.storage_ref COLLATE "C");

  -- Parallel arrays, never a temp table: a caller could pre-create a pg_temp
  -- relation that this definer function would then use.
  SELECT coalesce(array_agg(k ORDER BY k COLLATE "C", v COLLATE "C"), '{}'), coalesce(array_agg(v ORDER BY k COLLATE "C", v COLLATE "C"), '{}')
    INTO removed_kinds, removed_ids FROM (
      SELECT 'observation', v FROM unnest(obs) v UNION ALL SELECT 'artifact', v FROM unnest(arts) v
      UNION ALL SELECT 'capture', v FROM unnest(caps) v UNION ALL SELECT 'decision', v FROM unnest(decs) v
      UNION ALL SELECT 'label', v FROM unnest(labs) v UNION ALL SELECT 'feature-run', v FROM unnest(runs) v
      UNION ALL SELECT 'pin', v FROM unnest(pins) v UNION ALL SELECT 'blob', v FROM unnest(blobs) v
      UNION ALL SELECT 'source-stats-row', v FROM unnest(source_rows) v
      UNION ALL SELECT 'source-binding', v FROM unnest(bindings) v UNION ALL SELECT 'source-stats-revision', v FROM unnest(revisions) v) t(k, v);
  -- The canonical JSON array of {"id","kind"} pairs ordered by (kind, id),
  -- mirrored by retentionIdsDigest() in persistence.ts. JSON escaping keeps it
  -- unambiguous whatever an identifier contains.
  SELECT encode(sha256(convert_to('[' || coalesce(string_agg('{"id":' || to_json(r.v)::text || ',"kind":' || to_json(r.k)::text || '}', ','
      ORDER BY r.n), '') || ']', 'UTF8')), 'hex')
    INTO ids_digest FROM unnest(removed_kinds, removed_ids) WITH ORDINALITY r(k, v, n);
  SELECT count(*) INTO links FROM public.predictive_artifact_observations l WHERE l.observation_id = ANY(obs) OR l.artifact_id = ANY(arts);
  SELECT count(*) INTO inputs FROM public.predictive_decision_inputs i WHERE i.decision_id = ANY(decs);
  SELECT count(*) INTO dependencies FROM public.predictive_feature_run_dependencies d WHERE d.feature_run_id = ANY(runs);
  SELECT count(*) INTO unpins FROM public.predictive_feature_run_unpins u WHERE u.pin_id = ANY(pins);
  counts := jsonb_build_object('observations', cardinality(obs), 'artifacts', cardinality(arts), 'captures', cardinality(caps),
    'decisions', cardinality(decs), 'labels', cardinality(labs), 'featureRuns', cardinality(runs), 'pins', cardinality(pins),
    'blobs', cardinality(blobs), 'links', links, 'decisionInputs', inputs, 'featureRunDependencies', dependencies, 'unpins', unpins);

  -- Preserve old zero-row event counts/digests for backup re-apply parity.
  IF cardinality(source_rows) > 0 THEN counts := counts || jsonb_build_object('sourceStatsRows', cardinality(source_rows)); END IF;
  IF cardinality(bindings)>0 THEN
    SELECT sum(n)::integer INTO binding_links FROM (
      SELECT count(*) AS n FROM public.predictive_source_binding_captures WHERE binding_id=ANY(bindings)
      UNION ALL SELECT count(*) FROM public.predictive_source_binding_rows WHERE binding_id=ANY(bindings)
      UNION ALL SELECT count(*) FROM public.predictive_source_binding_dependencies WHERE binding_id=ANY(bindings)
      UNION ALL SELECT count(*) FROM public.predictive_source_binding_links WHERE binding_id=ANY(bindings)
      UNION ALL SELECT count(*) FROM public.predictive_source_binding_decisions WHERE binding_id=ANY(bindings)
      UNION ALL SELECT count(*) FROM public.predictive_source_binding_rights WHERE binding_id=ANY(bindings)) x;
    counts:=counts || jsonb_build_object('sourceBindings',cardinality(bindings),'sourceStatsRevisions',cardinality(revisions),'sourceBindingLinks',binding_links);
  END IF;
  INSERT INTO public.predictive_retention_events (id,reason,authority,decided_at,scope_descriptor,audit_level,removed_counts,removed_ids_digest,executed_at)
    VALUES (event_id, event_reason, event_authority, event_decided_at, event_scope, event_audit_level, counts, ids_digest, pg_catalog.now());
  INSERT INTO public.predictive_retention_authorizations (txid, retention_event_id) VALUES (pg_catalog.pg_current_xact_id(), event_id);
  DELETE FROM public.predictive_source_binding_captures WHERE binding_id=ANY(bindings);
  DELETE FROM public.predictive_source_binding_rows WHERE binding_id=ANY(bindings);
  DELETE FROM public.predictive_source_binding_dependencies WHERE binding_id=ANY(bindings);
  DELETE FROM public.predictive_source_binding_links WHERE binding_id=ANY(bindings);
  DELETE FROM public.predictive_source_binding_decisions WHERE binding_id=ANY(bindings);
  DELETE FROM public.predictive_source_binding_rights WHERE binding_id=ANY(bindings);
  DELETE FROM public.predictive_source_bindings WHERE id=ANY(bindings);
  DELETE FROM public.predictive_source_stats_revisions WHERE id=ANY(revisions);
  DELETE FROM public.predictive_feature_run_unpins WHERE pin_id = ANY(pins);
  DELETE FROM public.predictive_feature_run_pins WHERE id = ANY(pins);
  DELETE FROM public.predictive_feature_run_dependencies WHERE feature_run_id = ANY(runs);
  DELETE FROM public.predictive_feature_runs WHERE id = ANY(runs);
  DELETE FROM public.predictive_outcome_labels WHERE id = ANY(labs);
  DELETE FROM public.predictive_decision_inputs WHERE decision_id = ANY(decs);
  DELETE FROM public.predictive_decisions WHERE id = ANY(decs);
  DELETE FROM public.predictive_artifact_observations WHERE observation_id = ANY(obs) OR artifact_id = ANY(arts);
  DELETE FROM public.predictive_observations WHERE id = ANY(obs);
  DELETE FROM public.predictive_source_stats_rows WHERE id = ANY(source_rows);
  DELETE FROM public.predictive_captures WHERE id = ANY(caps);
  DELETE FROM public.predictive_artifacts WHERE id = ANY(arts);
  DELETE FROM public.predictive_blobs WHERE sha256 = ANY(blobs);
  INSERT INTO public.predictive_blob_removals (storage_ref, queued_at) SELECT r, pg_catalog.now() FROM unnest(refs) r ON CONFLICT DO NOTHING;
  IF event_audit_level = 'full' THEN
    INSERT INTO public.predictive_retention_tombstones (retention_event_id, target_kind, target_id)
      SELECT event_id, r.k, r.v FROM unnest(removed_kinds, removed_ids) r(k, v);
  END IF;
  DELETE FROM public.predictive_retention_authorizations WHERE txid = pg_catalog.pg_current_xact_id();
  -- Blob references are returned to the caller for file removal, never stored
  -- for digest-only events.
  RETURN jsonb_build_object('eventId', event_id, 'removedCounts', counts, 'removedIdsDigest', ids_digest, 'removedBlobRefs', to_jsonb(refs));
END
$$;

-- A real CSV profile cannot bypass staging by wrapping generated revisions in
-- JSON. The separately guarded synthetic JSON harness retains its proof path.
CREATE OR REPLACE FUNCTION public.predictive_source_canonical_guard() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF EXISTS (SELECT 1 FROM public.predictive_artifacts a JOIN public.predictive_blobs b ON b.sha256=a.blob_sha256
      JOIN public.predictive_source_profiles p ON p.id=a.profile_id WHERE a.id=NEW.artifact_id
      AND p.parser_version='nflverse-csv-qualification-v1' AND (b.media_type='text/csv' OR p.purpose<>'synthetic-test')) THEN
    RAISE EXCEPTION 'predictive-source-canonical-binding-required' USING ERRCODE='23514'; END IF;
  RETURN NEW;
END
$$;

-- One binding-aware evidence contract for downstream research consumers.
-- Revisions alone are not heads: an unchanged recapture can reuse a revision,
-- and a raw lineage can move to an unrecorded canonical destination. Discover
-- every recorded raw chain in the explicit profiles BEFORE applying the entity
-- filter. This is recorded-lineage coverage, never a qualified population.
--
-- This kernel proves database metadata, not filesystem bytes. Application reads
-- must still verify the exact CSV/JSON files before using its witness. It does
-- not activate the released feature/decision/label writers or authorize uses
-- other than internal research. Those writers must adopt this same contract in
-- a subsequent forward migration, together with their use-specific rights.
CREATE FUNCTION public.predictive_source_witness_at(req jsonb, rights_time timestamptz) RETURNS jsonb
LANGUAGE plpgsql STABLE SET search_path = pg_catalog, pg_temp AS $$
DECLARE profiles text[]; entities text[]; t timestamptz; reason text;
  heads jsonb := '[]'; withheld jsonb := '[]'; missing jsonb := '[]'; fields jsonb;
  raw record; event record; head public.predictive_source_bindings; plan jsonb; fact text; lineage text;
  destinations jsonb; routing text; failure text; n integer;
BEGIN
  IF public.predictive_source_exact(req,ARRAY['profileIds','entityKeys','cutoff']) IS NOT TRUE
      OR jsonb_typeof(req->'profileIds') IS DISTINCT FROM 'array' OR jsonb_typeof(req->'entityKeys') IS DISTINCT FROM 'array'
      OR jsonb_array_length(req->'profileIds') NOT BETWEEN 1 AND 16 OR jsonb_array_length(req->'entityKeys')>64
      OR EXISTS (SELECT 1 FROM jsonb_array_elements((req->'profileIds') || (req->'entityKeys')) x WHERE jsonb_typeof(x)<>'string')
      OR public.predictive_instant(req->>'cutoff') IS NOT TRUE OR rights_time IS NULL OR NOT isfinite(rights_time) THEN
    RAISE EXCEPTION 'predictive-source-witness-request-refused' USING ERRCODE='23514'; END IF;
  profiles:=ARRAY(SELECT x FROM jsonb_array_elements_text(req->'profileIds') x);
  entities:=ARRAY(SELECT x FROM jsonb_array_elements_text(req->'entityKeys') x);
  IF profiles IS DISTINCT FROM ARRAY(SELECT DISTINCT x COLLATE "C" FROM unnest(profiles) x ORDER BY 1)
      OR entities IS DISTINCT FROM ARRAY(SELECT DISTINCT x COLLATE "C" FROM unnest(entities) x ORDER BY 1)
      OR EXISTS (SELECT 1 FROM unnest(profiles) x WHERE length(x) NOT BETWEEN 1 AND 256 OR length(btrim(x))=0 OR x ~ '[[:cntrl:]|]')
      OR EXISTS (SELECT 1 FROM unnest(entities) x WHERE x !~ '^(player-game-stats|team-game-stats):[a-f0-9]{8}-[a-f0-9]{4}-4[a-f0-9]{3}-[89ab][a-f0-9]{3}-[a-f0-9]{12}:'
        OR CASE split_part(x,':',1) WHEN 'player-game-stats' THEN split_part(x,':',3) !~ '^00-[0-9]{7}$' OR cardinality(string_to_array(x,':'))<>3
          ELSE NOT EXISTS (SELECT 1 FROM public.predictive_teams tm WHERE tm.id=regexp_replace(x,'^[^:]+:[^:]+:','')) END) THEN
    RAISE EXCEPTION 'predictive-source-witness-request-refused' USING ERRCODE='23514'; END IF;
  t:=(req->>'cutoff')::timestamptz;
  IF t>rights_time THEN RAISE EXCEPTION 'source-binding-future-cutoff-refused' USING ERRCODE='23514'; END IF;

  <<evidence>> BEGIN
    IF EXISTS (SELECT 1 FROM unnest(profiles) p WHERE NOT EXISTS (SELECT 1 FROM public.predictive_source_profiles s WHERE s.id=p)) THEN
      reason:='source-profile-missing'; EXIT evidence; END IF;
    IF EXISTS (SELECT 1 FROM public.predictive_source_profiles s WHERE s.id=ANY(profiles) AND
      (s.provider<>'nflverse' OR s.feed NOT IN ('player','team') OR s.parser_version<>'nflverse-csv-qualification-v1'
        OR s.allowlist_version<>'predictive-raw-allowlist-v1')) THEN reason:='source-profile-refused'; EXIT evidence; END IF;
    IF EXISTS (SELECT 1 FROM unnest(profiles) p WHERE public.predictive_rights_allow(p,rights_time,rights_time,'internal-research') IS NOT TRUE) THEN
      reason:='rights-not-in-force'; EXIT evidence; END IF;

    SELECT count(*) INTO n FROM public.predictive_source_bindings b WHERE b.profile_id=ANY(profiles) AND b.recorded_at<=t;
    IF n>8192 OR EXISTS (SELECT 1 FROM public.predictive_source_bindings b WHERE b.profile_id=ANY(profiles) AND b.recorded_at<=t
        GROUP BY b.profile_id,b.raw_key_sha256 HAVING count(*)>256)
      OR (SELECT count(*) FROM (SELECT DISTINCT b.profile_id,b.raw_key_sha256 FROM public.predictive_source_bindings b
        WHERE b.profile_id=ANY(profiles) AND b.recorded_at<=t) x)>256 THEN
      RAISE EXCEPTION 'source-fact-bounds-refused' USING ERRCODE='23514'; END IF;
    -- Check ALL historical context rights before examining plans. A revoked
    -- ancestor cannot be read to argue that its chain is irrelevant to a filter.
    IF EXISTS (SELECT 1 FROM public.predictive_source_bindings b CROSS JOIN LATERAL jsonb_array_elements(b.plan->'binding'->'dependencies') x
        WHERE b.profile_id=ANY(profiles) AND b.recorded_at<=t
          AND public.predictive_rights_allow(x->>'profileId',rights_time,rights_time,'internal-research') IS NOT TRUE) THEN
      reason:='rights-not-in-force'; EXIT evidence; END IF;
    FOR event IN SELECT b.* FROM public.predictive_source_bindings b WHERE b.profile_id=ANY(profiles) AND b.recorded_at<=t LOOP
      PERFORM public.predictive_source_plan_check(event.plan,event.recorded_at,false);
    END LOOP;

    FOR raw IN SELECT b.profile_id,b.raw_key_sha256,(b.plan->'binding'->'sourceRequest')-'cutoff' AS request
      FROM public.predictive_source_bindings b WHERE b.profile_id=ANY(profiles) AND b.recorded_at<=t
      GROUP BY b.profile_id,b.raw_key_sha256,(b.plan->'binding'->'sourceRequest')-'cutoff'
      ORDER BY b.profile_id COLLATE "C",b.raw_key_sha256 COLLATE "C",(b.plan->'binding'->'sourceRequest')-'cutoff' LOOP
      IF raw.profile_id IS DISTINCT FROM raw.request->>'profileId'
          OR raw.raw_key_sha256 IS DISTINCT FROM public.predictive_source_request_key(raw.request || jsonb_build_object('cutoff',req->'cutoff')) THEN
        RAISE EXCEPTION 'stored-source-binding-mismatch' USING ERRCODE='23514'; END IF;
      SELECT b.* INTO STRICT head FROM public.predictive_source_bindings b WHERE b.profile_id=raw.profile_id AND b.raw_key_sha256=raw.raw_key_sha256
        AND b.recorded_at<=t AND NOT EXISTS (SELECT 1 FROM public.predictive_source_bindings next WHERE next.predecessor_id=b.id AND next.recorded_at<=t);
      plan:=public.predictive_source_plan_v2(raw.request || jsonb_build_object('cutoff',req->'cutoff'),rights_time);
      lineage:='source-stats:' || public.predictive_source_digest(jsonb_build_array(raw.profile_id,raw.raw_key_sha256));
      failure:=CASE WHEN public.predictive_source_plan_basis(head.plan) IS DISTINCT FROM public.predictive_source_plan_basis(plan)
        THEN 'source-binding-stale' WHEN head.revision_id IS NULL THEN coalesce(head.plan->>'reason','source-binding-withheld') END;
      IF failure IS NOT NULL THEN
        SELECT coalesce(jsonb_agg(to_jsonb(key) ORDER BY key COLLATE "C"),'[]') INTO destinations FROM (
          SELECT r.entity_key AS key FROM public.predictive_source_bindings b JOIN public.predictive_source_stats_revisions r ON r.id=b.revision_id
            WHERE b.profile_id=raw.profile_id AND b.raw_key_sha256=raw.raw_key_sha256 AND b.recorded_at<=t
          UNION SELECT (plan->'candidate'->>'kind') || ':' || (plan->'candidate'->'data'->>'gameId') || ':' ||
            coalesce(plan->'candidate'->'data'->>'playerId',plan->'candidate'->'data'->>'teamId') WHERE plan->'candidate'<>'null'::jsonb
        ) keys WHERE cardinality(entities)=0 OR key=ANY(entities);
        routing:=CASE WHEN plan->'candidate'='null'::jsonb THEN 'unresolved' ELSE 'known-destinations' END;
        IF routing='unresolved' OR cardinality(entities)=0 OR jsonb_array_length(destinations)>0 THEN
          withheld:=withheld || jsonb_build_array(jsonb_build_object('lineageKey',lineage,'profileId',raw.profile_id,'bindingId',head.id,
            'reason',failure,'routing',routing,'entityKeys',destinations)); END IF;
      ELSE
        SELECT r.entity_key INTO STRICT fact FROM public.predictive_source_stats_revisions r WHERE r.id=head.revision_id;
        IF cardinality(entities)=0 OR fact=ANY(entities) THEN
          heads:=heads || jsonb_build_array(jsonb_build_object('profileId',raw.profile_id,'lineageKey',lineage,'entityKey',fact,
            'bindingId',head.id,'revisionId',head.revision_id,'headToken',public.predictive_source_digest(jsonb_build_object(
              'bindingId',head.id,'revisionId',head.revision_id,'planDigest',head.plan->>'planDigest')))); END IF;
      END IF;
    END LOOP;
    SELECT coalesce(jsonb_agg(x ORDER BY x->>'lineageKey' COLLATE "C"),'[]') INTO heads FROM jsonb_array_elements(heads) x;
    SELECT coalesce(jsonb_agg(x ORDER BY x->>'lineageKey' COLLATE "C"),'[]') INTO withheld FROM jsonb_array_elements(withheld) x;
    SELECT coalesce(jsonb_agg(to_jsonb(key) ORDER BY key COLLATE "C"),'[]') INTO missing FROM unnest(entities) key
      WHERE NOT EXISTS (SELECT 1 FROM jsonb_array_elements(heads) h WHERE h->>'entityKey'=key)
        AND NOT EXISTS (SELECT 1 FROM jsonb_array_elements(withheld) w WHERE w->>'routing'='unresolved' OR w->'entityKeys' ? key);
  END evidence;
  fields:=jsonb_build_object('version','source-consumer-witness-v1','profileIds',to_jsonb(profiles),'entityKeys',to_jsonb(entities),
    'coverage','recorded-lineages-only','heads',heads,'withheld',withheld,'reason',reason,'missingEntityKeys',missing);
  RETURN fields || jsonb_build_object('cutoff',req->'cutoff','evidenceDigest',public.predictive_source_digest(fields));
END
$$;

-- Private checker for future recorder functions: a rehashed omission is refused
-- against recomputed SQL metadata. Current use additionally requires the exact
-- same bindings now, with no withheld or missing requested entity. Query time
-- alone does not change the evidence digest. Full population is still unproven.
CREATE FUNCTION public.predictive_source_witness_check(proposed jsonb, rights_time timestamptz, require_current boolean) RETURNS void
LANGUAGE plpgsql STABLE SET search_path = pg_catalog, pg_temp AS $$
DECLARE req jsonb; expected jsonb; current_witness jsonb;
BEGIN
  IF require_current IS NULL THEN RAISE EXCEPTION 'predictive-source-witness-invalid' USING ERRCODE='23514'; END IF;
  req:=jsonb_build_object('profileIds',proposed->'profileIds','entityKeys',proposed->'entityKeys','cutoff',proposed->'cutoff');
  expected:=public.predictive_source_witness_at(req,rights_time);
  IF proposed IS DISTINCT FROM expected THEN RAISE EXCEPTION 'predictive-source-witness-invalid' USING ERRCODE='23514'; END IF;
  IF require_current THEN
    current_witness:=public.predictive_source_witness_at(jsonb_set(req,'{cutoff}',to_jsonb(public.predictive_source_time(rights_time))),rights_time);
    IF current_witness->>'reason' IS NOT NULL OR current_witness->'withheld'<>'[]'::jsonb
        OR current_witness->'missingEntityKeys'<>'[]'::jsonb OR current_witness->'heads'='[]'::jsonb
        OR proposed->>'evidenceDigest' IS DISTINCT FROM current_witness->>'evidenceDigest' THEN
      RAISE EXCEPTION 'predictive-source-witness-not-current' USING ERRCODE='23514'; END IF;
  END IF;
END
$$;

-- Replay/recorder access uses the database's clock; callers cannot backdate
-- rights. Internal kernels remain unavailable to application roles and PUBLIC.
CREATE FUNCTION public.predictive_source_witness(req jsonb) RETURNS jsonb
LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $$
BEGIN
  IF NOT (pg_catalog.pg_has_role(session_user,'predictive_replay','MEMBER')
      OR pg_catalog.pg_has_role(session_user,'predictive_recorder','MEMBER')) THEN
    RAISE EXCEPTION 'predictive-source-witness-not-authorized' USING ERRCODE='42501'; END IF;
  RETURN public.predictive_source_witness_at(req,pg_catalog.date_trunc('milliseconds',pg_catalog.clock_timestamp()));
END
$$;
REVOKE ALL ON FUNCTION public.predictive_source_witness_at(jsonb,timestamptz),
  public.predictive_source_witness_check(jsonb,timestamptz,boolean),public.predictive_source_witness(jsonb) FROM PUBLIC;
DO $grants$
DECLARE role_name text;
BEGIN
  FOREACH role_name IN ARRAY ARRAY['predictive_replay','predictive_recorder'] LOOP
    IF EXISTS (SELECT 1 FROM pg_catalog.pg_roles WHERE rolname=role_name) THEN
      EXECUTE format('GRANT EXECUTE ON FUNCTION public.predictive_source_witness(jsonb) TO %I',role_name); END IF;
  END LOOP;
END
$grants$;
